import React, { useState, useEffect } from 'react';
import { ArrowRightLeft, TrendingUp, RefreshCw, AlertTriangle, ExternalLink } from 'lucide-react';
import { Exchange, ArbitrageOpportunity } from '../types';
import { CEX_LIST, INITIAL_ARB_OPPS } from '../constants';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';

const CexDashboard: React.FC = () => {
  const [opportunities, setOpportunities] = useState<ArbitrageOpportunity[]>(INITIAL_ARB_OPPS);
  const [isScanning, setIsScanning] = useState(false);

  const scanMarket = () => {
    setIsScanning(true);
    // Simulate API call delay
    setTimeout(() => {
      // Shuffle prices slightly
      const newOpps = opportunities.map(opp => ({
        ...opp,
        buyPrice: opp.buyPrice * (1 + (Math.random() * 0.01 - 0.005)),
        sellPrice: opp.sellPrice * (1 + (Math.random() * 0.01 - 0.005)),
        timestamp: Date.now()
      })).map(opp => ({
        ...opp,
        spread: ((opp.sellPrice - opp.buyPrice) / opp.buyPrice) * 100,
        profitPotential: (opp.sellPrice - opp.buyPrice)
      }));
      setOpportunities(newOpps);
      setIsScanning(false);
    }, 1500);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
      {/* Header Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {CEX_LIST.slice(0, 4).map((ex) => (
          <div key={ex.id} className="bg-surface border border-slate-800 p-4 rounded-xl flex items-center gap-4">
            <img src={ex.logo} alt={ex.name} className="w-10 h-10 rounded-full bg-slate-700" />
            <div>
              <h3 className="font-bold text-slate-200">{ex.name}</h3>
              <p className="text-xs text-slate-400">Vol: <span className="text-primary">{ex.volume24h}</span></p>
            </div>
            <div className={`ml-auto w-2 h-2 rounded-full ${ex.status === 'active' ? 'bg-accent shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-red-500'}`}></div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Scanner Panel */}
        <div className="lg:col-span-2 bg-surface border border-slate-800 rounded-2xl overflow-hidden shadow-xl">
          <div className="p-6 border-b border-slate-800 flex justify-between items-center bg-gradient-to-r from-surface to-slate-900">
            <div>
              <h2 className="text-xl font-bold text-white flex items-center gap-2">
                <ArrowRightLeft className="text-primary" /> Arbitrage Scanner
              </h2>
              <p className="text-sm text-slate-400">Real-time price discrepancies across CEXs</p>
            </div>
            <button 
              onClick={scanMarket}
              disabled={isScanning}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-semibold transition-all ${isScanning ? 'bg-slate-700 text-slate-400' : 'bg-primary text-white hover:bg-blue-600 shadow-lg shadow-blue-500/20'}`}
            >
              <RefreshCw className={`w-4 h-4 ${isScanning ? 'animate-spin' : ''}`} />
              {isScanning ? 'Scanning...' : 'Scan Now'}
            </button>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm text-slate-300">
              <thead className="bg-slate-900/50 text-slate-400 uppercase text-xs">
                <tr>
                  <th className="px-6 py-4">Pair</th>
                  <th className="px-6 py-4">Buy At</th>
                  <th className="px-6 py-4">Sell At</th>
                  <th className="px-6 py-4 text-right">Spread</th>
                  <th className="px-6 py-4 text-right">Profit Est.</th>
                  <th className="px-6 py-4 text-center">Action</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800">
                {opportunities.map((opp) => (
                  <tr key={opp.id} className="hover:bg-slate-800/30 transition-colors">
                    <td className="px-6 py-4 font-bold text-white">{opp.pair}</td>
                    <td className="px-6 py-4">
                      <div className="flex flex-col">
                        <span className="font-mono text-accent">${opp.buyPrice.toLocaleString()}</span>
                        <span className="text-xs text-slate-500">{opp.buyExchange}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex flex-col">
                        <span className="font-mono text-danger">${opp.sellPrice.toLocaleString()}</span>
                        <span className="text-xs text-slate-500">{opp.sellExchange}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-right font-mono text-accent">+{opp.spread.toFixed(2)}%</td>
                    <td className="px-6 py-4 text-right font-mono font-bold text-white">${opp.profitPotential.toFixed(2)}</td>
                    <td className="px-6 py-4 text-center">
                      <button className="text-primary hover:text-white transition-colors">
                        <ExternalLink className="w-5 h-5 mx-auto" />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Analytics / Chart */}
        <div className="bg-surface border border-slate-800 rounded-2xl p-6 flex flex-col shadow-xl">
           <h3 className="text-lg font-bold text-white mb-6 flex items-center gap-2">
            <TrendingUp className="text-accent" /> Spread Analysis
          </h3>
          <div className="flex-1 min-h-[200px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={opportunities}>
                <XAxis dataKey="pair" stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} />
                <YAxis stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155', color: '#f8fafc' }}
                  cursor={{fill: '#334155', opacity: 0.2}}
                />
                <Bar dataKey="spread" radius={[4, 4, 0, 0]}>
                   {opportunities.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={entry.spread > 1.5 ? '#10b981' : '#3b82f6'} />
                    ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
          <div className="mt-6 bg-yellow-500/10 border border-yellow-500/20 rounded-lg p-3">
            <div className="flex items-start gap-3">
                <AlertTriangle className="w-5 h-5 text-yellow-500 shrink-0 mt-0.5" />
                <p className="text-xs text-yellow-200">
                    <strong>Risk Warning:</strong> Transfer times between exchanges may affect arbitrage execution. Always verify withdrawal statuses.
                </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CexDashboard;

import React, { useState } from 'react';
import { Zap, Layers, Settings, ChevronRight, Activity, ArrowDown } from 'lucide-react';
import { DEX_LIST } from '../constants';

const DexDashboard: React.FC = () => {
  const [loanAmount, setLoanAmount] = useState<string>('1000');
  const [selectedToken, setSelectedToken] = useState('ETH');
  const [executing, setExecuting] = useState(false);
  const [log, setLog] = useState<string[]>([]);

  const executeFlashLoan = () => {
    if (!loanAmount) return;
    setExecuting(true);
    setLog([]);

    const steps = [
      `Initiating Transaction on Aave V3...`,
      `Borrowing ${loanAmount} ${selectedToken} (Flash Loan)`,
      `Routing via Uniswap V3: Swapping ${selectedToken} -> USDC`,
      `Price Impact: 0.05%`,
      `Arbitrage found on Curve: USDC -> ${selectedToken}`,
      `Executing Swap on Curve Finance...`,
      `Repaying Flash Loan + 0.09% Fee`,
      `Transaction Confirmed: Block #19248512`
    ];

    let currentStep = 0;
    const interval = setInterval(() => {
      if (currentStep >= steps.length) {
        clearInterval(interval);
        setExecuting(false);
        setLog(prev => [...prev, `✅ SUCCESS: Profit Generated: ${(parseFloat(loanAmount) * 0.004).toFixed(4)} ${selectedToken}`]);
      } else {
        setLog(prev => [...prev, steps[currentStep]]);
        currentStep++;
      }
    }, 800);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
        {DEX_LIST.map((dex) => (
          <div key={dex.id} className="bg-surface border border-slate-800 p-4 rounded-xl hover:border-slate-600 transition-colors cursor-pointer group">
            <div className="flex justify-between items-start mb-2">
              <img src={dex.logo} alt={dex.name} className="w-8 h-8 rounded-full" />
              <ExternalLinkIcon className="w-4 h-4 text-slate-600 group-hover:text-secondary" />
            </div>
            <h3 className="font-bold text-slate-200">{dex.name}</h3>
            <div className="flex justify-between items-center mt-2 text-xs">
               <span className="text-slate-500">TVL</span>
               <span className="text-slate-300 font-mono">{dex.volume24h}</span>
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        {/* Flash Loan Builder */}
        <div className="lg:col-span-7 bg-surface border border-slate-800 rounded-2xl p-6 shadow-xl relative overflow-hidden">
          <div className="absolute top-0 right-0 p-4 opacity-10 pointer-events-none">
            <Zap className="w-64 h-64 text-secondary" />
          </div>

          <h2 className="text-xl font-bold text-white mb-6 flex items-center gap-2">
            <Zap className="text-yellow-400 fill-yellow-400" /> Flash Loan Simulator
          </h2>

          <div className="space-y-6 relative z-10">
            <div className="bg-slate-900/50 p-4 rounded-xl border border-slate-700">
              <label className="text-xs text-slate-400 uppercase font-bold tracking-wider mb-2 block">1. Borrow Asset</label>
              <div className="flex gap-4">
                <input 
                  type="number" 
                  value={loanAmount}
                  onChange={(e) => setLoanAmount(e.target.value)}
                  className="flex-1 bg-transparent text-2xl font-mono text-white outline-none placeholder-slate-600"
                  placeholder="0.00"
                />
                <select 
                  value={selectedToken}
                  onChange={(e) => setSelectedToken(e.target.value)}
                  className="bg-slate-800 text-white rounded-lg px-4 py-2 outline-none border border-slate-600 focus:border-secondary"
                >
                  <option value="ETH">ETH</option>
                  <option value="USDC">USDC</option>
                  <option value="DAI">DAI</option>
                  <option value="WBTC">WBTC</option>
                </select>
              </div>
            </div>

            <div className="flex justify-center -my-3 relative z-20">
              <div className="bg-slate-800 rounded-full p-2 border border-slate-700">
                <ArrowDown className="w-5 h-5 text-slate-400" />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="bg-slate-900/50 p-4 rounded-xl border border-slate-700 hover:border-secondary/50 transition-colors">
                 <div className="flex items-center gap-2 mb-2">
                    <img src={DEX_LIST[0].logo} className="w-5 h-5 rounded-full" />
                    <span className="text-sm font-semibold text-slate-300">Uniswap V3</span>
                 </div>
                 <div className="text-xs text-slate-500">Route 1: Swap {selectedToken} → USDC</div>
              </div>
              <div className="bg-slate-900/50 p-4 rounded-xl border border-slate-700 hover:border-secondary/50 transition-colors">
                 <div className="flex items-center gap-2 mb-2">
                    <img src={DEX_LIST[2].logo} className="w-5 h-5 rounded-full" />
                    <span className="text-sm font-semibold text-slate-300">Curve</span>
                 </div>
                 <div className="text-xs text-slate-500">Route 2: Swap USDC → {selectedToken}</div>
              </div>
            </div>

            <button 
              onClick={executeFlashLoan}
              disabled={executing}
              className={`w-full py-4 rounded-xl font-bold text-lg shadow-lg flex items-center justify-center gap-2 transition-all
              ${executing 
                ? 'bg-slate-800 text-slate-500 cursor-not-allowed' 
                : 'bg-gradient-to-r from-secondary to-purple-600 hover:from-secondary/90 hover:to-purple-600/90 text-white shadow-purple-500/20'
              }`}
            >
              {executing ? (
                <>Processing Block <Activity className="w-5 h-5 animate-spin" /></>
              ) : (
                <>Execute Flash Loan Transaction</>
              )}
            </button>
          </div>
        </div>

        {/* Execution Log */}
        <div className="lg:col-span-5 bg-black border border-slate-800 rounded-2xl p-0 overflow-hidden flex flex-col h-full shadow-xl">
           <div className="p-4 border-b border-slate-800 bg-slate-900/50 flex justify-between items-center">
              <h3 className="font-mono text-sm font-bold text-slate-400">TX TERMINAL</h3>
              <div className="flex gap-1.5">
                <div className="w-3 h-3 rounded-full bg-red-500/20 border border-red-500/50"></div>
                <div className="w-3 h-3 rounded-full bg-yellow-500/20 border border-yellow-500/50"></div>
                <div className="w-3 h-3 rounded-full bg-green-500/20 border border-green-500/50"></div>
              </div>
           </div>
           <div className="p-4 font-mono text-xs space-y-2 overflow-y-auto flex-1 max-h-[400px]">
              {log.length === 0 && !executing && (
                <div className="text-slate-600 italic text-center mt-10">Waiting for execution parameters...</div>
              )}
              {log.map((line, i) => (
                <div key={i} className={`pb-1 border-b border-dashed border-slate-900 ${line.includes('SUCCESS') ? 'text-green-400 font-bold' : 'text-slate-300'}`}>
                  <span className="text-slate-600 mr-2">[{new Date().toLocaleTimeString()}]</span>
                  {line}
                </div>
              ))}
              {executing && (
                <div className="text-secondary animate-pulse">_</div>
              )}
           </div>
        </div>
      </div>
    </div>
  );
};

