// Public Project ID for demo purposes. In production, this should be replaced with a key from cloud.walletconnect.com
const WC_PROJECT_ID = 'c3e53625345719326a26c4897f1025d5';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<'CEX' | 'DEX'>('CEX');
  const [isWalletModalOpen, setIsWalletModalOpen] = useState(false);
  const [activeWallet, setActiveWallet] = useState<Wallet | null>(null);

  const handleConnectWallet = async (wallet: Wallet) => {
    try {
      if (wallet.id === 'metamask') {
        const ethereum = (window as any).ethereum;
        if (ethereum) {
          const provider = new BrowserProvider(ethereum);
          await provider.send("eth_requestAccounts", []);
          const signer = await provider.getSigner();
          const address = await signer.getAddress();
          const balanceBigInt = await provider.getBalance(address);

          setActiveWallet({
            ...wallet,
            connected: true,
            address: `${address.slice(0, 6)}...${address.slice(-4)}`,
            balance: `${parseFloat(formatEther(balanceBigInt)).toFixed(4)} ETH`
          });
        } else {
          alert("MetaMask not detected. Using simulation mode.");
          await simulateConnection(wallet);
        }
      } else if (wallet.id === 'phantom') {
        const solana = (window as any).solana;
        if (solana && solana.isPhantom) {
          const response = await solana.connect();
          const address = response.publicKey.toString();

          setActiveWallet({
            ...wallet,
            connected: true,
            address: `${address.slice(0, 6)}...${address.slice(-4)}`,
            balance: '14.5 SOL'
          });
        } else {
           alert("Phantom not detected. Using simulation mode.");
           await simulateConnection(wallet);
        }
      } else if (wallet.id === 'walletconnect') {
        try {
          const provider = await EthereumProvider.init({
            projectId: WC_PROJECT_ID,
            showQrModal: true,
            chains: [1], // Mainnet
            methods: ["eth_sendTransaction", "personal_sign"],
            events: ["chainChanged", "accountsChanged"],
          });

          await provider.connect();

          const ethersProvider = new BrowserProvider(provider);
          const signer = await ethersProvider.getSigner();
          const address = await signer.getAddress();
          const balance = await ethersProvider.getBalance(address);

