            ...wallet,
            connected: true,
            address: `${address.slice(0, 6)}...${address.slice(-4)}`,
            balance: `${parseFloat(formatEther(balance)).toFixed(4)} ETH`
          });
        } catch (wcError) {
          console.error("WalletConnect Error:", wcError);
          throw wcError;
        }
      } else {
        await simulateConnection(wallet);
      }
