const CexDashboard: React.FC = () => {
  const [opportunities, setOpportunities] = useState<ArbitrageOpportunity[]>(INITIAL_ARB_OPPS);
  const [isScanning, setIsScanning] = useState(false);
  const [tradeStatuses, setTradeStatuses] = useState<Record<string, 'idle' | 'loading' | 'success'>>({});

  const scanMarket = () => {
    setIsScanning(true);
    // Simulate API call delay
    setTimeout(() => {
      // Shuffle prices slightly
      const newOpps = opportunities.map(opp => ({
        ...opp,
        buyPrice: opp.buyPrice * (1 + (Math.random() * 0.01 - 0.005)),
        sellPrice: opp.sellPrice * (1 + (Math.random() * 0.01 - 0.005)),
        timestamp: Date.now()
      })).map(opp => ({
        ...opp,
        spread: ((opp.sellPrice - opp.buyPrice) / opp.buyPrice) * 100,
        profitPotential: (opp.sellPrice - opp.buyPrice)
      }));
      setOpportunities(newOpps);
      setIsScanning(false);
    }, 1500);
  };

  const handleTrade = (id: string) => {
    setTradeStatuses(prev => ({ ...prev, [id]: 'loading' }));

    // Simulate Trade Execution API call
    setTimeout(() => {
      setTradeStatuses(prev => ({ ...prev, [id]: 'success' }));

      // Reset status after showing success message
      setTimeout(() => {
        setTradeStatuses(prev => {
          const newState = { ...prev };
          delete newState[id];
          return newState;
        });
      }, 3000);
    }, 2000);
  };

  return (
