import { GoogleGenAI } from "@google/genai";

const apiKey = process.env.API_KEY || '';

// Initialize only if key exists.
const ai = apiKey ? new GoogleGenAI({ apiKey }) : null;

export const generateAiResponse = async (
  prompt: string,
  context: string,
  history: { role: string; text: string }[]
): Promise<string> => {
  if (!ai) {
    return "API Key is missing. Please check your environment variables.";
  }

  try {
    // Determine complexity based on keywords or length to switch models
    const isComplexQuery = /analyze|strategy|prediction|forecast|complex|reasoning|audit/i.test(prompt) || prompt.length > 80;

    let model = 'gemini-2.5-flash-lite-preview-02-04'; // Default: Fast, low-latency
    let config = {};

    if (isComplexQuery) {
      model = 'gemini-3-pro-preview'; // Complex tasks
      config = {
        thinkingConfig: { thinkingBudget: 32768 }
      };
    }

    const systemInstruction = `You are NexusAI, an advanced, highly intelligent crypto trading assistant monitoring a terminal. 
    You watch over both CEX (Centralized) and DEX (Decentralized) activities. 
    Your tone is professional, technical, slightly futuristic, and concise.
    Current App State/Context: ${context}`;

    // Construct the full prompt content including history context if needed, 
    // but for this stateless function, we'll append recent history to the prompt text for context window.

    const recentHistory = history.slice(-3).map(h => `${h.role}: ${h.text}`).join('\n');
    const fullContent = `${systemInstruction}\n\nRecent Context:\n${recentHistory}\n\nUser Query: ${prompt}`;

    const response = await ai.models.generateContent({
      model: model,
      contents: fullContent,
      config: config
    });

    return response.text || "I processed the data but could not generate a verbal response.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "System alert: AI Connection interrupted. Please try again.";
  }
};

import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import CexDashboard from './components/CexDashboard';
import DexDashboard from './components/DexDashboard';
import AiAssistant from './components/AiAssistant';
import WalletModal from './components/WalletModal';
import { Wallet } from './types';
import { BrowserProvider, formatEther } from 'ethers';
import { EthereumProvider } from '@walletconnect/ethereum-provider';

// Public Project ID for demo purposes.
const WC_PROJECT_ID = 'c3e53625345719326a26c4897f1025d5';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<'CEX' | 'DEX'>('CEX');
  const [isWalletModalOpen, setIsWalletModalOpen] = useState(false);
  const [activeWallet, setActiveWallet] = useState<Wallet | null>(null);
  const [connectionError, setConnectionError] = useState<string | null>(null);

  // Attempt to restore connection on mount (simplified)
  useEffect(() => {
    const savedWalletId = localStorage.getItem('connectedWalletId');
    if (savedWalletId && savedWalletId === 'metamask') {
       // Silent reconnect logic could go here
    }
  }, []);

  const handleConnectWallet = async (wallet: Wallet) => {
    setConnectionError(null);
    try {
      if (wallet.id === 'metamask') {
        const ethereum = (window as any).ethereum;
        if (!ethereum) {
           throw new Error("MetaMask is not installed.");
        }

        const provider = new BrowserProvider(ethereum);
        // Request accounts (this triggers the popup)
        await provider.send("eth_requestAccounts", []);
        const signer = await provider.getSigner();
        const address = await signer.getAddress();
        const balanceBigInt = await provider.getBalance(address);

        setActiveWallet({
          ...wallet,
          connected: true,
          address: `${address.slice(0, 6)}...${address.slice(-4)}`,
          balance: `${parseFloat(formatEther(balanceBigInt)).toFixed(4)} ETH`
        });
        localStorage.setItem('connectedWalletId', wallet.id);

      } else if (wallet.id === 'phantom') {
        const solana = (window as any).solana;
        if (!solana || !solana.isPhantom) {
           throw new Error("Phantom wallet is not installed.");
        }

        const response = await solana.connect();
        const address = response.publicKey.toString();

        setActiveWallet({
          ...wallet,
          connected: true,
          address: `${address.slice(0, 6)}...${address.slice(-4)}`,
          balance: '14.5 SOL' // Mock balance for Solana as it requires extra connection logic
        });
        localStorage.setItem('connectedWalletId', wallet.id);

      } else if (wallet.id === 'walletconnect') {
        try {
          const provider = await EthereumProvider.init({
            projectId: WC_PROJECT_ID,
            showQrModal: true,
            chains: [1], 
            methods: ["eth_sendTransaction", "personal_sign"],
            events: ["chainChanged", "accountsChanged"],
          });

          await provider.connect();

          const ethersProvider = new BrowserProvider(provider);
          const signer = await ethersProvider.getSigner();
          const address = await signer.getAddress();
          const balance = await ethersProvider.getBalance(address);

          setActiveWallet({
            ...wallet,
            connected: true,
            address: `${address.slice(0, 6)}...${address.slice(-4)}`,
            balance: `${parseFloat(formatEther(balance)).toFixed(4)} ETH`
          });
          localStorage.setItem('connectedWalletId', wallet.id);
        } catch (wcError: any) {
          console.error("WalletConnect Error:", wcError);
          // Clean up if possible or just throw
          throw new Error(wcError.message || "WalletConnect failed to initialize.");
        }
      } else {
        await simulateConnection(wallet);
      }
    } catch (error: any) {
      console.error("Connection failed:", error);
      if (error.code === 4001 || error.message?.includes('User rejected')) {
         setConnectionError("Connection rejected by user.");
      } else {
         setConnectionError(error.message || "Failed to connect wallet.");
         // Fallback to simulation if desired, or just show error.
         // For this demo, if extension is missing, we simulate.
         if (error.message.includes("not installed")) {
             alert(`${error.message} Switching to Simulation Mode.`);
             await simulateConnection(wallet);
             setConnectionError(null); // Clear error if simulation succeeds
         }
      }
      throw error; // Re-throw to let Modal know
    }
  };

  const simulateConnection = (wallet: Wallet) => {
    return new Promise<void>((resolve) => {
      setTimeout(() => {
        setActiveWallet({ 
          ...wallet, 
          connected: true, 
          address: '0x71C...9A21', 
          balance: wallet.id === 'phantom' ? '124.5 SOL' : '14.5 ETH' 
        });
        localStorage.setItem('connectedWalletId', wallet.id);
        resolve();
      }, 800);
    });
  };

  const handleDisconnect = () => {
    setActiveWallet(null);
    localStorage.removeItem('connectedWalletId');
    // Implement specific provider disconnect logic if needed
  };

  return (
    <div className="min-h-screen bg-background text-slate-200 font-sans selection:bg-primary/30">
      <Navbar 
        activeView={activeView} 
        setActiveView={setActiveView} 
        activeWallet={activeWallet}
        onConnectClick={() => setIsWalletModalOpen(true)}
      />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 pb-32">
        <div className="mb-8">
          <h2 className="text-3xl font-bold text-white mb-2">
            {activeView === 'CEX' ? 'Global Exchange Monitor' : 'DeFi Liquidity Terminal'}
          </h2>
          <p className="text-slate-400">
            {activeView === 'CEX' 
              ? 'Scan centralized order books for arbitrage spreads across major exchanges.' 
              : 'Execute flash loans and analyze liquidity pools across decentralized protocols.'}
          </p>
        </div>

        {activeView === 'CEX' ? <CexDashboard /> : <DexDashboard />}
      </main>

      <AiAssistant currentContext={activeView} />

      <WalletModal 
        isOpen={isWalletModalOpen} 
        onClose={() => { setIsWalletModalOpen(false); setConnectionError(null); }}
        activeWallet={activeWallet}
        onConnect={handleConnectWallet}
        error={connectionError}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { X, Wallet as WalletIcon, CheckCircle2, Loader2, ArrowRight, AlertCircle } from 'lucide-react';
import { Wallet } from '../types';
import { WALLETS } from '../constants';

interface WalletModalProps {
  isOpen: boolean;
  onClose: () => void;
  activeWallet: Wallet | null;
  onConnect: (wallet: Wallet) => Promise<void>;
  error?: string | null;
}

const WalletModal: React.FC<WalletModalProps> = ({ isOpen, onClose, activeWallet, onConnect, error: propError }) => {
  const [connectingWalletId, setConnectingWalletId] = useState<string | null>(null);
  const [localError, setLocalError] = useState<string | null>(null);

  // Sync prop error to local error
  useEffect(() => {
    if (propError) setLocalError(propError);
  }, [propError]);

  if (!isOpen) return null;

  const handleConnect = async (wallet: Wallet) => {
    setConnectingWalletId(wallet.id);
    setLocalError(null);
    try {
      await onConnect(wallet);
      onClose();
    } catch (error) {
      // Error is handled in App.tsx and passed back via prop or state, 
      // but we catch here to stop loading state.
      console.error("Connection attempt finished with error");
    } finally {
      setConnectingWalletId(null);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
      <div className="bg-surface border border-slate-700 w-full max-w-md rounded-2xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
        <div className="p-4 border-b border-slate-700 flex justify-between items-center bg-slate-900/50">
