import { GoogleGenAI } from "@google/genai";

// Safely access apiKey preventing crashes if process is undefined in browser
const apiKey = (typeof process !== 'undefined' && process.env) ? process.env.API_KEY : '';

// Initialize only if key exists.
const ai = apiKey ? new GoogleGenAI({ apiKey }) : null;

export interface AiResponse {
  text: string;
  sources?: { title: string; uri: string }[];
  isThinking?: boolean;
}

export const generateAiResponse = async (
  prompt: string,
  context: string,
  history: { role: string; text: string }[]
): Promise<AiResponse> => {
  if (!ai) {
    return { text: "API Key is missing. Please check your environment variables." };
  }

  try {
    // Determine complexity based on keywords
    const isComplexQuery = /audit|verify|check|real|strategy|prediction|forecast|complex|reasoning|risk|calculate/i.test(prompt) || prompt.length > 80;

    let model = 'gemini-3-flash-preview'; // Default: Fast + Search
    let config: any = {
      tools: [{ googleSearch: {} }] // Enable search by default for up-to-date market info
    };

    // Use Thinking Mode for complex tasks
    if (isComplexQuery) {
      model = 'gemini-3-pro-preview'; 
      config = {
        thinkingConfig: { thinkingBudget: 32768 } // Max budget for deep reasoning
        // Do not use googleSearch with thinking models in this specific configuration if focusing on pure reasoning, 
        // OR if the API supports it, use it. For this instruction, we focus on Thinking for complex logic.
        // We remove search tool for pure thinking tasks to adhere to "Think more when needed" strict instructions.
      };
    }

    const systemInstruction = `You are NexusAI, an advanced, highly intelligent crypto trading assistant monitoring a terminal. 
    You watch over both CEX (Centralized) and DEX (Decentralized) activities. 
    Your tone is professional, technical, slightly futuristic, and concise.
    Current App State/Context: ${context}`;

    const recentHistory = history.slice(-3).map(h => `${h.role}: ${h.text}`).join('\n');
    const fullContent = `${systemInstruction}\n\nRecent Context:\n${recentHistory}\n\nUser Query: ${prompt}`;

    const response = await ai.models.generateContent({
      model: model,
      contents: fullContent,
      config: config
    });

    let sources: { title: string; uri: string }[] = [];

    // Extract Grounding (Search) Data if available
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (groundingChunks) {
      groundingChunks.forEach((chunk: any) => {
        if (chunk.web?.uri) {
          sources.push({
            title: chunk.web.title || "Source",
            uri: chunk.web.uri
          });
        }
      });
    }

    return {
      text: response.text || "I processed the data but could not generate a verbal response.",
      sources: sources.length > 0 ? sources : undefined,
      isThinking: isComplexQuery
    };

  } catch (error) {
    console.error("Gemini API Error:", error);
    return { text: "System alert: AI Connection interrupted. Please try again." };
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Bot, Send, Minimize2, Maximize2, Sparkles, BrainCircuit, ExternalLink, Globe, Brain } from 'lucide-react';
import { ChatMessage } from '../types';
import { generateAiResponse, AiResponse } from '../services/geminiService';

interface ExtendedChatMessage extends ChatMessage {
  sources?: { title: string; uri: string }[];
  isThinking?: boolean;
}

interface AiAssistantProps {
  currentContext: string;
}

const AiAssistant: React.FC<AiAssistantProps> = ({ currentContext }) => {
  const [isOpen, setIsOpen] = useState(true);
  const [messages, setMessages] = useState<ExtendedChatMessage[]>([
    { id: 'init', role: 'model', text: 'NexusAI online. Monitoring market conditions. How can I assist your trading strategy today?', timestamp: new Date() }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [loadingMode, setLoadingMode] = useState<'thinking' | 'searching' | 'default'>('default');
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isOpen]);

  // Expose a method for other components to trigger the AI
  useEffect(() => {
    (window as any).triggerNexusAi = (prompt: string) => {
      if(!isOpen) setIsOpen(true);
      setInput(prompt);
      // Optional: Auto-send could be implemented here, but pre-filling input is safer for user intent
    };
  }, [isOpen]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: ExtendedChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    // Guess mode for UI feedback before API confirms
    if (input.toLowerCase().includes('audit') || input.toLowerCase().includes('plan')) {
      setLoadingMode('thinking');
    } else {
      setLoadingMode('searching');
    }

    // Format history for the service
    const history = messages.map(m => ({ role: m.role, text: m.text }));

    const response: AiResponse = await generateAiResponse(userMsg.text, currentContext, history);

    const aiMsg: ExtendedChatMessage = {
      id: (Date.now() + 1).toString(),
      role: 'model',
      text: response.text,
      sources: response.sources,
      isThinking: response.isThinking,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, aiMsg]);
    setIsLoading(false);
    setLoadingMode('default');
  };

  if (!isOpen) {
    return (
      <button 
        onClick={() => setIsOpen(true)}
        className="fixed bottom-6 right-6 bg-purple-600 hover:bg-purple-500 text-white p-4 rounded-full shadow-2xl shadow-purple-500/30 transition-all z-40 animate-bounce"
      >
        <Bot className="w-8 h-8" />
      </button>
    );
  }

  return (
    <div className="fixed bottom-6 right-6 w-[380px] h-[600px] bg-surface/95 backdrop-blur-md border border-purple-500/30 rounded-2xl shadow-2xl flex flex-col overflow-hidden z-40 animate-in slide-in-from-bottom-10 duration-300">
      {/* Header */}
      <div className="p-4 bg-gradient-to-r from-purple-900/50 to-slate-900 border-b border-purple-500/20 flex justify-between items-center">
        <div className="flex items-center gap-3">
          <div className="relative">
            <div className="w-2 h-2 absolute -right-0.5 -top-0.5 bg-green-500 rounded-full animate-pulse"></div>
            <BrainCircuit className="w-6 h-6 text-purple-400" />
          </div>
          <div>
            <h3 className="font-bold text-slate-100 text-sm">NexusAI Overseer</h3>
            <p className="text-[10px] text-purple-300 flex items-center gap-1">
              <Sparkles className="w-3 h-3" /> Gemini 3 Core Active
            </p>
          </div>
        </div>
        <button onClick={() => setIsOpen(false)} className="text-slate-400 hover:text-white">
          <Minimize2 className="w-5 h-5" />
        </button>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-black/20" ref={scrollRef}>
        {messages.map((msg) => (
          <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
            <div 
              className={`max-w-[85%] p-3 rounded-2xl text-sm leading-relaxed
                ${msg.role === 'user' 
                  ? 'bg-purple-600 text-white rounded-br-none' 
                  : 'bg-slate-800 text-slate-200 border border-slate-700 rounded-bl-none'
                }`}
            >
              {msg.text}
            </div>

            {/* Sources Display */}
            {msg.sources && msg.sources.length > 0 && (
              <div className="mt-2 flex flex-wrap gap-2 max-w-[85%]">
                {msg.sources.slice(0, 3).map((source, idx) => (
                  <a 
                    key={idx}
                    href={source.uri}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center gap-1 text-[10px] bg-slate-900/80 text-blue-400 border border-slate-700 px-2 py-1 rounded-md hover:bg-slate-800 transition-colors"
                  >
                    <Globe className="w-3 h-3" />
                    <span className="truncate max-w-[100px]">{source.title}</span>
                  </a>
                ))}
              </div>
            )}

            {/* Thinking Indicator for completed messages */}
            {msg.isThinking && (
              <span className="text-[10px] text-purple-400/50 mt-1 flex items-center gap-1">
                <Brain className="w-3 h-3" /> Thought Process Complete
              </span>
            )}
          </div>
        ))}

        {isLoading && (
           <div className="flex justify-start">
             <div className="bg-slate-800 p-3 rounded-2xl rounded-bl-none border border-slate-700">
               <div className="flex items-center gap-2">
                 {loadingMode === 'thinking' ? (
                   <>
                    <Brain className="w-4 h-4 text-purple-500 animate-pulse" />
                    <span className="text-xs text-purple-300">Reasoning...</span>
                   </>
                 ) : (
                   <>
                    <Globe className="w-4 h-4 text-blue-500 animate-spin" />
                    <span className="text-xs text-blue-300">Searching Live Data...</span>
                   </>
                 )}
               </div>
             </div>
           </div>
        )}
      </div>

      {/* Input */}
      <div className="p-4 bg-slate-900 border-t border-slate-800">
        <div className="relative">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Ask AI to audit, verify, or explain..."
            className="w-full bg-slate-800 border border-slate-700 text-white rounded-xl pl-4 pr-12 py-3 focus:outline-none focus:border-purple-500 transition-colors placeholder-slate-500 text-sm"
          />
          <button 
            onClick={handleSend}
            disabled={isLoading || !input.trim()}
            className="absolute right-2 top-2 p-1.5 bg-purple-600 hover:bg-purple-500 rounded-lg text-white transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <Send className="w-4 h-4" />
          </button>
        </div>
        <div className="mt-2 flex justify-center">
            <span className="text-[10px] text-slate-600">AI monitors real-time context from {currentContext}</span>
        </div>
      </div>
    </div>
  );
};

