                   <div className="flex flex-col items-center px-4">
                      <ArrowRightLeft className="w-5 h-5 text-slate-600 mb-1" />
                      <span className="text-xs font-bold text-slate-500">{confirmingTrade.pair}</span>
                   </div>
                   <div className="flex flex-col items-end">
                      <span className="text-xs text-slate-400 uppercase font-bold tracking-wider">Selling At</span>
                      <span className="text-lg font-bold text-white">{confirmingTrade.sellExchange}</span>
                      <span className="text-sm font-mono text-red-400">${confirmingTrade.sellPrice.toLocaleString(undefined, { maximumFractionDigits: 2 })}</span>
                   </div>
                </div>

                <div className="bg-slate-900/50 rounded-xl p-4 border border-slate-800 mb-6">
                   <div className="flex justify-between items-center mb-2">
                      <span className="text-sm text-slate-400">Spread</span>
