const DexDashboard: React.FC = () => {
  const [loanAmount, setLoanAmount] = useState<string>('1000');
  const [selectedToken, setSelectedToken] = useState('ETH');
  const [executing, setExecuting] = useState(false);
  const [log, setLog] = useState<string[]>([]);
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, []);

  const executeFlashLoan = () => {
    if (!loanAmount) return;
    if (intervalRef.current) clearInterval(intervalRef.current);

    setExecuting(true);
    setLog([]);

    const steps = [
      `Initiating Transaction on Aave V3...`,
      `Borrowing ${loanAmount} ${selectedToken} (Flash Loan)`,
      `Routing via Uniswap V3: Swapping ${selectedToken} -> USDC`,
      `Price Impact: 0.05%`,
      `Arbitrage found on Curve: USDC -> ${selectedToken}`,
      `Executing Swap on Curve Finance...`,
      `Repaying Flash Loan + 0.09% Fee`,
      `Transaction Confirmed: Block #19248512`
    ];

    let currentStep = 0;

    intervalRef.current = setInterval(() => {
      if (currentStep >= steps.length) {
        if (intervalRef.current) clearInterval(intervalRef.current);
        setExecuting(false);
        setLog(prev => [...prev, `✅ SUCCESS: Profit Generated: ${(parseFloat(loanAmount) * 0.004).toFixed(4)} ${selectedToken}`]);
      } else {
        const step = steps[currentStep];
        if (step) {
            setLog(prev => [...prev, step]);
        }
        currentStep++;
      }
    }, 800);
  };

  const handleAiAudit = () => {
    const prompt = `Audit this flash loan route using deep reasoning: Borrow ${loanAmount} ${selectedToken} from Aave -> Swap on Uniswap V3 -> Swap back on Curve. Calculate potential gas fees, slippage risks, and MEV (Miner Extractable Value) threats. Is this profitable?`;
    if ((window as any).triggerNexusAi) {
      (window as any).triggerNexusAi(prompt);
    }
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
        {DEX_LIST.map((dex) => (
          <div key={dex.id} className="bg-surface border border-slate-800 p-4 rounded-xl hover:border-slate-600 transition-colors cursor-pointer group">
            <div className="flex justify-between items-start mb-2">
              <img src={dex.logo} alt={dex.name} className="w-8 h-8 rounded-full" />
              <ExternalLinkIcon className="w-4 h-4 text-slate-600 group-hover:text-secondary" />
            </div>
            <h3 className="font-bold text-slate-200">{dex.name}</h3>
            <div className="flex justify-between items-center mt-2 text-xs">
               <span className="text-slate-500">TVL</span>
               <span className="text-slate-300 font-mono">{dex.volume24h}</span>
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        {/* Flash Loan Builder */}
        <div className="lg:col-span-7 bg-surface border border-slate-800 rounded-2xl p-6 shadow-xl relative overflow-hidden">
          <div className="absolute top-0 right-0 p-4 opacity-10 pointer-events-none">
            <Zap className="w-64 h-64 text-secondary" />
          </div>

          <h2 className="text-xl font-bold text-white mb-6 flex items-center gap-2">
            <Zap className="text-yellow-400 fill-yellow-400" /> Flash Loan Simulator
          </h2>

          <div className="space-y-6 relative z-10">
            <div className="bg-slate-900/50 p-4 rounded-xl border border-slate-700">
              <label className="text-xs text-slate-400 uppercase font-bold tracking-wider mb-2 block">1. Borrow Asset</label>
              <div className="flex gap-4">
                <input 
                  type="number" 
                  value={loanAmount}
                  onChange={(e) => setLoanAmount(e.target.value)}
                  className="flex-1 bg-transparent text-2xl font-mono text-white outline-none placeholder-slate-600"
                  placeholder="0.00"
                />
                <select 
                  value={selectedToken}
                  onChange={(e) => setSelectedToken(e.target.value)}
                  className="bg-slate-800 text-white rounded-lg px-4 py-2 outline-none border border-slate-600 focus:border-secondary"
                >
                  <option value="ETH">ETH</option>
                  <option value="USDC">USDC</option>
                  <option value="DAI">DAI</option>
                  <option value="WBTC">WBTC</option>
                </select>
              </div>
            </div>

            <div className="flex justify-center -my-3 relative z-20">
              <div className="bg-slate-800 rounded-full p-2 border border-slate-700">
                <ArrowDown className="w-5 h-5 text-slate-400" />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="bg-slate-900/50 p-4 rounded-xl border border-slate-700 hover:border-secondary/50 transition-colors">
                 <div className="flex items-center gap-2 mb-2">
                    <img src={DEX_LIST[0].logo} className="w-5 h-5 rounded-full" />
                    <span className="text-sm font-semibold text-slate-300">Uniswap V3</span>
                 </div>
                 <div className="text-xs text-slate-500">Route 1: Swap {selectedToken} → USDC</div>
              </div>
              <div className="bg-slate-900/50 p-4 rounded-xl border border-slate-700 hover:border-secondary/50 transition-colors">
                 <div className="flex items-center gap-2 mb-2">
                    <img src={DEX_LIST[2].logo} className="w-5 h-5 rounded-full" />
                    <span className="text-sm font-semibold text-slate-300">Curve</span>
                 </div>
                 <div className="text-xs text-slate-500">Route 2: Swap USDC → {selectedToken}</div>
              </div>
            </div>

            <div className="flex gap-3">
              <button 
                onClick={handleAiAudit}
                className="flex-1 py-4 rounded-xl font-bold text-sm shadow-lg flex items-center justify-center gap-2 bg-purple-600/20 text-purple-400 border border-purple-600/50 hover:bg-purple-600 hover:text-white transition-all"
              >
                <BrainCircuit className="w-5 h-5" /> AI Smart Audit
              </button>

              <button 
                onClick={executeFlashLoan}
                disabled={executing}
                className={`flex-[2] py-4 rounded-xl font-bold text-lg shadow-lg flex items-center justify-center gap-2 transition-all
                ${executing 
                  ? 'bg-slate-800 text-slate-500 cursor-not-allowed' 
                  : 'bg-gradient-to-r from-secondary to-purple-600 hover:from-secondary/90 hover:to-purple-600/90 text-white shadow-purple-500/20'
                }`}
              >
                {executing ? (
                  <>Processing Block <Activity className="w-5 h-5 animate-spin" /></>
                ) : (
                  <>Execute Flash Loan</>
                )}
              </button>
            </div>
          </div>
        </div>

        {/* Execution Log */}
        <div className="lg:col-span-5 bg-black border border-slate-800 rounded-2xl p-0 overflow-hidden flex flex-col h-full shadow-xl">
           <div className="p-4 border-b border-slate-800 bg-slate-900/50 flex justify-between items-center">
              <h3 className="font-mono text-sm font-bold text-slate-400">TX TERMINAL</h3>
              <div className="flex gap-1.5">
                <div className="w-3 h-3 rounded-full bg-red-500/20 border border-red-500/50"></div>
                <div className="w-3 h-3 rounded-full bg-yellow-500/20 border border-yellow-500/50"></div>
                <div className="w-3 h-3 rounded-full bg-green-500/20 border border-green-500/50"></div>
              </div>
           </div>
           <div className="p-4 font-mono text-xs space-y-2 overflow-y-auto flex-1 max-h-[400px]">
              {log.length === 0 && !executing && (
                <div className="text-slate-600 italic text-center mt-10">Waiting for execution parameters...</div>
              )}
              {log.map((line, i) => {
                if (!line) return null;
                return (
                  <div key={i} className={`pb-1 border-b border-dashed border-slate-900 ${line.includes('SUCCESS') ? 'text-green-400 font-bold' : 'text-slate-300'}`}>
                    <span className="text-slate-600 mr-2">[{new Date().toLocaleTimeString()}]</span>
                    {line}
                  </div>
                );
              })}
              {executing && (
                <div className="text-secondary animate-pulse">_</div>
              )}
           </div>
        </div>
      </div>

      <AiAssistant currentContext="DEX Market Analysis: Simulating flash loan execution paths and monitoring liquidity pool depths on Uniswap, Curve, and Balancer." />
    </div>
  );
};

const ExternalLinkIcon = ({ className }: { className?: string }) => (
  <svg className={className} width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/><polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/></svg>
);

export default DexDashboard;

import React, { useState, useEffect } from 'react';
import { ArrowRightLeft, TrendingUp, RefreshCw, AlertTriangle, Play, Loader2, Check, Clock, Filter, X, ShieldCheck, History, Sparkles, Zap, Radio } from 'lucide-react';
import { CEX_LIST, INITIAL_ARB_OPPS } from '../constants';
import { ArbitrageOpportunity } from '../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell, LineChart, Line, CartesianGrid } from 'recharts';
import AiAssistant from './AiAssistant';

const CexDashboard: React.FC = () => {
  const [opportunities, setOpportunities] = useState<ArbitrageOpportunity[]>(INITIAL_ARB_OPPS);
  const [isScanning, setIsScanning] = useState(false);
  const [tradeStatuses, setTradeStatuses] = useState<Record<string, 'idle' | 'loading' | 'success'>>({});
  const [lastUpdated, setLastUpdated] = useState<Date>(new Date());
  const [sortBy, setSortBy] = useState<'profit' | 'spread'>('profit');
  const [confirmingTrade, setConfirmingTrade] = useState<ArbitrageOpportunity | null>(null);
  const [isLive, setIsLive] = useState(true);

  // Historical Data State
  const [history, setHistory] = useState<{
    id: string;
    pair: string;
    buyExchange: string;
    sellExchange: string;
    profit: number;
    timestamp: number;
  }[]>([]);

  // Initialize mock history
  useEffect(() => {
    const mockHistory = Array.from({ length: 8 }).map((_, i) => {
      const time = new Date();
      time.setHours(time.getHours() - (8 - i));
      // Add some minutes randomization
      time.setMinutes(Math.floor(Math.random() * 60));

      return {
        id: `hist-${i}`,
        pair: ['BTC/USDT', 'ETH/USDT', 'SOL/USDT', 'AVAX/USDT'][Math.floor(Math.random() * 4)],
        buyExchange: ['Binance', 'KuCoin', 'Okx'][Math.floor(Math.random() * 3)],
        sellExchange: ['Coinbase', 'Kraken', 'Bybit'][Math.floor(Math.random() * 3)],
        profit: Math.random() * 120 + 10,
        timestamp: time.getTime()
      };
    });
    setHistory(mockHistory);
  }, []);

  // Live Price Feed Simulation
  useEffect(() => {
    if (!isLive) return;

    const interval = setInterval(() => {
      setOpportunities(prev => prev.map(opp => {
        // Simulate small price fluctuations (0.05% - 0.2%)
        const fluctuation = (Math.random() * 0.004) - 0.002;
        const newBuyPrice = opp.buyPrice * (1 + fluctuation);

        // Sell price moves slightly differently to create dynamic spread
        const spreadNoise = (Math.random() * 0.002) - 0.001; 
        const newSellPrice = opp.sellPrice * (1 + fluctuation + spreadNoise);

        return {
          ...opp,
          buyPrice: newBuyPrice,
          sellPrice: newSellPrice,
          spread: ((newSellPrice - newBuyPrice) / newBuyPrice) * 100,
          profitPotential: (newSellPrice - newBuyPrice) * (Math.random() * 10 + 1), // Varies with spread & simulated volume
          timestamp: Date.now()
        };
      }));
      setLastUpdated(new Date());
    }, 2000); // Update every 2 seconds

    return () => clearInterval(interval);
  }, [isLive]);

  // Calculate cumulative profit for chart
  const chartData = history.map((item, index) => ({
    time: item.timestamp,
    profit: item.profit,
    cumulative: history.slice(0, index + 1).reduce((acc, curr) => acc + curr.profit, 0)
  }));

  const scanMarket = () => {
    setIsScanning(true);
    // Simulate API call delay with visual feedback
    setTimeout(() => {
      // Shuffle prices and create variations
      const newOpps = opportunities.map(opp => {
        const volatility = Math.random() * 0.02 - 0.01; // +/- 1%
        const newBuy = opp.buyPrice * (1 + volatility);
        const newSell = opp.sellPrice * (1 + volatility + 0.002); // Slight bias to positive spread for demo
        return {
          ...opp,
          buyPrice: newBuy,
          sellPrice: newSell,
          spread: ((newSell - newBuy) / newBuy) * 100,
          profitPotential: (newSell - newBuy) * (Math.random() * 10 + 1), // Random volume multiplier
          timestamp: Date.now()
        };
      });

      // Sort
      const sortedOpps = [...newOpps].sort((a, b) => 
        sortBy === 'profit' ? b.profitPotential - a.profitPotential : b.spread - a.spread
      );

      setOpportunities(sortedOpps);
      setLastUpdated(new Date());
      setIsScanning(false);
    }, 2000);
  };

  const handleTrade = (opp: ArbitrageOpportunity) => {
    setTradeStatuses(prev => ({ ...prev, [opp.id]: 'loading' }));

    // Simulate Trade Execution
    setTimeout(() => {
      setTradeStatuses(prev => ({ ...prev, [opp.id]: 'success' }));

      // Add to history
      const newHistoryItem = {
        id: `trade-${Date.now()}`,
        pair: opp.pair,
        buyExchange: opp.buyExchange,
        sellExchange: opp.sellExchange,
        profit: opp.profitPotential,
        timestamp: Date.now()
      };
      setHistory(prev => [...prev, newHistoryItem]);

      // Reset status after showing success message
      setTimeout(() => {
        setTradeStatuses(prev => {
          const newState = { ...prev };
          delete newState[opp.id];
          return newState;
        });
      }, 3000);
    }, 2000);
  };

  const handleConfirmTrade = () => {
    if (confirmingTrade) {
      handleTrade(confirmingTrade);
      setConfirmingTrade(null);
    }
  };

  const handleAiVerify = (opp: ArbitrageOpportunity) => {
    // Access the global AI trigger exposed in AiAssistant
    const prompt = `Verify the current price of ${opp.pair} on ${opp.buyExchange} and ${opp.sellExchange}. Is a spread of ${opp.spread.toFixed(2)}% realistic right now?`;
    if ((window as any).triggerNexusAi) {
      (window as any).triggerNexusAi(prompt);
    }
  };

  // Re-sort when sort criteria changes
  useEffect(() => {
    setOpportunities(prev => [...prev].sort((a, b) => 
      sortBy === 'profit' ? b.profitPotential - a.profitPotential : b.spread - a.spread
    ));
  }, [sortBy]);

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 relative">
      {/* Header Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {CEX_LIST.slice(0, 4).map((ex) => (
          <div key={ex.id} className="bg-surface border border-slate-800 p-4 rounded-xl flex items-center gap-4 transition-transform hover:scale-105 duration-200">
            <img src={ex.logo} alt={ex.name} className="w-10 h-10 rounded-full bg-slate-700" />
            <div>
              <h3 className="font-bold text-slate-200">{ex.name}</h3>
              <p className="text-xs text-slate-400">Vol: <span className="text-primary">{ex.volume24h}</span></p>
            </div>
            <div className={`ml-auto w-2 h-2 rounded-full ${ex.status === 'active' ? 'bg-accent shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-red-500'}`}></div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Scanner Panel */}
        <div className="lg:col-span-2 bg-surface border border-slate-800 rounded-2xl overflow-hidden shadow-xl flex flex-col">
          <div className="p-6 border-b border-slate-800 flex flex-wrap justify-between items-center gap-4 bg-gradient-to-r from-surface to-slate-900">
            <div>
              <h2 className="text-xl font-bold text-white flex items-center gap-2">
                <ArrowRightLeft className="text-primary" /> Arbitrage Scanner
              </h2>
              <div className="flex items-center gap-2 text-xs text-slate-400 mt-1">
                <div className={`w-2 h-2 rounded-full ${isLive ? 'bg-green-500 animate-pulse' : 'bg-slate-600'}`}></div>
                <span className={isLive ? 'text-green-400 font-medium' : ''}>{isLive ? 'Live Feed Active' : 'Feed Paused'}</span>
                <span className="text-slate-600">|</span>
                <Clock className="w-3 h-3" />
                <span>Updated: {lastUpdated.toLocaleTimeString()}</span>
              </div>
            </div>
            <div className="flex items-center gap-2">
               <button 
                onClick={() => setIsLive(!isLive)}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all ${
                  isLive 
                    ? 'bg-green-500/10 text-green-400 border-green-500/30 hover:bg-green-500/20' 
                    : 'bg-slate-800 text-slate-400 border-slate-700 hover:text-white'
                }`}
              >
                <Radio className={`w-3 h-3 ${isLive ? 'animate-pulse' : ''}`} />
                {isLive ? 'Live On' : 'Live Off'}
              </button>

              <div className="flex bg-slate-800 rounded-lg p-1 border border-slate-700">
                <button 
                  onClick={() => setSortBy('profit')}
                  className={`px-3 py-1 rounded text-xs font-medium transition-colors ${sortBy === 'profit' ? 'bg-slate-700 text-white' : 'text-slate-400 hover:text-white'}`}
                >
                  Profit
                </button>
                <button 
                  onClick={() => setSortBy('spread')}
                  className={`px-3 py-1 rounded text-xs font-medium transition-colors ${sortBy === 'spread' ? 'bg-slate-700 text-white' : 'text-slate-400 hover:text-white'}`}
                >
                  Spread
                </button>
              </div>
              <button 
                onClick={scanMarket}
                disabled={isScanning}
                className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-semibold transition-all ${isScanning ? 'bg-slate-700 text-slate-400 cursor-wait' : 'bg-primary text-white hover:bg-blue-600 shadow-lg shadow-blue-500/20'}`}
              >
                <RefreshCw className={`w-4 h-4 ${isScanning ? 'animate-spin' : ''}`} />
                {isScanning ? 'Scanning...' : 'Scan Now'}
              </button>
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm text-slate-300">
              <thead className="bg-slate-900/50 text-slate-400 uppercase text-xs">
                <tr>
                  <th className="px-6 py-4">Pair</th>
                  <th className="px-6 py-4">Buy At</th>
                  <th className="px-6 py-4">Sell At</th>
                  <th className="px-6 py-4 text-right">Spread</th>
                  <th className="px-6 py-4 text-right">Profit Est.</th>
                  <th className="px-6 py-4 text-center">Action</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800">
                {isScanning ? (
                  <tr>
                    <td colSpan={6} className="py-12 text-center text-slate-500">
                      <div className="flex flex-col items-center gap-3">
                        <Loader2 className="w-8 h-8 animate-spin text-primary" />
                        <span>Analyzing Order Books...</span>
                      </div>
                    </td>
                  </tr>
                ) : opportunities.map((opp) => (
                  <tr key={opp.id} className="hover:bg-slate-800/30 transition-colors">
                    <td className="px-6 py-4 font-bold text-white">
                      <div className="flex items-center gap-2">
                        {opp.pair}
                        {isLive && (
                          <span className="relative flex h-2 w-2">
                             <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
                             <span className="relative inline-flex rounded-full h-2 w-2 bg-green-500"></span>
                          </span>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex flex-col">
                        <span className="font-mono text-accent transition-all duration-300">${opp.buyPrice.toLocaleString(undefined, { maximumFractionDigits: 2 })}</span>
                        <span className="text-xs text-slate-500">{opp.buyExchange}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex flex-col">
                        <span className="font-mono text-danger transition-all duration-300">${opp.sellPrice.toLocaleString(undefined, { maximumFractionDigits: 2 })}</span>
                        <span className="text-xs text-slate-500">{opp.sellExchange}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-right">
                       <span className={`font-mono font-bold px-2 py-1 rounded transition-colors duration-300 ${opp.spread > 1 ? 'bg-emerald-500/10 text-emerald-400' : 'text-slate-400'}`}>
                         +{opp.spread.toFixed(2)}%
                       </span>
                    </td>
                    <td className="px-6 py-4 text-right font-mono font-bold text-white transition-all duration-300">${opp.profitPotential.toFixed(2)}</td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2 justify-end">
                        <button
                          onClick={() => handleAiVerify(opp)}
                          className="p-1.5 rounded-lg bg-purple-500/10 text-purple-400 hover:bg-purple-500 hover:text-white transition-colors"
                          title="Verify with AI Search"
                        >
                          <Sparkles className="w-4 h-4" />
                        </button>
                        {tradeStatuses[opp.id] === 'loading' ? (
                          <button disabled className="bg-slate-800 text-slate-400 px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1 cursor-not-allowed w-24 justify-center">
                            <Loader2 className="w-3 h-3 animate-spin" /> Process
                          </button>
                        ) : tradeStatuses[opp.id] === 'success' ? (
                          <button disabled className="bg-emerald-500/20 text-emerald-400 px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1 border border-emerald-500/50 w-24 justify-center">
                            <Check className="w-3 h-3" /> Filled
                          </button>
                        ) : (
                          <button 
                            onClick={() => setConfirmingTrade(opp)}
                            className="bg-primary/10 hover:bg-primary text-primary hover:text-white border border-primary/50 hover:border-primary px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1 transition-all w-24 justify-center group"
                          >
                            <Play className="w-3 h-3 fill-current group-hover:scale-110 transition-transform" /> Trade
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Analytics / Chart */}
        <div className="bg-surface border border-slate-800 rounded-2xl p-6 flex flex-col shadow-xl">
           <div className="flex items-center justify-between mb-6">
              <h3 className="text-lg font-bold text-white flex items-center gap-2">
                <TrendingUp className="text-accent" /> Spread Analysis
              </h3>
              <Filter className="w-4 h-4 text-slate-500" />
           </div>
          <div className="flex-1 min-h-[200px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={opportunities}>
                <XAxis dataKey="pair" stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} />
                <YAxis stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155', color: '#f8fafc' }}
                  cursor={{fill: '#334155', opacity: 0.2}}
                />
                <Bar dataKey="spread" radius={[4, 4, 0, 0]}>
                   {opportunities.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={entry.spread > 1.5 ? '#10b981' : '#3b82f6'} />
                    ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
          <div className="mt-6 bg-yellow-500/10 border border-yellow-500/20 rounded-lg p-3">
