import React, { useState, useEffect } from 'react';
import { X, Wallet as WalletIcon, CheckCircle2, Loader2, ArrowRight, AlertCircle, LogOut, ShieldCheck, Fingerprint, Bell, Lock } from 'lucide-react';
import { Wallet } from '../types';
import { WALLETS } from '../constants';

interface WalletModalProps {
  isOpen: boolean;
  onClose: () => void;
  activeWallet: Wallet | null;
  onConnect: (wallet: Wallet) => Promise<void>;
  onDisconnect: () => void;
  error?: string | null;
}

const WalletModal: React.FC<WalletModalProps> = ({ isOpen, onClose, activeWallet, onConnect, onDisconnect, error: propError }) => {
  const [connectingWalletId, setConnectingWalletId] = useState<string | null>(null);
  const [localError, setLocalError] = useState<string | null>(null);

  // Security Settings State (Persisted in local state for session)
  const [securitySettings, setSecuritySettings] = useState({
    biometrics: false,
    largeTxAlert: true,
    autoDisconnect: false
  });

  // Sync prop error to local error
  useEffect(() => {
    if (propError) setLocalError(propError);
  }, [propError]);

  if (!isOpen) return null;

  const handleConnect = async (wallet: Wallet) => {
    setConnectingWalletId(wallet.id);
    setLocalError(null);
    try {
      await onConnect(wallet);
      onClose();
    } catch (error) {
      // Error is handled in App.tsx and passed back via prop or state, 
      // but we catch here to stop loading state.
    } finally {
      setConnectingWalletId(null);
    }
  };

  const handleDisconnect = () => {
    onDisconnect();
    onClose();
  };

  const toggleSetting = (key: keyof typeof securitySettings) => {
    setSecuritySettings(prev => ({ ...prev, [key]: !prev[key] }));
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
      <div className="bg-surface border border-slate-700 w-full max-w-md rounded-2xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
        <div className="p-4 border-b border-slate-700 flex justify-between items-center bg-slate-900/50">
          <h2 className="text-xl font-bold text-white flex items-center gap-2">
            <WalletIcon className="w-5 h-5 text-primary" /> {activeWallet ? 'Wallet Security' : 'Connect Wallet'}
          </h2>
          <button 
            onClick={onClose} 
            className="text-slate-400 hover:text-white transition-colors"
            disabled={!!connectingWalletId}
          >
            <X className="w-6 h-6" />
          </button>
        </div>

        <div className="p-6">
          {localError && (
            <div className="bg-red-500/10 border border-red-500/20 rounded-xl p-3 flex items-start gap-3 mb-4 animate-in slide-in-from-top-2">
              <AlertCircle className="w-5 h-5 text-red-500 shrink-0 mt-0.5" />
              <div className="text-sm text-red-200">{localError}</div>
            </div>
          )}

          {activeWallet ? (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-200">
              {/* Connected Wallet Info */}
              <div className="bg-slate-800/50 rounded-xl p-4 border border-emerald-500/20 flex items-center gap-4">
                 <div className="relative">
                    <img src={activeWallet.icon} alt={activeWallet.name} className="w-12 h-12 rounded-full object-cover bg-slate-900" />
                    <div className="absolute -bottom-1 -right-1 bg-surface rounded-full p-0.5">
                       <CheckCircle2 className="w-4 h-4 text-emerald-500" />
                    </div>
                 </div>
                 <div>
                    <h3 className="font-bold text-white text-lg">{activeWallet.name}</h3>
                    <p className="font-mono text-slate-400 text-sm">{activeWallet.address}</p>
                 </div>
              </div>

              {/* Security Settings */}
              <div className="space-y-3">
                 <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider flex items-center gap-2 mb-3">
                    <ShieldCheck className="w-4 h-4 text-primary" /> Security & Protection
                 </h4>

                 {/* Biometric / MFA */}
                 <div className="flex items-center justify-between p-3 rounded-xl bg-slate-800/30 border border-slate-700/50 hover:bg-slate-800/50 transition-colors">
                    <div className="flex items-center gap-3">
                       <div className="p-2 rounded-lg bg-blue-500/10 text-blue-400">
                          <Fingerprint className="w-5 h-5" />
                       </div>
                       <div>
                          <p className="text-sm font-medium text-slate-200">Biometric Approval</p>
                          <p className="text-xs text-slate-500">2FA for transactions</p>
                       </div>
                    </div>
                    <button 
                       onClick={() => toggleSetting('biometrics')}
                       className={`w-11 h-6 rounded-full transition-colors relative ${securitySettings.biometrics ? 'bg-primary' : 'bg-slate-700'}`}
                    >
                       <div className={`absolute top-1 h-4 w-4 rounded-full bg-white transition-all duration-200 ${securitySettings.biometrics ? 'left-6' : 'left-1'}`} />
                    </button>
                 </div>

                 {/* Large Tx Alert */}
                 <div className="flex items-center justify-between p-3 rounded-xl bg-slate-800/30 border border-slate-700/50 hover:bg-slate-800/50 transition-colors">
                    <div className="flex items-center gap-3">
                       <div className="p-2 rounded-lg bg-yellow-500/10 text-yellow-400">
                          <Bell className="w-5 h-5" />
                       </div>
                       <div>
                          <p className="text-sm font-medium text-slate-200">Whale Alert</p>
                          <p className="text-xs text-slate-500">Warn if Tx &gt; $1,000</p>
                       </div>
                    </div>
                    <button 
                       onClick={() => toggleSetting('largeTxAlert')}
                       className={`w-11 h-6 rounded-full transition-colors relative ${securitySettings.largeTxAlert ? 'bg-primary' : 'bg-slate-700'}`}
                    >
                       <div className={`absolute top-1 h-4 w-4 rounded-full bg-white transition-all duration-200 ${securitySettings.largeTxAlert ? 'left-6' : 'left-1'}`} />
                    </button>
                 </div>

                 {/* Auto-Disconnect */}
                 <div className="flex items-center justify-between p-3 rounded-xl bg-slate-800/30 border border-slate-700/50 hover:bg-slate-800/50 transition-colors">
                    <div className="flex items-center gap-3">
                       <div className="p-2 rounded-lg bg-slate-500/10 text-slate-400">
                          <Lock className="w-5 h-5" />
                       </div>
                       <div>
                          <p className="text-sm font-medium text-slate-200">Auto-Disconnect</p>
                          <p className="text-xs text-slate-500">After 15m idle</p>
                       </div>
                    </div>
                    <button 
                       onClick={() => toggleSetting('autoDisconnect')}
                       className={`w-11 h-6 rounded-full transition-colors relative ${securitySettings.autoDisconnect ? 'bg-primary' : 'bg-slate-700'}`}
                    >
                       <div className={`absolute top-1 h-4 w-4 rounded-full bg-white transition-all duration-200 ${securitySettings.autoDisconnect ? 'left-6' : 'left-1'}`} />
                    </button>
                 </div>
              </div>

              <div className="pt-2 border-t border-slate-800">
                 <button 
                   onClick={handleDisconnect}
                   className="w-full py-3 rounded-xl border border-red-500/20 bg-red-500/10 text-red-400 hover:bg-red-500/20 hover:text-red-300 font-semibold transition-all flex items-center justify-center gap-2"
                 >
                   <LogOut className="w-4 h-4" /> Disconnect Wallet
                 </button>
              </div>
            </div>
          ) : (
            <>
              <p className="text-slate-400 text-sm mb-4">Select a wallet provider to connect your assets to NexusTrade.</p>
              <div className="space-y-3">
                {WALLETS.map((wallet) => {
                  const isActive = activeWallet?.id === wallet.id;
                  const isConnecting = connectingWalletId === wallet.id;
                  const isDisabled = (!!connectingWalletId && !isConnecting);

                  return (
                    <button
                      key={wallet.id}
                      onClick={() => handleConnect(wallet)}
                      disabled={isDisabled}
                      className={`w-full flex items-center justify-between p-4 rounded-xl border transition-all duration-200 group relative overflow-hidden
                        ${isDisabled 
                            ? 'border-slate-800 bg-slate-900/50 opacity-40 cursor-not-allowed'
                            : 'border-slate-700 bg-slate-800/50 hover:bg-slate-800 hover:border-primary/50'
                        }`}
                    >
                      <div className="flex items-center gap-4 z-10">
                        <div className="w-10 h-10 rounded-full bg-slate-900 flex items-center justify-center border border-slate-700 shrink-0">
                          <img src={wallet.icon} alt={wallet.name} className="w-6 h-6 object-cover rounded-full" />
                        </div>
                        <div className="text-left">
                          <span className="font-medium block text-slate-200 group-hover:text-white transition-colors">
                            {wallet.name}
                          </span>
                          {wallet.id === 'walletconnect' && !isConnecting && (
                            <span className="text-[10px] text-slate-500">Scan QR Code</span>
                          )}
                        </div>
                      </div>

                      <div className="z-10">
                        {isConnecting && <Loader2 className="w-5 h-5 text-primary animate-spin" />}
                        {!isConnecting && !isDisabled && (
                          <ArrowRight className="w-4 h-4 text-slate-500 group-hover:text-white transition-colors opacity-0 group-hover:opacity-100 -translate-x-2 group-hover:translate-x-0 transform duration-200" />
                        )}
                      </div>
                    </button>
                  );
                })}
              </div>
            </>
          )}
        </div>

        <div className="p-4 bg-slate-900/50 border-t border-slate-700 text-center">
          <p className="text-xs text-slate-500">By connecting, you agree to the Terms of Service.</p>
        </div>
      </div>
    </div>
  );
};

export default WalletModal;

import React, { useState, useEffect } from 'react';
import { ArrowRightLeft, TrendingUp, RefreshCw, AlertTriangle, Play, Loader2, Check, Clock, Filter, X, ShieldCheck, History, Sparkles, Zap, Radio, DollarSign, BarChart2, Activity } from 'lucide-react';
import { CEX_LIST, INITIAL_ARB_OPPS } from '../constants';
import { ArbitrageOpportunity } from '../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell, LineChart, Line, CartesianGrid, ComposedChart, Area } from 'recharts';
import AiAssistant from './AiAssistant';

const CexDashboard: React.FC = () => {
  const [opportunities, setOpportunities] = useState<ArbitrageOpportunity[]>(INITIAL_ARB_OPPS);
  const [isScanning, setIsScanning] = useState(false);
  const [tradeStatuses, setTradeStatuses] = useState<Record<string, 'idle' | 'loading' | 'success'>>({});
  const [lastUpdated, setLastUpdated] = useState<Date>(new Date());
  const [sortBy, setSortBy] = useState<'profit' | 'spread'>('profit');
  const [confirmingTrade, setConfirmingTrade] = useState<ArbitrageOpportunity | null>(null);
  const [isLive, setIsLive] = useState(true);

  // Historical Data State
  const [history, setHistory] = useState<{
    id: string;
    pair: string;
    buyExchange: string;
    sellExchange: string;
    profit: number;
    spread: number;
    tradeVolume: number;
    timestamp: number;
  }[]>([]);

  // Initialize mock history
  useEffect(() => {
    const mockHistory = Array.from({ length: 8 }).map((_, i) => {
      const time = new Date();
      time.setHours(time.getHours() - (8 - i));
      // Add some minutes randomization
      time.setMinutes(Math.floor(Math.random() * 60));

      const spread = Math.random() * 1.5 + 0.1;
      const profit = Math.random() * 120 + 10;
      // Est volume based on profit / spread roughly
      const volume = (profit / (spread / 100));

      return {
        id: `hist-${i}`,
        pair: ['BTC/USDT', 'ETH/USDT', 'SOL/USDT', 'AVAX/USDT'][Math.floor(Math.random() * 4)],
        buyExchange: ['Binance', 'KuCoin', 'Okx'][Math.floor(Math.random() * 3)],
        sellExchange: ['Coinbase', 'Kraken', 'Bybit'][Math.floor(Math.random() * 3)],
        profit: profit,
        spread: spread,
        tradeVolume: volume,
        timestamp: time.getTime()
      };
    });
    setHistory(mockHistory);
  }, []);

  // Live Price Feed Simulation
  useEffect(() => {
    if (!isLive) return;

    const interval = setInterval(() => {
      setOpportunities(prev => prev.map(opp => {
        // Simulate small price fluctuations (0.05% - 0.2%)
        const fluctuation = (Math.random() * 0.004) - 0.002;
        const newBuyPrice = opp.buyPrice * (1 + fluctuation);

        // Sell price moves slightly differently to create dynamic spread
        const spreadNoise = (Math.random() * 0.002) - 0.001; 
        const newSellPrice = opp.sellPrice * (1 + fluctuation + spreadNoise);

        return {
          ...opp,
          buyPrice: newBuyPrice,
          sellPrice: newSellPrice,
          spread: ((newSellPrice - newBuyPrice) / newBuyPrice) * 100,
          profitPotential: (newSellPrice - newBuyPrice) * (Math.random() * 10 + 1), // Varies with spread & simulated volume
          timestamp: Date.now()
        };
      }));
      setLastUpdated(new Date());
    }, 2000); // Update every 2 seconds

    return () => clearInterval(interval);
  }, [isLive]);

  // Calculate cumulative profit for chart
  const chartData = history.map((item, index) => ({
    time: item.timestamp,
    profit: item.profit,
    cumulative: history.slice(0, index + 1).reduce((acc, curr) => acc + curr.profit, 0)
  }));

  // Metrics
  const totalProfit = history.reduce((acc, curr) => acc + curr.profit, 0);
  const avgSpread = history.length > 0 ? history.reduce((acc, curr) => acc + curr.spread, 0) / history.length : 0;
  const totalVolume = history.reduce((acc, curr) => acc + curr.tradeVolume, 0);

  const scanMarket = () => {
    setIsScanning(true);
    // Simulate API call delay with visual feedback
    setTimeout(() => {
      // Shuffle prices and create variations
      const newOpps = opportunities.map(opp => {
        const volatility = Math.random() * 0.02 - 0.01; // +/- 1%
        const newBuy = opp.buyPrice * (1 + volatility);
        const newSell = opp.sellPrice * (1 + volatility + 0.002); // Slight bias to positive spread for demo
        return {
          ...opp,
          buyPrice: newBuy,
          sellPrice: newSell,
          spread: ((newSell - newBuy) / newBuy) * 100,
          profitPotential: (newSell - newBuy) * (Math.random() * 10 + 1), // Random volume multiplier
          timestamp: Date.now()
        };
      });

      // Sort
      const sortedOpps = [...newOpps].sort((a, b) => 
        sortBy === 'profit' ? b.profitPotential - a.profitPotential : b.spread - a.spread
      );

      setOpportunities(sortedOpps);
      setLastUpdated(new Date());
      setIsScanning(false);
    }, 2000);
  };

  const handleTrade = (opp: ArbitrageOpportunity) => {
    setTradeStatuses(prev => ({ ...prev, [opp.id]: 'loading' }));

    // Simulate Trade Execution
    setTimeout(() => {
      setTradeStatuses(prev => ({ ...prev, [opp.id]: 'success' }));

      // Add to history
      const newHistoryItem = {
        id: `trade-${Date.now()}`,
        pair: opp.pair,
        buyExchange: opp.buyExchange,
        sellExchange: opp.sellExchange,
        profit: opp.profitPotential,
        spread: opp.spread,
        tradeVolume: opp.profitPotential / (opp.spread / 100),
        timestamp: Date.now()
      };
      setHistory(prev => [...prev, newHistoryItem]);

      // Reset status after showing success message
      setTimeout(() => {
        setTradeStatuses(prev => {
          const newState = { ...prev };
          delete newState[opp.id];
          return newState;
        });
      }, 3000);
    }, 2000);
  };

  const handleConfirmTrade = () => {
    if (confirmingTrade) {
      handleTrade(confirmingTrade);
      setConfirmingTrade(null);
    }
  };

  const handleAiVerify = (opp: ArbitrageOpportunity) => {
    // Access the global AI trigger exposed in AiAssistant
    const prompt = `Verify the current price of ${opp.pair} on ${opp.buyExchange} and ${opp.sellExchange}. Is a spread of ${opp.spread.toFixed(2)}% realistic right now?`;
    if ((window as any).triggerNexusAi) {
      (window as any).triggerNexusAi(prompt);
    }
  };

  // Re-sort when sort criteria changes
  useEffect(() => {
    setOpportunities(prev => [...prev].sort((a, b) => 
      sortBy === 'profit' ? b.profitPotential - a.profitPotential : b.spread - a.spread
    ));
  }, [sortBy]);

  // Generate dynamic AI Context
  const topOpportunities = [...opportunities]
    .sort((a, b) => b.profitPotential - a.profitPotential)
    .slice(0, 3);

  const opportunitiesContext = topOpportunities
    .map(opp => `${opp.pair} (${opp.buyExchange} -> ${opp.sellExchange}): Spread ${opp.spread.toFixed(2)}%, Est. Profit $${opp.profitPotential.toFixed(2)}`)
    .join('; ');

  const aiContext = `CEX Market Analysis: Analyzing real-time arbitrage opportunities between major exchanges (Binance, Coinbase, Kraken, etc.). 
  Current Top Opportunities: ${opportunitiesContext}. 
  Users can request verification of these prices via Google Search.`;

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 relative">
      {/* Header Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {CEX_LIST.slice(0, 4).map((ex) => (
          <div key={ex.id} className="bg-surface border border-slate-800 p-4 rounded-xl flex items-center gap-4 transition-transform hover:scale-105 duration-200">
            <img src={ex.logo} alt={ex.name} className="w-10 h-10 rounded-full bg-slate-700" />
            <div>
              <h3 className="font-bold text-slate-200">{ex.name}</h3>
              <p className="text-xs text-slate-400">Vol: <span className="text-primary">{ex.volume24h}</span></p>
            </div>
            <div className={`ml-auto w-2 h-2 rounded-full ${ex.status === 'active' ? 'bg-accent shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-red-500'}`}></div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Scanner Panel */}
        <div className="lg:col-span-2 bg-surface border border-slate-800 rounded-2xl overflow-hidden shadow-xl flex flex-col">
          <div className="p-6 border-b border-slate-800 flex flex-wrap justify-between items-center gap-4 bg-gradient-to-r from-surface to-slate-900">
            <div>
              <h2 className="text-xl font-bold text-white flex items-center gap-2">
                <ArrowRightLeft className="text-primary" /> Arbitrage Scanner
              </h2>
              <div className="flex items-center gap-2 text-xs text-slate-400 mt-1">
                <div className={`w-2 h-2 rounded-full ${isLive ? 'bg-green-500 animate-pulse' : 'bg-slate-600'}`}></div>
                <span className={isLive ? 'text-green-400 font-medium' : ''}>{isLive ? 'Live Feed Active' : 'Feed Paused'}</span>
                <span className="text-slate-600">|</span>
                <Clock className="w-3 h-3" />
                <span>Updated: {lastUpdated.toLocaleTimeString()}</span>
              </div>
            </div>
            <div className="flex items-center gap-2">
               <button 
                onClick={() => setIsLive(!isLive)}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all ${
                  isLive 
                    ? 'bg-green-500/10 text-green-400 border-green-500/30 hover:bg-green-500/20' 
                    : 'bg-slate-800 text-slate-400 border-slate-700 hover:text-white'
                }`}
              >
                <Radio className={`w-3 h-3 ${isLive ? 'animate-pulse' : ''}`} />
                {isLive ? 'Live On' : 'Live Off'}
              </button>

              <div className="flex bg-slate-800 rounded-lg p-1 border border-slate-700">
                <button 
                  onClick={() => setSortBy('profit')}
