  // Calculate cumulative profit for chart
  const chartData = history.map((item, index) => ({
    time: item.timestamp,
    profit: item.profit,
    cumulative: history.slice(0, index + 1).reduce((acc, curr) => acc + curr.profit, 0)
  }));

  // Metrics
  const totalProfit = history.reduce((acc, curr) => acc + curr.profit, 0);
  const avgSpread = history.length > 0 ? history.reduce((acc, curr) => acc + curr.spread, 0) / history.length : 0;
  const totalVolume = history.reduce((acc, curr) => acc + curr.tradeVolume, 0);

