import React, { useState, useEffect } from 'react';
import { ArrowRightLeft, TrendingUp, RefreshCw, AlertTriangle, Play, Loader2, Check, Clock, Filter, X, ShieldCheck, History, Sparkles, Zap, Radio, DollarSign, BarChart2, Activity, Bot, Wifi, Layers, ZoomIn } from 'lucide-react';
import { CEX_LIST, INITIAL_ARB_OPPS } from '../constants';
import { ArbitrageOpportunity } from '../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell, LineChart, Line, CartesianGrid, ComposedChart, Area } from 'recharts';
import AiAssistant from './AiAssistant';

// Extended type for internal use
interface ExtendedOpportunity extends ArbitrageOpportunity {
  liquidityDepth: 'High' | 'Medium' | 'Low';
  bidWall: number; // For visualization
  askWall: number; // For visualization
}

const CexDashboard: React.FC = () => {
  const [opportunities, setOpportunities] = useState<ExtendedOpportunity[]>(
    INITIAL_ARB_OPPS.map(o => ({...o, liquidityDepth: 'Medium', bidWall: 50, askWall: 50}))
  );
  const [isScanning, setIsScanning] = useState(false);
  const [tradeStatuses, setTradeStatuses] = useState<Record<string, 'idle' | 'loading' | 'success'>>({});
  const [lastUpdated, setLastUpdated] = useState<Date>(new Date());
  const [sortBy, setSortBy] = useState<'profit' | 'spread'>('profit');
  const [confirmingTrade, setConfirmingTrade] = useState<ExtendedOpportunity | null>(null);
  const [isLive, setIsLive] = useState(true);

  // Bot / Auto-Trade State
  const [isAutoTrading, setIsAutoTrading] = useState(false);
  const [autoTradeThreshold, setAutoTradeThreshold] = useState(150);

  // Deep Scan State
  const [deepScanMode, setDeepScanMode] = useState(false);
  const [selectedDepthOpp, setSelectedDepthOpp] = useState<string | null>(null);

  // Historical Data State
  const [history, setHistory] = useState<{
    id: string;
    pair: string;
    buyExchange: string;
    sellExchange: string;
    profit: number;
    spread: number;
    tradeVolume: number;
    timestamp: number;
  }[]>([]);

  // Initialize mock history
  useEffect(() => {
    const mockHistory = Array.from({ length: 8 }).map((_, i) => {
      const time = new Date();
      time.setHours(time.getHours() - (8 - i));
      time.setMinutes(Math.floor(Math.random() * 60));
      const spread = Math.random() * 1.5 + 0.1;
      const profit = Math.random() * 120 + 10;
      const volume = (profit / (spread / 100));

      return {
        id: `hist-${i}`,
        pair: ['BTC/USDT', 'ETH/USDT', 'SOL/USDT', 'AVAX/USDT'][Math.floor(Math.random() * 4)],
        buyExchange: ['Binance', 'KuCoin', 'Okx'][Math.floor(Math.random() * 3)],
        sellExchange: ['Coinbase', 'Kraken', 'Bybit'][Math.floor(Math.random() * 3)],
        profit: profit,
        spread: spread,
        tradeVolume: volume,
        timestamp: time.getTime()
      };
    });
    setHistory(mockHistory);
  }, []);

  // Live Price Feed & Bot Logic
  useEffect(() => {
    if (!isLive) return;

    const interval = setInterval(() => {
      setOpportunities(prev => {
        const updated = prev.map(opp => {
          const fluctuation = (Math.random() * 0.004) - 0.002;
          const newBuyPrice = opp.buyPrice * (1 + fluctuation);
          const spreadNoise = (Math.random() * 0.002) - 0.001; 
          const newSellPrice = opp.sellPrice * (1 + fluctuation + spreadNoise);
          const profit = (newSellPrice - newBuyPrice) * (Math.random() * 10 + 1);

          return {
            ...opp,
            buyPrice: newBuyPrice,
            sellPrice: newSellPrice,
            spread: ((newSellPrice - newBuyPrice) / newBuyPrice) * 100,
            profitPotential: profit,
            timestamp: Date.now()
          };
        });

        if (isAutoTrading) {
          updated.forEach(opp => {
            // In deep scan mode, only auto-trade High liquidity
            if (deepScanMode && opp.liquidityDepth !== 'High') return;

            if (opp.profitPotential >= autoTradeThreshold && !tradeStatuses[opp.id]) {
              handleTrade(opp, true);
            }
          });
        }
        return updated;
      });
      setLastUpdated(new Date());
    }, 2000);

    return () => clearInterval(interval);
  }, [isLive, isAutoTrading, autoTradeThreshold, tradeStatuses, deepScanMode]);

  // Calculate cumulative profit
  const chartData = history.map((item, index) => ({
    time: item.timestamp,
    profit: item.profit,
    cumulative: history.slice(0, index + 1).reduce((acc, curr) => acc + curr.profit, 0)
  }));

  const totalProfit = history.reduce((acc, curr) => acc + curr.profit, 0);
  const avgSpread = history.length > 0 ? history.reduce((acc, curr) => acc + curr.spread, 0) / history.length : 0;

  const scanMarket = () => {
    setIsScanning(true);
    // Deep scan takes longer
    const delay = deepScanMode ? 3000 : 1500;

    setTimeout(() => {
      const newOpps = opportunities.map(opp => {
        const volatility = Math.random() * 0.02 - 0.01;
        const newBuy = opp.buyPrice * (1 + volatility);
        const newSell = opp.sellPrice * (1 + volatility + 0.002);

        // Randomize Liquidity for simulation
        const rand = Math.random();
        const depth: 'High' | 'Medium' | 'Low' = rand > 0.7 ? 'High' : rand > 0.3 ? 'Medium' : 'Low';

        return {
          ...opp,
          buyPrice: newBuy,
          sellPrice: newSell,
          spread: ((newSell - newBuy) / newBuy) * 100,
          profitPotential: (newSell - newBuy) * (Math.random() * 10 + 1),
          timestamp: Date.now(),
          liquidityDepth: depth,
          bidWall: Math.floor(Math.random() * 80) + 20,
          askWall: Math.floor(Math.random() * 80) + 20
        };
      });

      // Filter logic if Deep Scan is ON (remove Low liquidity)
      const filteredOpps = deepScanMode 
        ? newOpps.filter(o => o.liquidityDepth !== 'Low')
        : newOpps;

      const sortedOpps = [...filteredOpps].sort((a, b) => 
        sortBy === 'profit' ? b.profitPotential - a.profitPotential : b.spread - a.spread
      );

      setOpportunities(sortedOpps);
      setLastUpdated(new Date());
      setIsScanning(false);

      // Auto-select first high liquidity opp for visualization in Deep Scan
      if (deepScanMode && sortedOpps.length > 0) {
        setSelectedDepthOpp(sortedOpps[0].id);
      }
    }, delay);
  };

  const handleTrade = (opp: ArbitrageOpportunity, isBot = false) => {
    if (tradeStatuses[opp.id]) return;

    setTradeStatuses(prev => ({ ...prev, [opp.id]: 'loading' }));

    setTimeout(() => {
      setTradeStatuses(prev => ({ ...prev, [opp.id]: 'success' }));

      const newHistoryItem = {
        id: `trade-${Date.now()}`,
        pair: opp.pair,
        buyExchange: opp.buyExchange,
        sellExchange: opp.sellExchange,
        profit: opp.profitPotential,
        spread: opp.spread,
        tradeVolume: opp.profitPotential / (opp.spread / 100),
        timestamp: Date.now()
      };
      setHistory(prev => [...prev, newHistoryItem]);

      setTimeout(() => {
        setTradeStatuses(prev => {
          const newState = { ...prev };
          delete newState[opp.id];
          return newState;
        });
      }, 3000);
    }, 2000);
  };

  const handleConfirmTrade = () => {
    if (confirmingTrade) {
      handleTrade(confirmingTrade);
      setConfirmingTrade(null);
    }
  };

  const handleAiVerify = (opp: ArbitrageOpportunity) => {
    const prompt = `Audit: Check ${opp.pair} price difference between ${opp.buyExchange} and ${opp.sellExchange}. Spread: ${opp.spread.toFixed(2)}%. Analyze order book depth for slippage risk.`;
    if ((window as any).triggerNexusAi) {
      (window as any).triggerNexusAi(prompt);
    }
  };

  useEffect(() => {
