      sortBy === 'profit' ? b.profitPotential - a.profitPotential : b.spread - a.spread
    ));
  }, [sortBy]);

  // Visual component for Order Book Depth
  const DepthVisualizer = ({ opp }: { opp: ExtendedOpportunity }) => (
