          <span className={`text-xs px-2 py-0.5 rounded border ${opp.liquidityDepth === 'High' ? 'border-green-500/50 text-green-400 bg-green-500/10' : 'border-yellow-500/50 text-yellow-400 bg-yellow-500/10'}`}>
