             <div className="w-full bg-emerald-500/20 rounded-t-sm relative group" style={{height: `${opp.bidWall}%`}}>
                <div className="absolute top-0 w-full h-0.5 bg-emerald-500 shadow-[0_0_10px_#10b981]"></div>
                <div className="opacity-0 group-hover:opacity-100 absolute -top-8 right-0 bg-slate-800 text-xs p-1 rounded border border-slate-600 z-10 whitespace-nowrap">
                   Bid Vol: ${(opp.bidWall * 1250).toLocaleString()}
                </div>
             </div>
             <span className="text-[10px] text-emerald-500 font-mono">Bids</span>
          </div>
          {/* Ask Side (Red) */}
          <div className="flex-1 flex flex-col justify-end items-start gap-1 pl-2">
             <div className="w-full bg-red-500/20 rounded-t-sm relative group" style={{height: `${opp.askWall}%`}}>
                <div className="absolute top-0 w-full h-0.5 bg-red-500 shadow-[0_0_10px_#ef4444]"></div>
                <div className="opacity-0 group-hover:opacity-100 absolute -top-8 left-0 bg-slate-800 text-xs p-1 rounded border border-slate-600 z-10 whitespace-nowrap">
                   Ask Vol: ${(opp.askWall * 1250).toLocaleString()}
                </div>
             </div>
             <span className="text-[10px] text-red-500 font-mono">Asks</span>
          </div>
       </div>
       <div className="mt-2 text-[10px] text-slate-500 text-center">
          Order Book depth determines slippage risk. High walls = Safer execution.
       </div>
    </div>
