  Focus: ${selectedOppData ? selectedOppData.pair + ' Liquidity: ' + selectedOppData.liquidityDepth : 'General'}.`;

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 relative">
      {/* Header Stats / Exchange Latency */}
      <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
        {CEX_LIST.slice(0, 5).map((ex, i) => (
