            <img src={ex.logo} alt={ex.name} className="w-8 h-8 rounded-full bg-slate-700" />
            <div className="flex-1">
              <h3 className="font-bold text-slate-200 text-sm">{ex.name}</h3>
              <div className="flex items-center gap-1.5 mt-0.5">
                 <Wifi className={`w-3 h-3 ${i % 2 === 0 ? 'text-green-500' : 'text-emerald-400'}`} />
                 <span className="text-[10px] text-slate-400 font-mono">{45 + i * 12}ms</span>
              </div>
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
