import React, { useState, useEffect } from 'react';
import { ArrowRightLeft, TrendingUp, RefreshCw, AlertTriangle, Play, Loader2, Check, Clock, Filter, X, ShieldCheck, History, Sparkles, Zap, Radio, DollarSign, BarChart2, Activity, Bot, Wifi, Layers, ZoomIn, ArrowUp, ArrowDown } from 'lucide-react';
