            <div className="flex items-center gap-3">
               {/* Deep Scan Toggle */}
               <div className={`flex items-center gap-2 px-3 py-1.5 rounded-xl border transition-all ${deepScanMode ? 'bg-purple-500/10 border-purple-500/50' : 'bg-slate-800 border-slate-700'}`}>
                  <div className="flex flex-col">
                     <span className="text-[10px] uppercase font-bold text-slate-500">Deep Scan</span>
                     <span className={`text-[10px] font-mono ${deepScanMode ? 'text-purple-300' : 'text-slate-500'}`}>Filter Noise</span>
                  </div>
                  <button 
                     onClick={() => setDeepScanMode(!deepScanMode)}
                     className={`w-10 h-6 rounded-full transition-colors relative ${deepScanMode ? 'bg-purple-500' : 'bg-slate-600'}`}
                  >
                     <div className={`absolute top-1 h-4 w-4 rounded-full bg-white transition-all duration-200 ${deepScanMode ? 'left-5' : 'left-1'}`} />
                  </button>
               </div>

               {/* Bot Control */}
               <div className={`flex items-center gap-2 px-3 py-1.5 rounded-xl border transition-all ${isAutoTrading ? 'bg-indigo-500/10 border-indigo-500/50' : 'bg-slate-800 border-slate-700'}`}>
                  <div className="flex flex-col">
                     <span className="text-[10px] uppercase font-bold text-slate-500">Auto-Trade</span>
                     <span className="text-[10px] text-indigo-300 font-mono">&gt; ${autoTradeThreshold}</span>
                  </div>
                  <button 
                     onClick={() => setIsAutoTrading(!isAutoTrading)}
                     className={`w-10 h-6 rounded-full transition-colors relative ${isAutoTrading ? 'bg-indigo-500' : 'bg-slate-600'}`}
                  >
                     <div className={`absolute top-1 h-4 w-4 rounded-full bg-white transition-all duration-200 ${isAutoTrading ? 'left-5' : 'left-1'}`} />
                  </button>
               </div>

               <button 
                onClick={scanMarket}
                disabled={isScanning}
                className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-semibold transition-all ${isScanning ? 'bg-slate-700 text-slate-400 cursor-wait' : 'bg-primary text-white hover:bg-blue-600 shadow-lg shadow-blue-500/20'}`}
              >
                {isScanning ? <Loader2 className="w-4 h-4 animate-spin" /> : <ZoomIn className="w-4 h-4" />}
                {isScanning ? (deepScanMode ? 'Deep Scan...' : 'Scanning') : 'Scan'}
              </button>
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm text-slate-300">
              <thead className="bg-slate-900/50 text-slate-400 uppercase text-xs">
                <tr>
                  <th className="px-6 py-4">Pair</th>
                  <th className="px-6 py-4">Route</th>
                  <th className="px-6 py-4 text-right">Spread</th>
                  <th className="px-6 py-4 text-right">Profit Est.</th>
                  <th className="px-6 py-4 text-right">Liquidity</th>
                  <th className="px-6 py-4 text-center">Action</th>
