                  <tr>
                    <td colSpan={6} className="py-12 text-center text-slate-500">
                      <div className="flex flex-col items-center gap-3">
                        <Loader2 className="w-8 h-8 animate-spin text-primary" />
                        <span>{deepScanMode ? 'Analyzing Order Books & Depth...' : 'Scanning Prices...'}</span>
                      </div>
                    </td>
                  </tr>
                ) : opportunities.length === 0 ? (
                   <tr>
                    <td colSpan={6} className="py-12 text-center text-slate-500">
                       No opportunities found matching current filters.
                    </td>
                   </tr>
                ) : opportunities.map((opp) => (
                  <tr 
                    key={opp.id} 
                    className={`cursor-pointer transition-colors ${selectedDepthOpp === opp.id ? 'bg-slate-800/60' : 'hover:bg-slate-800/30'} ${tradeStatuses[opp.id] === 'loading' ? 'bg-indigo-900/10' : ''}`}
                    onClick={() => setSelectedDepthOpp(opp.id)}
                  >
                    <td className="px-6 py-4 font-bold text-white">
                      <div className="flex items-center gap-2">
                        {opp.pair}
                        {isAutoTrading && opp.profitPotential > autoTradeThreshold && (
                           <Bot className="w-3 h-3 text-indigo-400" />
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                       <div className="flex items-center gap-2 text-xs">
                          <span className="text-slate-400">{opp.buyExchange}</span>
                          <span className="text-slate-600">→</span>
                          <span className="text-slate-400">{opp.sellExchange}</span>
                       </div>
                    </td>
                    <td className="px-6 py-4 text-right">
                       <span className={`font-mono font-bold px-2 py-1 rounded transition-colors duration-300 ${opp.spread > 1 ? 'bg-emerald-500/10 text-emerald-400' : 'text-slate-400'}`}>
                         +{opp.spread.toFixed(2)}%
                       </span>
                    </td>
                    <td className="px-6 py-4 text-right font-mono font-bold text-white transition-all duration-300">${opp.profitPotential.toFixed(2)}</td>
                    <td className="px-6 py-4 text-right">
                        <span className={`text-[10px] uppercase font-bold ${
                            opp.liquidityDepth === 'High' ? 'text-green-400' : 
                            opp.liquidityDepth === 'Medium' ? 'text-yellow-400' : 'text-red-400'
                        }`}>
                            {opp.liquidityDepth}
                        </span>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2 justify-end" onClick={(e) => e.stopPropagation()}>
                        <button
                          onClick={() => handleAiVerify(opp)}
                          className="p-1.5 rounded-lg bg-purple-500/10 text-purple-400 hover:bg-purple-500 hover:text-white transition-colors"
                          title="Verify with AI Search"
                        >
                          <Sparkles className="w-4 h-4" />
