  { symbol: 'USDT', name: 'Tether', balance: '32,150.00', value: '$32,150.00', change: '0.0%' },
  { symbol: 'BTC', name: 'Bitcoin', balance: '0.25', value: '$16,100.00', change: '-1.2%' },
  { symbol: 'SOL', name: 'Solana', balance: '124.50', value: '$10,725.00', change: '+5.7%' },
];

