  { id: 'tx1', type: 'withdraw', asset: 'ETH', amount: '0.5', to: '0x4a...9f21', time: '2 mins ago', status: 'confirmed' },
  { id: 'tx2', type: 'swap', asset: 'USDT -> ETH', amount: '1000', to: 'Uniswap V3', time: '1 hour ago', status: 'confirmed' },
  { id: 'tx3', type: 'receive', asset: 'SOL', amount: '50.0', to: 'Wallet', time: '5 hours ago', status: 'confirmed' },
