                    className={`cursor-pointer transition-colors ${selectedDepthOpp === opp.id ? 'bg-slate-800/60' : 'hover:bg-slate-800/30'} ${tradeStatuses[opp.id] === 'loading' ? 'bg-indigo-900/10' : ''}`}
                    onClick={() => setSelectedDepthOpp(opp.id)}
