                      </div>
                    </td>
                    <td className="px-6 py-4">
                       <div className="flex items-center gap-2 text-xs">
                          <span className="text-slate-400">{opp.buyExchange}</span>
                          <span className="text-slate-600">→</span>
                          <span className="text-slate-400">{opp.sellExchange}</span>
                       </div>
                    </td>
                    <td className="px-6 py-4 text-right">
                       <span className={`font-mono font-bold px-2 py-1 rounded transition-colors duration-300 ${opp.spread > 1 ? 'bg-emerald-500/10 text-emerald-400' : 'text-slate-400'}`}>
                         +{opp.spread.toFixed(2)}%
                       </span>
                    </td>
                    <td className="px-6 py-4 text-right font-mono font-bold text-white transition-all duration-300">${opp.profitPotential.toFixed(2)}</td>
                    <td className="px-6 py-4 text-right">
                        <span className={`text-[10px] uppercase font-bold ${
                            opp.liquidityDepth === 'High' ? 'text-green-400' : 
                            opp.liquidityDepth === 'Medium' ? 'text-yellow-400' : 'text-red-400'
                        }`}>
                            {opp.liquidityDepth}
                        </span>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2 justify-end" onClick={(e) => e.stopPropagation()}>
                        <button
                          onClick={() => handleAiVerify(opp)}
                          className="p-1.5 rounded-lg bg-purple-500/10 text-purple-400 hover:bg-purple-500 hover:text-white transition-colors"
                          title="Verify with AI Search"
                        >
                          <Sparkles className="w-4 h-4" />
                        </button>
                        {tradeStatuses[opp.id] === 'loading' ? (
                          <button disabled className="bg-indigo-500/20 text-indigo-400 px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1 cursor-not-allowed w-24 justify-center">
                            <Bot className="w-3 h-3 animate-bounce" /> Auto
                          </button>
                        ) : tradeStatuses[opp.id] === 'success' ? (
                          <button disabled className="bg-emerald-500/20 text-emerald-400 px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1 border border-emerald-500/50 w-24 justify-center">
                            <Check className="w-3 h-3" /> Filled
                          </button>
                        ) : (
                          <button 
                            onClick={() => setConfirmingTrade(opp)}
                            className="bg-primary/10 hover:bg-primary text-primary hover:text-white border border-primary/50 hover:border-primary px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1 transition-all w-24 justify-center group"
                          >
                            <Play className="w-3 h-3 fill-current group-hover:scale-110 transition-transform" /> Trade
                          </button>
