                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Analytics / Depth Chart */}
        <div className="bg-surface border border-slate-800 rounded-2xl p-6 flex flex-col shadow-xl">
           {selectedOppData ? (
               <DepthVisualizer opp={selectedOppData} />
