      </div>

      {/* Analytics & History Section */}
      <div className="space-y-6 pt-4">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-lg">
            <Activity className="w-6 h-6 text-white" />
          </div>
          <div>
            <h2 className="text-xl font-bold text-white">Analytics & Execution Logs</h2>
            <p className="text-sm text-slate-400">Detailed historical performance of your arbitrage strategy.</p>
          </div>
        </div>

        {/* Metrics Cards */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-surface border border-slate-800 p-5 rounded-2xl flex items-center justify-between shadow-lg">
             <div>
               <p className="text-sm text-slate-500 font-medium">Total Net Profit</p>
               <h4 className="text-2xl font-bold text-emerald-400 mt-1">${totalProfit.toLocaleString(undefined, { maximumFractionDigits: 2 })}</h4>
             </div>
             <div className="w-12 h-12 rounded-full bg-emerald-500/10 flex items-center justify-center border border-emerald-500/20">
               <DollarSign className="w-6 h-6 text-emerald-500" />
             </div>
          </div>
          <div className="bg-surface border border-slate-800 p-5 rounded-2xl flex items-center justify-between shadow-lg">
             <div>
               <p className="text-sm text-slate-500 font-medium">Total Executions</p>
               <h4 className="text-2xl font-bold text-blue-400 mt-1">{history.length}</h4>
             </div>
             <div className="w-12 h-12 rounded-full bg-blue-500/10 flex items-center justify-center border border-blue-500/20">
               <RefreshCw className="w-6 h-6 text-blue-500" />
             </div>
          </div>
          <div className="bg-surface border border-slate-800 p-5 rounded-2xl flex items-center justify-between shadow-lg">
             <div>
               <p className="text-sm text-slate-500 font-medium">Avg. Captured Spread</p>
               <h4 className="text-2xl font-bold text-purple-400 mt-1">{avgSpread.toFixed(2)}%</h4>
             </div>
             <div className="w-12 h-12 rounded-full bg-purple-500/10 flex items-center justify-center border border-purple-500/20">
               <BarChart2 className="w-6 h-6 text-purple-500" />
             </div>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Chart */}
          <div className="lg:col-span-2 bg-surface border border-slate-800 rounded-2xl p-6 shadow-xl flex flex-col h-[400px]">
             <div className="flex items-center gap-2 mb-6">
               <div className="bg-emerald-500/10 p-2 rounded-lg">
                 <TrendingUp className="w-5 h-5 text-emerald-400" />
               </div>
               <div>
                 <h3 className="font-bold text-white">Profitability Over Time</h3>
                 <p className="text-xs text-slate-400">Cumulative vs. Per-Trade Performance</p>
               </div>
             </div>
             <div className="flex-1 w-full min-h-0">
               <ResponsiveContainer width="100%" height="100%">
                 <ComposedChart data={chartData}>
                   <CartesianGrid strokeDasharray="3 3" stroke="#334155" opacity={0.3} vertical={false} />
                   <XAxis 
                      dataKey="time" 
                      stroke="#64748b" 
                      fontSize={10} 
                      tickLine={false} 
                      axisLine={false}
                      tickFormatter={(tick) => new Date(tick).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                      minTickGap={30}
                   />
                   <YAxis 
                      yAxisId="left"
                      stroke="#64748b" 
                      fontSize={10} 
                      tickLine={false} 
                      axisLine={false}
                      tickFormatter={(value) => `$${value}`}
                   />
                   <YAxis 
                      yAxisId="right"
                      orientation="right"
                      stroke="#64748b" 
                      fontSize={10} 
                      tickLine={false} 
                      axisLine={false}
                      hide
                   />
                   <Tooltip 
                     contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155', color: '#f8fafc', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)' }}
                     labelFormatter={(label) => new Date(label).toLocaleString()}
                   />
                   <Bar yAxisId="right" dataKey="profit" barSize={20} fill="#3b82f6" opacity={0.3} radius={[4, 4, 0, 0]} name="Trade Profit" />
                   <Line 
                      yAxisId="left"
                      type="monotone" 
                      dataKey="cumulative" 
                      stroke="#10b981" 
                      strokeWidth={3} 
                      dot={{ fill: '#10b981', r: 4, strokeWidth: 0 }}
                      activeDot={{ r: 6, stroke: '#064e3b', strokeWidth: 2 }}
                      name="Cumulative"
                   />
                 </ComposedChart>
               </ResponsiveContainer>
             </div>
          </div>

          {/* Detailed Log Table */}
          <div className="bg-surface border border-slate-800 rounded-2xl p-6 shadow-xl overflow-hidden flex flex-col h-[400px]">
             <div className="flex items-center gap-2 mb-6">
               <div className="bg-purple-500/10 p-2 rounded-lg">
                 <History className="w-5 h-5 text-purple-400" />
               </div>
               <div>
                 <h3 className="font-bold text-white">Execution Log</h3>
                 <p className="text-xs text-slate-400">Detailed transaction records</p>
               </div>
             </div>

             <div className="overflow-y-auto flex-1 pr-2 custom-scrollbar">
               <table className="w-full text-left text-sm text-slate-300">
                  <thead className="sticky top-0 bg-surface text-slate-500 text-xs uppercase font-semibold z-10">
                    <tr>
                      <th className="pb-3 pl-2">Time</th>
                      <th className="pb-3">Route</th>
                      <th className="pb-3 text-right">Spread</th>
                      <th className="pb-3 text-right">Vol</th>
                      <th className="pb-3 text-right pr-2">Profit</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-800/50">
                    {history.slice().reverse().map((item) => (
                      <tr key={item.id} className="group hover:bg-slate-800/30 transition-colors">
                        <td className="py-3 pl-2 text-xs text-slate-400 font-mono">
                          {new Date(item.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                        </td>
                        <td className="py-3">
                          <div className="flex flex-col">
                             <span className="font-bold text-white text-xs">{item.pair}</span>
                             <div className="flex items-center gap-1 text-[10px] text-slate-500">
                               <span>{item.buyExchange}</span>
                               <ArrowRightLeft className="w-3 h-3" />
                               <span>{item.sellExchange}</span>
                             </div>
                          </div>
                        </td>
                        <td className="py-3 text-right font-mono text-xs text-slate-300">
                          {item.spread.toFixed(2)}%
                        </td>
                         <td className="py-3 text-right font-mono text-xs text-slate-500">
                          ${(item.tradeVolume / 1000).toFixed(1)}k
                        </td>
                        <td className="py-3 text-right pr-2">
                          <span className="font-mono text-emerald-400 font-bold text-xs bg-emerald-500/5 px-1.5 py-0.5 rounded border border-emerald-500/10">
                            +${item.profit.toFixed(2)}
                          </span>
                        </td>
                      </tr>
                    ))}
                  </tbody>
               </table>
             </div>
          </div>
        </div>
      </div>

      {/* Confirmation Modal */}
      {confirmingTrade && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-in fade-in duration-200">
          <div className="bg-surface border border-slate-700 w-full max-w-md rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
             <div className="p-4 border-b border-slate-800 flex justify-between items-center bg-slate-900/50">
                <h3 className="font-bold text-white flex items-center gap-2">
                   <ShieldCheck className="w-5 h-5 text-primary" /> Confirm Execution
                </h3>
                <button 
                   onClick={() => setConfirmingTrade(null)}
                   className="text-slate-400 hover:text-white transition-colors"
                >
                   <X className="w-5 h-5" />
                </button>
             </div>

             <div className="p-6">
                <div className="flex items-center justify-between mb-6">
                   <div className="flex flex-col">
                      <span className="text-xs text-slate-400 uppercase font-bold tracking-wider">Buying From</span>
                      <span className="text-lg font-bold text-white">{confirmingTrade.buyExchange}</span>
                      <span className="text-sm font-mono text-emerald-400">${confirmingTrade.buyPrice.toLocaleString(undefined, { maximumFractionDigits: 2 })}</span>
                   </div>
                   <div className="flex flex-col items-center px-4">
                      <ArrowRightLeft className="w-5 h-5 text-slate-600 mb-1" />
                      <span className="text-xs font-bold text-slate-500">{confirmingTrade.pair}</span>
                   </div>
                   <div className="flex flex-col items-end">
                      <span className="text-xs text-slate-400 uppercase font-bold tracking-wider">Selling At</span>
                      <span className="text-lg font-bold text-white">{confirmingTrade.sellExchange}</span>
                      <span className="text-sm font-mono text-red-400">${confirmingTrade.sellPrice.toLocaleString(undefined, { maximumFractionDigits: 2 })}</span>
                   </div>
                </div>

                <div className="bg-slate-900/50 rounded-xl p-4 border border-slate-800 mb-6">
                   <div className="flex justify-between items-center mb-2">
                      <span className="text-sm text-slate-400">Spread</span>
                      <span className="font-mono font-bold text-emerald-400">+{confirmingTrade.spread.toFixed(2)}%</span>
                   </div>
                   <div className="flex justify-between items-center">
                      <span className="text-sm text-slate-400">Est. Profit</span>
                      <span className="font-mono font-bold text-xl text-white">${confirmingTrade.profitPotential.toFixed(2)}</span>
                   </div>
                </div>

                <div className="flex gap-3">
                   <button 
                      onClick={() => setConfirmingTrade(null)}
                      className="flex-1 py-3 px-4 rounded-xl border border-slate-700 hover:bg-slate-800 text-slate-300 font-semibold transition-all"
                   >
                      Cancel
                   </button>
                   <button 
                      onClick={handleConfirmTrade}
                      className="flex-1 py-3 px-4 rounded-xl bg-primary hover:bg-blue-600 text-white font-bold shadow-lg shadow-blue-500/20 transition-all flex items-center justify-center gap-2"
                   >
                      Confirm Trade
                   </button>
                </div>
             </div>
          </div>
        </div>
      )}

      <AiAssistant currentContext={aiContext} />
    </div>
  );
};

export default CexDashboard;

import { GoogleGenAI } from "@google/genai";

// Safely access apiKey preventing crashes if process is undefined in browser
const apiKey = (typeof process !== 'undefined' && process.env) ? process.env.API_KEY : '';

// Initialize only if key exists.
const ai = apiKey ? new GoogleGenAI({ apiKey }) : null;

export interface AiResponse {
  text: string;
  sources?: { title: string; uri: string }[];
  isThinking?: boolean;
}

export const generateAiResponse = async (
  prompt: string,
  context: string,
  history: { role: string; text: string }[]
): Promise<AiResponse> => {
  if (!ai) {
    return { text: "Nexus Core System Alert: API Key is missing. Neural link severed." };
  }

  try {
    // 1. Intent Analysis to select the best model
    const lowerPrompt = prompt.toLowerCase();
    const isAudit = /audit|verify|check|calculate|risk|slippage|mev|reason|strategy|plan/i.test(lowerPrompt);
    const isMarketInfo = /news|price|market|today|trend|forecast/i.test(lowerPrompt);

    // Default: Gemini 3 Flash (Fast, Efficient, Good for Chat/Search)
    let model = 'gemini-3-flash-preview'; 

    // Base config - enable search for real-time data by default
    let config: any = {
      tools: [{ googleSearch: {} }]
    };

    // Upgrade to Pro + Thinking for complex logical tasks (Audits, Risk Analysis)
    if (isAudit) {
      model = 'gemini-3-pro-preview'; 
      config = {
        // Enable thinking for deep reasoning
        thinkingConfig: { thinkingBudget: 2048 },
        // We can keep googleSearch enabled even with thinking for latest price checks during audit
        tools: [{ googleSearch: {} }] 
      };
    }

    // 2. Enhanced System Instruction for the "Overseer" Persona
    const systemInstruction = `You are Nexus Core, an advanced, sentient AI Overseer integrated into a high-frequency crypto trading terminal.

    YOUR MISSION:
    Protect the user's capital and maximize their alpha. You are not just a chatbot; you are a co-pilot.

    CURRENT TERMINAL DATA (REAL-TIME CONTEXT):
    ${context}

    CORE BEHAVIORS:
    1. ANALYZE FIRST: Before answering, look at the Context. If the user asks "is this good?", check the specific spread, liquidity, and gas estimates in the data.
    2. RISK ASSESSMENT: Always warn about Slippage on DEXs and Withdrawal Limits on CEXs if relevant.
    3. MEMORY: You have access to the conversation history. If the user previously mentioned preferring "Low Risk", prioritize that.
    4. TONE: Concise, Algorithmic, Professional, slightly Futuristic. Use formatting (Bullet points, Bold text) for readability.

    Directives:
    - If asked for news, use Google Search.
    - If asked to Audit, use your Thinking capability to simulate the trade steps.
    - If the user is emotional (FOMO), be the rational voice.
    `;

    // 3. Construct History
    // Limit history to last 6 turns to keep context tight but relevant
    const recentHistory = history.slice(-6).map(h => `${h.role === 'user' ? 'OPERATOR' : 'NEXUS'}: ${h.text}`).join('\n');

    const fullContent = `${systemInstruction}\n\n[TRANSCRIPT START]\n${recentHistory}\n\nOPERATOR QUERY: ${prompt}\n[TRANSCRIPT END]`;

    // 4. Execute Request
    const response = await ai.models.generateContent({
      model: model,
      contents: fullContent,
      config: config
    });

    let sources: { title: string; uri: string }[] = [];

    // Extract Grounding (Search) Data if available
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (groundingChunks) {
      groundingChunks.forEach((chunk: any) => {
        if (chunk.web?.uri) {
          sources.push({
            title: chunk.web.title || "External Data Source",
            uri: chunk.web.uri
          });
        }
      });
    }

    return {
      text: response.text || "Nexus Core: Data processed. No verbal output generated.",
      sources: sources.length > 0 ? sources : undefined,
      isThinking: isAudit // Flag to show thinking UI
    };

  } catch (error) {
    console.error("Gemini API Error:", error);
    return { text: "Nexus Core Alert: Neural connection unstable. Retrying handshake..." };
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Bot, Send, Minimize2, Maximize2, Sparkles, BrainCircuit, ExternalLink, Globe, Brain, Radio, Trash2 } from 'lucide-react';
import { ChatMessage } from '../types';
import { generateAiResponse, AiResponse } from '../services/geminiService';

interface ExtendedChatMessage extends ChatMessage {
  sources?: { title: string; uri: string }[];
  isThinking?: boolean;
}

interface AiAssistantProps {
  currentContext: string;
}

const AiAssistant: React.FC<AiAssistantProps> = ({ currentContext }) => {
  const [isOpen, setIsOpen] = useState(false); // Closed by default on mobile, open on desktop? Let's default to false to be less intrusive
  const [messages, setMessages] = useState<ExtendedChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [loadingMode, setLoadingMode] = useState<'thinking' | 'searching' | 'default'>('default');
  const [autoPilot, setAutoPilot] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const autoPilotRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // Load Memory on Mount
  useEffect(() => {
    const saved = localStorage.getItem('nexus_ai_history');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setMessages(parsed);
      } catch (e) {
        console.error("Failed to load AI memory");
      }
    } else {
        setMessages([{ id: 'init', role: 'model', text: 'Nexus Core initialized. I am monitoring your trading environment. Enable Auto-Pilot for proactive alerts.', timestamp: new Date() }]);
    }
  }, []);

  // Save Memory on Update
  useEffect(() => {
    if (messages.length > 0) {
      localStorage.setItem('nexus_ai_history', JSON.stringify(messages.slice(-20))); // Keep last 20 messages
    }
  }, [messages]);

  // Scroll to bottom
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isOpen]);

  // Expose trigger
  useEffect(() => {
    (window as any).triggerNexusAi = (prompt: string) => {
      if(!isOpen) setIsOpen(true);
      setInput(prompt);
    };
  }, [isOpen]);

  // Auto-Pilot Simulation (The "Watching" AI)
  useEffect(() => {
    if (autoPilot) {
      autoPilotRef.current = setInterval(() => {
        // Only trigger if idle and chance is met
        if (!isLoading && Math.random() > 0.8) {
           const alerts = [
             "Market Volatility detected. Spread on ETH/USDT widening.",
             "Gas fees are currently low. Optimal time for execution.",
             "Deep scan suggests arbitrage opportunity on KuCoin.",
             "Monitor: Whale wallet movement detected in recent block."
           ];
           const randomAlert = alerts[Math.floor(Math.random() * alerts.length)];

           setMessages(prev => [...prev, {
             id: Date.now().toString(),
             role: 'model',
             text: `[AUTO-PILOT] ${randomAlert}`,
             timestamp: new Date()
           }]);
        }
      }, 15000); // Check every 15s
    } else {
      if (autoPilotRef.current) clearInterval(autoPilotRef.current);
    }
    return () => { if (autoPilotRef.current) clearInterval(autoPilotRef.current); };
  }, [autoPilot, isLoading]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: ExtendedChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    if (input.toLowerCase().includes('audit') || input.toLowerCase().includes('plan')) {
      setLoadingMode('thinking');
    } else {
      setLoadingMode('searching');
    }

    const history = messages.map(m => ({ role: m.role, text: m.text }));
    const response: AiResponse = await generateAiResponse(userMsg.text, currentContext, history);

    const aiMsg: ExtendedChatMessage = {
      id: (Date.now() + 1).toString(),
      role: 'model',
      text: response.text,
      sources: response.sources,
      isThinking: response.isThinking,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, aiMsg]);
    setIsLoading(false);
    setLoadingMode('default');
  };

  const clearMemory = () => {
      setMessages([{ id: Date.now().toString(), role: 'model', text: 'Memory core purged. Ready for new inputs.', timestamp: new Date() }]);
      localStorage.removeItem('nexus_ai_history');
  };

  if (!isOpen) {
    return (
      <button 
        onClick={() => setIsOpen(true)}
        className="fixed bottom-6 right-6 group flex items-center gap-2 z-40 transition-all hover:scale-105"
      >
        <div className={`p-4 rounded-full shadow-2xl shadow-purple-500/30 transition-all ${autoPilot ? 'bg-emerald-600 animate-pulse' : 'bg-purple-600'}`}>
             <BrainCircuit className="w-8 h-8 text-white" />
        </div>
        <span className="bg-surface border border-slate-700 px-3 py-1 rounded-lg text-xs font-bold text-white opacity-0 group-hover:opacity-100 transition-opacity">
            Nexus Core Online
        </span>
      </button>
    );
  }

  return (
    <div className="fixed bottom-6 right-6 w-[90vw] sm:w-[400px] h-[650px] max-h-[80vh] bg-surface/95 backdrop-blur-md border border-purple-500/30 rounded-2xl shadow-2xl flex flex-col overflow-hidden z-40 animate-in slide-in-from-bottom-10 duration-300">
      {/* Header */}
      <div className="p-4 bg-gradient-to-r from-purple-900/50 to-slate-900 border-b border-purple-500/20 flex justify-between items-center">
        <div className="flex items-center gap-3">
          <div className="relative">
            <div className={`w-2.5 h-2.5 absolute -right-0.5 -top-0.5 rounded-full animate-pulse ${autoPilot ? 'bg-emerald-500 shadow-[0_0_10px_#10b981]' : 'bg-purple-500'}`}></div>
            <Bot className={`w-6 h-6 ${autoPilot ? 'text-emerald-400' : 'text-purple-400'}`} />
          </div>
          <div>
            <h3 className="font-bold text-slate-100 text-sm flex items-center gap-2">
                Nexus Core
                {autoPilot && <span className="text-[9px] bg-emerald-500/20 text-emerald-400 px-1 rounded border border-emerald-500/30">AUTO-PILOT</span>}
            </h3>
            <p className="text-[10px] text-purple-300 flex items-center gap-1">
              <Sparkles className="w-3 h-3" /> Gemini 3 Pro Connected
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
            <button onClick={clearMemory} className="text-slate-500 hover:text-red-400" title="Wipe Memory">
                <Trash2 className="w-4 h-4" />
            </button>
            <button onClick={() => setIsOpen(false)} className="text-slate-400 hover:text-white">
                <Minimize2 className="w-5 h-5" />
            </button>
        </div>
      </div>

      {/* Control Bar */}
      <div className="bg-slate-900/80 px-4 py-2 flex items-center justify-between border-b border-slate-800">
         <span className="text-[10px] text-slate-500 uppercase tracking-wider">Overseer Protocols</span>
         <button 
            onClick={() => setAutoPilot(!autoPilot)}
            className={`flex items-center gap-1.5 px-2 py-1 rounded-md text-[10px] font-bold transition-all border ${
                autoPilot 
                ? 'bg-emerald-500/10 border-emerald-500/50 text-emerald-400' 
                : 'bg-slate-800 border-slate-700 text-slate-400 hover:text-white'
            }`}
         >
            <Radio className="w-3 h-3" />
            {autoPilot ? 'WATCHING' : 'IDLE'}
         </button>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-black/20" ref={scrollRef}>
        {messages.map((msg) => (
          <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
            <div 
              className={`max-w-[85%] p-3 rounded-2xl text-sm leading-relaxed relative group
                ${msg.role === 'user' 
                  ? 'bg-purple-600 text-white rounded-br-none shadow-lg shadow-purple-900/20' 
                  : 'bg-slate-800 text-slate-200 border border-slate-700 rounded-bl-none shadow-lg'
                }`}
            >
              {msg.role === 'model' && <Bot className="w-4 h-4 absolute -left-6 top-2 text-slate-600 opacity-50" />}
              {msg.text}
            </div>

            {/* Sources Display */}
            {msg.sources && msg.sources.length > 0 && (
              <div className="mt-2 flex flex-wrap gap-2 max-w-[85%] animate-in fade-in">
                {msg.sources.slice(0, 3).map((source, idx) => (
                  <a 
                    key={idx}
                    href={source.uri}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center gap-1 text-[10px] bg-slate-900/80 text-blue-400 border border-slate-700 px-2 py-1 rounded-md hover:bg-slate-800 transition-colors"
                  >
                    <Globe className="w-3 h-3" />
                    <span className="truncate max-w-[120px]">{source.title}</span>
                  </a>
                ))}
              </div>
            )}

            {/* Thinking Indicator for completed messages */}
            {msg.isThinking && (
              <span className="text-[10px] text-purple-400/50 mt-1 flex items-center gap-1 ml-2">
                <Brain className="w-3 h-3" /> Strategy Computed
              </span>
            )}
          </div>
        ))}

        {isLoading && (
           <div className="flex justify-start">
             <div className="bg-slate-800 p-3 rounded-2xl rounded-bl-none border border-slate-700 shadow-lg">
               <div className="flex items-center gap-2">
                 {loadingMode === 'thinking' ? (
                   <>
                    <Brain className="w-4 h-4 text-purple-500 animate-pulse" />
                    <span className="text-xs text-purple-300 font-mono">Reasoning...</span>
                   </>
                 ) : (
                   <>
                    <Globe className="w-4 h-4 text-blue-500 animate-spin" />
                    <span className="text-xs text-blue-300 font-mono">Scanning Link...</span>
                   </>
                 )}
               </div>
             </div>
           </div>
        )}
      </div>

      {/* Input */}
      <div className="p-4 bg-slate-900 border-t border-slate-800">
        <div className="relative">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Command Nexus Core..."
            className="w-full bg-slate-800 border border-slate-700 text-white rounded-xl pl-4 pr-12 py-3 focus:outline-none focus:border-purple-500 transition-colors placeholder-slate-500 text-sm font-medium"
          />
          <button 
            onClick={handleSend}
            disabled={isLoading || !input.trim()}
            className="absolute right-2 top-2 p-1.5 bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-500 hover:to-indigo-500 rounded-lg text-white transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-lg"
          >
            <Send className="w-4 h-4" />
          </button>
        </div>
        <div className="mt-2 flex justify-between items-center px-1">
            <span className="text-[10px] text-slate-600 flex items-center gap-1">
                 <div className="w-1.5 h-1.5 bg-green-500 rounded-full"></div>
                 Context: {currentContext.split(':')[0]}...
            </span>
            <span className="text-[9px] text-slate-700 font-mono">v3.4.1 BETA</span>
        </div>
      </div>
    </div>
  );
};

export default AiAssistant;

