// Extended type for internal use
interface ExtendedOpportunity extends ArbitrageOpportunity {
  liquidityDepth: 'High' | 'Medium' | 'Low';
  bidWall: number; // For visualization
  askWall: number; // For visualization
  trend?: 'up' | 'down';
}

// Ticker Data Interface
interface TickerItem {
  symbol: string;
  price: number;
  change: number;
}

const INITIAL_TICKER: TickerItem[] = [
  { symbol: 'BTC', price: 64230.50, change: 1.2 },
  { symbol: 'ETH', price: 3450.20, change: -0.5 },
  { symbol: 'SOL', price: 145.80, change: 2.1 },
  { symbol: 'BNB', price: 580.10, change: 0.8 },
  { symbol: 'XRP', price: 0.62, change: -1.1 },
  { symbol: 'ADA', price: 0.45, change: 0.5 },
  { symbol: 'AVAX', price: 35.20, change: 1.5 },
];

const CexDashboard: React.FC = () => {
  const [opportunities, setOpportunities] = useState<ExtendedOpportunity[]>(
    INITIAL_ARB_OPPS.map(o => ({...o, liquidityDepth: 'Medium', bidWall: 50, askWall: 50}))
  );
  const [isScanning, setIsScanning] = useState(false);
  const [tradeStatuses, setTradeStatuses] = useState<Record<string, 'idle' | 'loading' | 'success'>>({});
  const [lastUpdated, setLastUpdated] = useState<Date>(new Date());
  const [sortBy, setSortBy] = useState<'profit' | 'spread'>('profit');
  const [confirmingTrade, setConfirmingTrade] = useState<ExtendedOpportunity | null>(null);
  const [isLive, setIsLive] = useState(true);

  // Real-time Data States
  const [tickerData, setTickerData] = useState<TickerItem[]>(INITIAL_TICKER);
  const [streamStatus, setStreamStatus] = useState<'connected' | 'connecting' | 'stalled'>('connected');
  const [packetsPerSecond, setPacketsPerSecond] = useState(124);

  // Bot / Auto-Trade State
  const [isAutoTrading, setIsAutoTrading] = useState(false);
  const [autoTradeThreshold, setAutoTradeThreshold] = useState(150);

  // Deep Scan State
  const [deepScanMode, setDeepScanMode] = useState(false);
  const [selectedDepthOpp, setSelectedDepthOpp] = useState<string | null>(null);

  // Historical Data State
  const [history, setHistory] = useState<{
    id: string;
    pair: string;
    buyExchange: string;
    sellExchange: string;
    profit: number;
    spread: number;
    tradeVolume: number;
    timestamp: number;
  }[]>([]);

  // Initialize mock history
  useEffect(() => {
    const mockHistory = Array.from({ length: 8 }).map((_, i) => {
      const time = new Date();
      time.setHours(time.getHours() - (8 - i));
      time.setMinutes(Math.floor(Math.random() * 60));
      const spread = Math.random() * 1.5 + 0.1;
      const profit = Math.random() * 120 + 10;
      const volume = (profit / (spread / 100));

      return {
        id: `hist-${i}`,
        pair: ['BTC/USDT', 'ETH/USDT', 'SOL/USDT', 'AVAX/USDT'][Math.floor(Math.random() * 4)],
        buyExchange: ['Binance', 'KuCoin', 'Okx'][Math.floor(Math.random() * 3)],
        sellExchange: ['Coinbase', 'Kraken', 'Bybit'][Math.floor(Math.random() * 3)],
        profit: profit,
        spread: spread,
        tradeVolume: volume,
        timestamp: time.getTime()
      };
    });
    setHistory(mockHistory);
  }, []);

  // High-Frequency Real-Time Data Simulation
  useEffect(() => {
    if (!isLive) {
      setStreamStatus('stalled');
      setPacketsPerSecond(0);
      return;
    }

    setStreamStatus('connected');

    // Simulate packet fluctuation
    const packetInterval = setInterval(() => {
        setPacketsPerSecond(Math.floor(Math.random() * 50) + 100);
    }, 1000);

    // Independent Ticker Updates (Fast)
