    }, 1500);

    // Independent Opportunity Updates (Asynchronous feel)
    const oppInterval = setInterval(() => {
      setOpportunities(prev => {
        const updated = prev.map(opp => {
          // Only update some items to simulate real tick data arriving at different times
          if (Math.random() > 0.4) return opp;

          const fluctuation = (Math.random() * 0.004) - 0.002;
          const newBuyPrice = opp.buyPrice * (1 + fluctuation);
          const spreadNoise = (Math.random() * 0.002) - 0.001; 
          const newSellPrice = opp.sellPrice * (1 + fluctuation + spreadNoise);
          const profit = (newSellPrice - newBuyPrice) * (Math.random() * 10 + 1);
          const trend = newBuyPrice > opp.buyPrice ? 'up' : 'down';

          return {
            ...opp,
            buyPrice: newBuyPrice,
            sellPrice: newSellPrice,
            spread: ((newSellPrice - newBuyPrice) / newBuyPrice) * 100,
            profitPotential: profit,
            timestamp: Date.now(),
            trend: trend as 'up' | 'down'
          };
        });

        // Check Bot Logic on update
        if (isAutoTrading) {
            updated.forEach(opp => {
              if (deepScanMode && opp.liquidityDepth !== 'High') return;
              if (opp.profitPotential >= autoTradeThreshold && !tradeStatuses[opp.id]) {
                handleTrade(opp, true);
              }
            });
        }

        return updated;
      });
      setLastUpdated(new Date());
    }, 400); // 400ms tick rate for high frequency feel

    return () => {
        clearInterval(packetInterval);
        clearInterval(tickerInterval);
        clearInterval(oppInterval);
    };
