        const depth: 'High' | 'Medium' | 'Low' = rand > 0.7 ? 'High' : rand > 0.3 ? 'Medium' : 'Low';
        const trend = newBuy > opp.buyPrice ? 'up' : 'down';

        return {
          ...opp,
