  const [connectingWalletId, setConnectingWalletId] = useState<string | null>(null);
  const [localError, setLocalError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'portfolio' | 'withdraw' | 'activity' | 'security'>('portfolio');

  // Security Settings State
  const [securitySettings, setSecuritySettings] = useState({
    biometrics: false,
    largeTxAlert: true,
    autoDisconnect: false
  });

  // Withdraw State
  const [transferAsset, setTransferAsset] = useState(ASSETS[0]);
  const [recipient, setRecipient] = useState('');
  const [amount, setAmount] = useState('');
  const [isSending, setIsSending] = useState(false);
  const [txSuccess, setTxSuccess] = useState<string | null>(null);

  // Calculate Health Score based on settings
  const healthScore = useMemo(() => {
    let score = 40; // Base score
    if (securitySettings.biometrics) score += 20;
    if (securitySettings.largeTxAlert) score += 20;
    if (securitySettings.autoDisconnect) score += 20;
    return score;
  }, [securitySettings]);

  useEffect(() => {
    if (propError) setLocalError(propError);
  }, [propError]);

  if (!isOpen) return null;

  const handleConnect = async (wallet: Wallet) => {
    setConnectingWalletId(wallet.id);
    setLocalError(null);
    try {
      await onConnect(wallet);
    } catch (error) {
       // handled by prop
    } finally {
      setConnectingWalletId(null);
    }
  };

  const handleDisconnect = () => {
    onDisconnect();
    onClose();
  };

  const toggleSetting = (key: keyof typeof securitySettings) => {
    setSecuritySettings(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const initWithdraw = (assetSymbol: string) => {
    const asset = ASSETS.find(a => a.symbol === assetSymbol);
    if (asset) {
        setTransferAsset(asset);
        setActiveTab('withdraw');
        setAmount('');
        setRecipient('');
        setTxSuccess(null);
    }
  };

  const handleWithdrawTransaction = () => {
    if (!amount || !recipient) return;

    // Basic Validation Simulation
    if (parseFloat(amount) > parseFloat(transferAsset.balance.replace(',',''))) {
        setLocalError("Insufficient balance for withdrawal.");
        return;
    }

    setLocalError(null);
    setIsSending(true);

    // Simulate Network Request
    setTimeout(() => {
        setIsSending(false);
        setTxSuccess(`0x${Math.random().toString(16).slice(2)}...${Math.random().toString(16).slice(2)}`);
    }, 2500);
