import { GoogleGenAI } from "@google/genai";

export interface AiResponse {
  text: string;
  sources?: { title: string; uri: string }[];
  isThinking?: boolean;
}

export const generateAiResponse = async (
  prompt: string,
  context: string,
  history: { role: string; text: string }[]
): Promise<AiResponse> => {
  // Always create a new instance right before making an API call to ensure the latest API key is used.
  // Must use a named parameter { apiKey: process.env.API_KEY }.
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    // 1. Intent Analysis to select the best model
    const lowerPrompt = prompt.toLowerCase();
    const isAudit = /audit|verify|check|calculate|risk|slippage|mev|reason|strategy|plan/i.test(lowerPrompt);

    // Default: Gemini 3 Flash (Fast, Efficient, Good for Chat/Search)
    let model = 'gemini-3-flash-preview'; 

    // Base config - enable search for real-time data by default
    let config: any = {
      tools: [{ googleSearch: {} }]
    };

    // Upgrade to Pro + Thinking for complex logical tasks (Audits, Risk Analysis)
    if (isAudit) {
      model = 'gemini-3-pro-preview'; 
      config = {
        // Enable thinking for deep reasoning
        thinkingConfig: { thinkingBudget: 2048 },
        // We can keep googleSearch enabled even with thinking for latest price checks during audit
        tools: [{ googleSearch: {} }] 
      };
    }

    // 2. Enhanced System Instruction for the "Overseer" Persona
    const systemInstruction = `You are Nexus Core, an advanced, sentient AI Overseer integrated into a high-frequency crypto trading terminal.

    YOUR MISSION:
    Protect the user's capital and maximize their alpha. You are not just a chatbot; you are a co-pilot.

    CURRENT TERMINAL DATA (REAL-TIME CONTEXT):
    ${context}

    CORE BEHAVIORS:
    1. ANALYZE FIRST: Before answering, look at the Context. If the user asks "is this good?", check the specific spread, liquidity, and gas estimates in the data.
    2. RISK ASSESSMENT: Always warn about Slippage on DEXs and Withdrawal Limits on CEXs if relevant.
    3. MEMORY: You have access to the conversation history. If the user previously mentioned preferring "Low Risk", prioritize that.
    4. TONE: Concise, Algorithmic, Professional, slightly Futuristic. Use formatting (Bullet points, Bold text) for readability.

    Directives:
    - If asked for news, use Google Search.
    - If asked to Audit, use your Thinking capability to simulate the trade steps.
    - If the user is emotional (FOMO), be the rational voice.
    `;

    // 3. Construct History
    // Limit history to last 6 turns to keep context tight but relevant
    const recentHistory = history.slice(-6).map(h => `${h.role === 'user' ? 'OPERATOR' : 'NEXUS'}: ${h.text}`).join('\n');

    const fullContent = `${systemInstruction}\n\n[TRANSCRIPT START]\n${recentHistory}\n\nOPERATOR QUERY: ${prompt}\n[TRANSCRIPT END]`;

    // 4. Execute Request using the correct generateContent structure
    const response = await ai.models.generateContent({
      model: model,
      contents: fullContent,
      config: config
    });

    let sources: { title: string; uri: string }[] = [];

    // Extract Grounding (Search) Data if available
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (groundingChunks) {
      groundingChunks.forEach((chunk: any) => {
        if (chunk.web?.uri) {
          sources.push({
            title: chunk.web.title || "External Data Source",
            uri: chunk.web.uri
          });
        }
      });
    }

    // response.text is a property, not a method.
    return {
      text: response.text || "Nexus Core: Data processed. No verbal output generated.",
      sources: sources.length > 0 ? sources : undefined,
      isThinking: isAudit // Flag to show thinking UI
    };

  } catch (error) {
    console.error("Gemini API Error:", error);
    return { text: "Nexus Core Alert: Neural connection unstable. Handshake failed." };
  }
};

/**
 * Simulated CEX API Service
 * Mocking a high-frequency trading API for multi-leg arbitrage execution.
 */

export interface TradeLegResult {
  exchange: string;
  orderId: string;
  status: 'filled' | 'failed';
  executionPrice: number;
  fee: number;
}

export interface ArbExecutionResponse {
  success: boolean;
  txId: string;
  buyLeg: TradeLegResult;
  sellLeg: TradeLegResult;
  netProfit: number;
  message: string;
}

class MockCexApi {
  private generateId() {
    return Math.random().toString(36).substring(2, 15);
  }

  /**
   * Simulates executing a two-leg arbitrage order.
   * In reality, this would involve concurrent API calls to two different exchanges.
   */
  async executeArbitrageOrder(
    pair: string,
    buyEx: string,
    sellEx: string,
    buyPrice: number,
    sellPrice: number,
    volume: number
  ): Promise<ArbExecutionResponse> {
    // 1. Simulate Network Latency
    const latency = Math.floor(Math.random() * 800) + 400;
    await new Promise(resolve => setTimeout(resolve, latency));

    // 2. Chance of Execution Failure (e.g., Price Slippage or API Timeout)
    const failureChance = Math.random();
    if (failureChance > 0.95) {
      return {
        success: false,
        txId: this.generateId(),
        buyLeg: { exchange: buyEx, orderId: '', status: 'failed', executionPrice: 0, fee: 0 },
        sellLeg: { exchange: sellEx, orderId: '', status: 'failed', executionPrice: 0, fee: 0 },
        netProfit: 0,
        message: 'API Timeout: Sell leg execution failed due to exchange latency.'
      };
    }

    // 3. Simulate minor slippage (0.01% - 0.05%)
    const slippage = 1 - (Math.random() * 0.0005);
    const effectiveBuyPrice = buyPrice * (1 + (1 - slippage));
    const effectiveSellPrice = sellPrice * slippage;

    // 4. Calculate Fees (Simulating standard 0.1% spot fee)
    const buyFee = (volume * effectiveBuyPrice) * 0.001;
    const sellFee = (volume * effectiveSellPrice) * 0.001;

    const grossProfit = (effectiveSellPrice - effectiveBuyPrice) * volume;
    const netProfit = grossProfit - (buyFee + sellFee);

    return {
      success: true,
      txId: `NEX-${this.generateId().toUpperCase()}`,
      buyLeg: {
        exchange: buyEx,
        orderId: `ORD-${this.generateId().toUpperCase()}`,
        status: 'filled',
        executionPrice: effectiveBuyPrice,
        fee: buyFee
      },
      sellLeg: {
        exchange: sellEx,
        orderId: `ORD-${this.generateId().toUpperCase()}`,
        status: 'filled',
        executionPrice: effectiveSellPrice,
        fee: sellFee
      },
      netProfit: netProfit,
      message: 'Arbitrage strategy executed successfully across both legs.'
    };
  }
}

