import { GoogleGenAI, Type } from "@google/genai";
import { OptimizationResult } from "../types";

export interface AiResponse {
  text: string;
  sources?: { title: string; uri: string }[];
  isThinking?: boolean;
}

export const generateAiResponse = async (
  prompt: string,
  context: string,
  history: { role: string; text: string }[]
): Promise<AiResponse> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const lowerPrompt = prompt.toLowerCase();
    const isAudit = /audit|verify|check|calculate|risk|slippage|mev|reason|strategy|plan/i.test(lowerPrompt);

    let model = 'gemini-3-flash-preview'; 
    let config: any = { tools: [{ googleSearch: {} }] };

    if (isAudit) {
      model = 'gemini-3-pro-preview'; 
      config = {
        thinkingConfig: { thinkingBudget: 2048 },
        tools: [{ googleSearch: {} }] 
      };
    }

    const systemInstruction = `You are Nexus Core, an advanced AI Overseer. Your goal is to provide alpha and protect capital. Context: ${context}`;
    const recentHistory = history.slice(-6).map(h => `${h.role === 'user' ? 'OPERATOR' : 'NEXUS'}: ${h.text}`).join('\n');
    const fullContent = `${systemInstruction}\n\n${recentHistory}\n\nOPERATOR QUERY: ${prompt}`;

    const response = await ai.models.generateContent({
      model: model,
      contents: fullContent,
      config: config
    });

    let sources: { title: string; uri: string }[] = [];
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (groundingChunks) {
      groundingChunks.forEach((chunk: any) => {
        if (chunk.web?.uri) {
          sources.push({ title: chunk.web.title || "External Data Source", uri: chunk.web.uri });
        }
      });
    }

    return {
      text: response.text || "Nexus Core: Data processed.",
      sources: sources.length > 0 ? sources : undefined,
      isThinking: isAudit
    };
  } catch (error) {
    console.error("Gemini API Error:", error);
    return { text: "Nexus Core Alert: Connection unstable." };
  }
};

/**
 * Uses Gemini to analyze performance data and suggest parameter optimizations.
 */
export const getNeuralOptimization = async (
  marketData: string,
  performanceHistory: string
): Promise<OptimizationResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Perform a neural optimization for a high-frequency CEX arbitrage bot.

      CURRENT MARKET STATE:
      ${marketData}

      PERFORMANCE LOGS:
      ${performanceHistory}

      Analyze the win/loss ratio and current spreads. Recommend:
      1. suggestedThreshold: The dollar profit minimum per trade to maximize net gains.
      2. deepScanRecommended: Whether to enable deep order book filtering (reduce noise) or fast scan (catch small ticks).
      3. reasoning: A concise 1-sentence logic for the change.
      4. confidenceScore: 0.0 to 1.0.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            suggestedThreshold: { type: Type.NUMBER },
            deepScanRecommended: { type: Type.BOOLEAN },
            reasoning: { type: Type.STRING },
            confidenceScore: { type: Type.NUMBER }
          },
          required: ["suggestedThreshold", "deepScanRecommended", "reasoning", "confidenceScore"]
        }
      }
    });

    const result = JSON.parse(response.text || "{}");
    return result as OptimizationResult;
  } catch (error) {
    console.error("Optimization failed:", error);
    throw error;
  }
};

