  const [recipient, setRecipient] = useState('');
  const [amount, setAmount] = useState('');
  const [isSending, setIsSending] = useState(false);
  const [txId, setTxId] = useState<string | null>(null);

  const [securitySettings, setSecuritySettings] = useState({
    biometrics: false,
    largeTxAlert: true,
    autoDisconnect: false
  });

  const healthScore = useMemo(() => {
    let score = 40; 
    if (securitySettings.biometrics) score += 20;
    if (securitySettings.largeTxAlert) score += 20;
    if (securitySettings.autoDisconnect) score += 20;
    if (activeWallet?.isValidated) score += 20;
    return Math.min(score, 100);
  }, [securitySettings, activeWallet]);

  useEffect(() => {
    if (propError) setLocalError(propError);
  }, [propError]);

  if (!isOpen) return null;

  const handleConnect = async (wallet: Wallet) => {
    setConnectingWalletId(wallet.id);
    setLocalError(null);
    try {
      await onConnect(wallet);
    } catch (error) {
       // handled by prop
    } finally {
      setConnectingWalletId(null);
    }
  };

  const triggerSecurityAudit = () => {
    if (!activeWallet) return;
    setIsAuditing(true);

    setTimeout(() => {
      setIsAuditing(false);
      const prompt = `Perform a deep security audit for wallet ${activeWallet.address}. Check for high-risk token approvals on DEXs, interaction with blacklisted contracts, and provide a threat level score. Current Balance: ${activeWallet.balance}.`;
      if ((window as any).triggerNexusAi) {
        (window as any).triggerNexusAi(prompt);
      }
    }, 2000);
  };

  const validateAddress = (addr: string) => {
    return /^0x[a-fA-F0-9]{40}$/.test(addr) || addr.length > 20; // Basic check
  };

  const goToPreview = () => {
    if (!amount || parseFloat(amount) <= 0) {
      setLocalError("Please enter a valid amount.");
      return;
    }
    if (!recipient || !validateAddress(recipient)) {
      setLocalError("Please enter a valid recipient address.");
      return;
    }
    if (parseFloat(amount) > parseFloat(transferAsset.balance.replace(',', ''))) {
      setLocalError("Insufficient balance for withdrawal.");
      return;
    }
    setLocalError(null);
    setWithdrawStep('preview');
  };

  const handleWithdrawTransaction = () => {
    setLocalError(null);
    setIsSending(true);

    // Neural Verification Simulation
    setTimeout(() => {
        setIsSending(false);
        const newTxId = `0x${Math.random().toString(16).slice(2, 10)}...${Math.random().toString(16).slice(2, 6)}`;
        setTxId(newTxId);
        setWithdrawStep('success');
    }, 3000);
  };

  const resetWithdrawal = () => {
    setWithdrawStep('input');
    setAmount('');
    setRecipient('');
    setTxId(null);
    setLocalError(null);
  };

  return (
