                <h3 className="text-lg font-bold text-white">Validating Wallet Identity</h3>
                <p className="text-sm text-slate-500 mt-2 px-8">Nexus Core is performing a neural handshake with the blockchain to ensure account integrity.</p>
              </div>
            </div>
          )}

          {activeWallet && !isValidating && (
