              <div className="pt-2 border-t border-slate-800">
                 <button onClick={onDisconnect} className="w-full py-3 rounded-xl border border-red-500/20 bg-red-500/10 text-red-400 hover:bg-red-500/20 hover:text-red-300 font-semibold transition-all flex items-center justify-center gap-2">
                   <LogOut className="w-4 h-4" /> Disconnect Wallet
