const CexDashboard: React.FC = () => {
  // --- States ---
  const [opportunities, setOpportunities] = useState<ExtendedOpportunity[]>(
    INITIAL_ARB_OPPS.map(o => ({ ...o, liquidityDepth: 'Medium', bidWall: 50, askWall: 50 }))
  );
  const [tickerData, setTickerData] = useState<TickerItem[]>(INITIAL_TICKER);
  const [tradeStatuses, setTradeStatuses] = useState<Record<string, 'idle' | 'transmitting' | 'filled' | 'failed'>>({});
  const [isLive, setIsLive] = useState(true);
  const [streamStatus, setStreamStatus] = useState<'connected' | 'connecting' | 'stalled'>('connecting');
  const [packetsPerSecond, setPacketsPerSecond] = useState(0);
  const [lastUpdated, setLastUpdated] = useState<Date>(new Date());

  const [isAutoTrading, setIsAutoTrading] = useState(false);
  const [autoTradeThreshold, setAutoTradeThreshold] = useState(150);
  const [deepScanMode, setDeepScanMode] = useState(false);
  const [selectedDepthOpp, setSelectedDepthOpp] = useState<string | null>(null);

  // Bot Evolution / Upgrade State
  const [botLevel, setBotLevel] = useState(1);
  const [botXp, setBotXp] = useState(45); // Progress to next level (0-100)
  const [isUpgrading, setIsUpgrading] = useState(false);
  const [lastUpgradeFeature, setLastUpgradeFeature] = useState<string>("Basic Arbitrage Handshake");

  // AI Optimization State
  const [isOptimizing, setIsOptimizing] = useState(false);
  const [lastAiOptimization, setLastAiOptimization] = useState<OptimizationResult | null>(null);
  const [autoApplyOptimization, setAutoApplyOptimization] = useState(false);

  const [history, setHistory] = useState<{
    id: string;
    pair: string;
    buyExchange: string;
    sellExchange: string;
    profit: number;
    spread: number;
    tradeVolume: number;
    timestamp: number;
    status: 'filled' | 'failed';
  }[]>([]);

  // --- Refs for WebSocket Simulation ---
  const wsRef = useRef<number | null>(null);
  const packetRef = useRef(0);

  // --- Initial History Hydration ---
  useEffect(() => {
    const mockHistory = Array.from({ length: 8 }).map((_, i) => ({
      id: `hist-${i}`,
      pair: ['BTC/USDT', 'ETH/USDT', 'SOL/USDT'][Math.floor(Math.random() * 3)],
      buyExchange: 'KuCoin',
      sellExchange: 'Binance',
      profit: Math.random() * 120 + 10,
      spread: Math.random() * 1.5 + 0.1,
      tradeVolume: 25000,
      timestamp: Date.now() - (8 - i) * 3600000,
      status: 'filled' as const
    }));
    setHistory(mockHistory);
  }, []);

  // --- WebSocket Price & Opportunity Stream ---
  useEffect(() => {
    if (!isLive) {
      setStreamStatus('stalled');
      setPacketsPerSecond(0);
      return;
    }

    setStreamStatus('connecting');
    const handshake = setTimeout(() => setStreamStatus('connected'), 1500);

    const tickInterval = 200; 
    wsRef.current = window.setInterval(() => {
      packetRef.current += Math.floor(Math.random() * 15) + 5;

      setTickerData(prev => prev.map(item => ({
        ...item,
        price: item.price * (1 + (Math.random() * 0.002 - 0.001)),
        change: item.change + (Math.random() * 0.05 - 0.025)
      })));

      setOpportunities(prev => prev.map(opp => {
        const fluctuation = (Math.random() * 0.003) - 0.0015;
        const newBuyPrice = opp.buyPrice * (1 + fluctuation);
        const spreadNoise = (Math.random() * 0.001) - 0.0005;
        const newSellPrice = opp.sellPrice * (1 + fluctuation + spreadNoise);
        return {
          ...opp,
          buyPrice: newBuyPrice,
          sellPrice: newSellPrice,
          spread: ((newSellPrice - newBuyPrice) / newBuyPrice) * 100,
          profitPotential: (newSellPrice - newBuyPrice) * 10,
          timestamp: Date.now(),
          trend: newBuyPrice > opp.buyPrice ? 'up' : 'down'
        };
      }));

      setLastUpdated(new Date());
    }, tickInterval);

    const ppsInterval = setInterval(() => {
      setPacketsPerSecond(packetRef.current);
      packetRef.current = 0;
    }, 1000);

    return () => {
      if (wsRef.current) clearInterval(wsRef.current);
      clearInterval(ppsInterval);
      clearTimeout(handshake);
    };
  }, [isLive]);

  // --- Bot Logic ---
  useEffect(() => {
    if (isAutoTrading && opportunities.length > 0 && streamStatus === 'connected') {
      const best = opportunities.find(o => 
        o.profitPotential >= autoTradeThreshold && 
        !tradeStatuses[o.id] &&
        (deepScanMode ? o.liquidityDepth === 'High' : true)
      );
      if (best) handleTrade(best);
    }
  }, [isAutoTrading, opportunities, autoTradeThreshold, streamStatus, deepScanMode]);

  const handleTrade = async (opp: ArbitrageOpportunity) => {
    if (tradeStatuses[opp.id] === 'transmitting' || tradeStatuses[opp.id] === 'filled') return;
    setTradeStatuses(prev => ({ ...prev, [opp.id]: 'transmitting' }));

    try {
      const response = await cexApi.executeArbitrageOrder(opp.pair, opp.buyExchange, opp.sellExchange, opp.buyPrice, opp.sellPrice, 1);
      if (response.success) {
        setTradeStatuses(prev => ({ ...prev, [opp.id]: 'filled' }));
        setHistory(prev => [...prev, {
          id: response.txId,
          pair: opp.pair,
          buyExchange: opp.buyExchange,
          sellExchange: opp.sellExchange,
          profit: response.netProfit,
          spread: opp.spread,
          tradeVolume: opp.buyPrice,
          timestamp: Date.now(),
          status: 'filled'
        }]);
        // Increase Bot XP on success
        setBotXp(prev => Math.min(100, prev + 5));
      } else {
        setTradeStatuses(prev => ({ ...prev, [opp.id]: 'failed' }));
      }
      setTimeout(() => setTradeStatuses(prev => {
        const next = { ...prev };
        delete next[opp.id];
        return next;
      }), 5000);
    } catch (e) {
      setTradeStatuses(prev => ({ ...prev, [opp.id]: 'failed' }));
    }
  };

  const handleUpgrade = async () => {
    if (botXp < 100 || isUpgrading) return;
    setIsUpgrading(true);

    // Call Gemini to get a "technical evolution" description
    try {
      const prompt = `Synthesize a high-tech arbitrage bot upgrade description for version v${(botLevel + 1).toFixed(1)}. Focus on specific technical concepts like MEV-shielding, nano-latency routing, or neural spread prediction. One sentence only.`;
