          {[...tickerData, ...tickerData].map((item, i) => (
            <div key={i} className="flex items-center gap-2 text-xs font-mono">
              <span className="font-bold text-slate-300">{item.symbol}/USDT</span>
              <span className="text-white font-bold">${item.price.toFixed(2)}</span>
              <span className={`text-[10px] ${item.change >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                {item.change >= 0 ? '▲' : '▼'}{Math.abs(item.change).toFixed(2)}%
              </span>
            </div>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        {/* Main Terminal Area */}
        <div className="lg:col-span-8 space-y-6">
          {/* Arbitrage Scanner Terminal */}
          <div className="bg-surface border border-slate-800 rounded-2xl overflow-hidden shadow-xl">
            <div className="p-6 border-b border-slate-800 flex flex-wrap justify-between items-center gap-4 bg-gradient-to-r from-surface to-slate-900">
              <div className="flex flex-col">
                <h2 className="text-xl font-bold text-white flex items-center gap-2">
                  <Server className="text-primary w-5 h-5" /> 
                  Nexus Terminal <span className="text-[10px] text-primary/50 font-mono">v{botLevel.toFixed(1)}_WSS</span>
                </h2>
                <div className="flex items-center gap-3 mt-1.5">
                   <div className="flex items-center gap-1.5">
                      <div className={`w-1.5 h-1.5 rounded-full ${streamStatus === 'connected' ? 'bg-green-500' : streamStatus === 'connecting' ? 'bg-yellow-500 animate-pulse' : 'bg-red-500'}`} />
                      <span className={`text-[10px] font-bold uppercase tracking-tighter ${streamStatus === 'connected' ? 'text-green-400' : 'text-slate-500'}`}>
                        {streamStatus}
                      </span>
                   </div>
                   <span className="text-slate-800 text-xs">|</span>
                   <span className="text-[10px] text-slate-500 font-mono">{packetsPerSecond} packets/sec</span>
                </div>
              </div>

              <div className="flex items-center gap-3">
                 <div className="flex bg-slate-900 rounded-xl p-1 border border-slate-800">
