                      <span className="text-lg font-mono font-black text-white">${autoTradeThreshold}</span>
                   </div>
                   <input type="range" min="10" max="500" step="10" value={autoTradeThreshold} onChange={(e) => setAutoTradeThreshold(parseInt(e.target.value))} className="w-full h-1.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-indigo-500" />
                </div>

                <button 
                  onClick={handleNeuralConsult}
                  className="w-full p-4 rounded-xl border border-purple-500/30 bg-purple-500/10 text-purple-400 hover:bg-purple-500/20 transition-all flex items-center justify-center gap-3 group"
                >
