      </div>

      <AiAssistant currentContext={`BOT_VER: v${botLevel.toFixed(1)} | XP: ${botXp}% | TOTAL_PROFIT: $${totalProfit.toFixed(2)} | WIN_RATE: ${winRate.toFixed(1)}%`} />
    </div>
  );
};

