  { symbol: 'BTC', price: 64230.50, change: 1.2 },
  { symbol: 'ETH', price: 3450.20, change: -0.5 },
  { symbol: 'SOL', price: 145.80, change: 2.1 },
  { symbol: 'BNB', price: 580.10, change: 0.8 },
