                </h2>
                <div className="flex items-center gap-3 mt-1.5">
                   <div className="flex items-center gap-1.5">
                      <div className={`w-1.5 h-1.5 rounded-full ${streamStatus === 'connected' ? 'bg-green-500' : 'bg-red-500'}`} />
                      <span className={`text-[10px] font-bold uppercase tracking-tighter ${streamStatus === 'connected' ? 'text-green-400' : 'text-slate-500'}`}>
                        {streamStatus}
