/**
 * MockWebSocket Class
 * Simulates the browser's WebSocket API for internal streaming logic.
 */
class MockWebSocket {
  onMessage: (data: any) => void = () => {};
  onStatusChange: (status: 'connected' | 'connecting' | 'stalled') => void = () => {};
  private interval: any = null;
  private status: 'connected' | 'connecting' | 'stalled' = 'connecting';

  constructor() {
    this.connect();
  }

  connect() {
    this.status = 'connecting';
    this.onStatusChange(this.status);

    // Simulate handshake
    setTimeout(() => {
      this.status = 'connected';
      this.onStatusChange(this.status);
      this.startStreaming();
    }, 2000);
  }

  private startStreaming() {
    this.interval = setInterval(() => {
      // Simulate random network stalling (5% chance)
      if (Math.random() < 0.05 && this.status === 'connected') {
        this.status = 'stalled';
        this.onStatusChange(this.status);
        setTimeout(() => {
          if (this.status === 'stalled') {
            this.status = 'connected';
            this.onStatusChange(this.status);
          }
        }, 1500);
        return;
      }

      if (this.status === 'connected') {
        this.onMessage({
          type: 'TICKER_UPDATE',
          data: {
            index: Math.floor(Math.random() * INITIAL_TICKER.length),
            priceShift: (Math.random() * 0.001) - 0.0005,
            changeShift: (Math.random() * 0.02) - 0.01
          }
        });

        this.onMessage({
          type: 'ARB_UPDATE',
          data: {
            index: Math.floor(Math.random() * INITIAL_ARB_OPPS.length),
            fluctuation: (Math.random() * 0.002) - 0.001,
            spreadNoise: (Math.random() * 0.0005) - 0.00025
          }
        });
      }
    }, 250);
  }

  disconnect() {
    if (this.interval) clearInterval(this.interval);
    this.status = 'stalled';
    this.onStatusChange(this.status);
  }
}

