            const oldBuy = opp.buyPrice;
            opp.buyPrice *= (1 + msg.data.fluctuation);
            opp.sellPrice *= (1 + msg.data.fluctuation + msg.data.spreadNoise);
            opp.spread = ((opp.sellPrice - opp.buyPrice) / opp.buyPrice) * 100;
            opp.profitPotential = (opp.sellPrice - opp.buyPrice) * 10;
            opp.trend = opp.buyPrice > oldBuy ? 'up' : 'down';
            opp.lastUpdated = Date.now();
          }
          return next;
        });
      }
    };

    const ppsInterval = setInterval(() => {
      setPacketsPerSecond(packetCounter.current);
      packetCounter.current = 0;
