import { BrowserProvider, formatEther } from 'ethers';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<'CEX' | 'DEX'>('CEX');
  const [isWalletModalOpen, setIsWalletModalOpen] = useState(false);
  const [activeWallet, setActiveWallet] = useState<(Wallet & { isValidated?: boolean }) | null>(null);
  const [connectionError, setConnectionError] = useState<string | null>(null);
  const [isValidating, setIsValidating] = useState(false);

  // Connection Stability State
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Monitor Network Status
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const handleConnectWallet = async (wallet: Wallet) => {
    setConnectionError(null);
    setIsValidating(true);

    try {
      let connectionData: Partial<Wallet> = {};

      if (wallet.id === 'metamask' && (window as any).ethereum) {
        const ethereum = (window as any).ethereum;
        const provider = new BrowserProvider(ethereum);
        await provider.send("eth_requestAccounts", []);
        const signer = await provider.getSigner();
        const address = await signer.getAddress();
        const balanceBigInt = await provider.getBalance(address);
        connectionData = {
          address: `${address.slice(0, 6)}...${address.slice(-4)}`,
          balance: `${parseFloat(formatEther(balanceBigInt)).toFixed(4)} ETH`,
          tier: 'Elite',
          trustScore: 99.4,
          lastAudit: Date.now()
        };
      } else {
        // Fallback to simulated high-fidelity connection
        await new Promise(resolve => setTimeout(resolve, 2000));
        connectionData = {
          address: '0x71C...9A21',
          balance: wallet.id === 'phantom' ? '124.5 SOL' : '14.5 ETH',
          tier: 'Neural',
          trustScore: 98.7,
          lastAudit: Date.now()
        };
      }

      // Final handshake simulation
      await new Promise(resolve => setTimeout(resolve, 500)); 

      setActiveWallet({
        ...wallet,
        ...connectionData,
        connected: true,
        isValidated: true
      });
      localStorage.setItem('connectedWalletId', wallet.id);
      setIsValidating(false);

    } catch (error: any) {
      setIsValidating(false);
      const errorMessage = error?.message || "Handshake failed: Provider rejected signature.";
      setConnectionError(errorMessage);
      throw error;
    }
  };

  const handleDisconnect = () => {
    setActiveWallet(null);
    localStorage.removeItem('connectedWalletId');
  };

  return (
    <div className="min-h-screen bg-background text-slate-200 font-sans selection:bg-primary/30">
      <Navbar 
        activeView={activeView} 
        setActiveView={setActiveView} 
        activeWallet={activeWallet}
        onConnectClick={() => setIsWalletModalOpen(true)}
        isOnline={isOnline}
      />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 pb-32">
        <div className="mb-10 animate-in fade-in slide-in-from-top-4 duration-700">
          <div className="flex items-center gap-3 mb-2">
             <div className="w-2 h-8 bg-primary rounded-full" />
             <h2 className="text-4xl font-black text-white tracking-tighter uppercase">
               {activeView === 'CEX' ? 'Exchange Monitor' : 'DeFi Terminal'}
             </h2>
          </div>
          <p className="text-slate-500 font-medium max-w-2xl border-l border-slate-800 pl-6 ml-1">
            {activeView === 'CEX' 
              ? 'Aggregating real-time order book spreads across the global centralized liquidity cluster.' 
              : 'Permissionless flash loan deployment and multi-protocol liquidity analysis via Nexus Neural Engine.'}
          </p>
        </div>

        {activeView === 'CEX' ? <CexDashboard /> : <DexDashboard />}
      </main>

      <WalletModal 
        isOpen={isWalletModalOpen} 
        onClose={() => { setIsWalletModalOpen(false); setConnectionError(null); }}
        activeWallet={activeWallet}
        onConnect={handleConnectWallet}
        onDisconnect={handleDisconnect}
        error={connectionError}
        isValidating={isValidating}
      />
    </div>
  );
};

