/**
 * MockWebSocket Class
 * High-fidelity simulation of an exchange WebSocket stream.
 */
class MockWebSocket {
  onMessage: (data: any) => void = () => {};
  onStatusChange: (status: 'connected' | 'connecting' | 'stalled') => void = () => {};
  private interval: any = null;
  private status: 'connected' | 'connecting' | 'stalled' = 'connecting';

  constructor() {
    this.connect();
  }

  connect() {
    this.status = 'connecting';
    this.onStatusChange(this.status);

    // Simulate handshake and authentication
    setTimeout(() => {
      this.status = 'connected';
      this.onStatusChange(this.status);
      this.startStreaming();
    }, 1500);
  }

  private startStreaming() {
    this.interval = setInterval(() => {
      // 3% chance of stream stalling/dropping
      if (Math.random() < 0.03 && this.status === 'connected') {
        this.status = 'stalled';
        this.onStatusChange(this.status);
        setTimeout(() => {
          if (this.status === 'stalled') {
            this.status = 'connected';
            this.onStatusChange(this.status);
          }
        }, 2000);
        return;
      }

      if (this.status === 'connected') {
        // Stream Ticker Data
        this.onMessage({
          type: 'TICKER',
          data: {
            index: Math.floor(Math.random() * INITIAL_TICKER.length),
            shift: (Math.random() * 0.002) - 0.001
          }
        });

        // Stream Arbitrage Opportunities (Order Book Updates)
        if (Math.random() > 0.4) { // Increased frequency for price updates
          this.onMessage({
            type: 'ARB_SCAN',
            data: {
              index: Math.floor(Math.random() * INITIAL_ARB_OPPS.length),
              noise: (Math.random() * 0.001) - 0.0005
            }
          });
        }
      }
    }, 150); // Fast sub-second updates
  }

  disconnect() {
    if (this.interval) clearInterval(this.interval);
    this.status = 'stalled';
    this.onStatusChange(this.status);
  }
}

