    socketRef.current = socket;

    socket.onStatusChange = (status) => {
      setStreamStatus(status);
    };

    socket.onMessage = (msg) => {
      packetRef.current += 1;

      if (msg.type === 'TICKER') {
        setTickerData(prev => {
          const next = [...prev];
          const item = next[msg.data.index];
          if (item) {
            item.price *= (1 + msg.data.shift);
            item.lastUpdate = Date.now();
          }
          return next;
        });
      }

      if (msg.type === 'ARB_SCAN') {
        setOpportunities(prev => {
          const next = [...prev];
          const opp = next[msg.data.index];
          if (opp) {
            const oldPrice = opp.buyPrice;
            opp.buyPrice *= (1 + msg.data.noise);
            opp.sellPrice *= (1 + msg.data.noise + 0.0001); // Slight spread noise
            opp.spread = ((opp.sellPrice - opp.buyPrice) / opp.buyPrice) * 100;
            opp.profitPotential = (opp.sellPrice - opp.buyPrice) * 10;
            opp.trend = opp.buyPrice > oldPrice ? 'up' : 'down';
            opp.lastUpdated = Date.now();
          }
          return next;
        });
      }
    };

    const statsInterval = setInterval(() => {
      setPacketsPerSecond(packetRef.current);
      packetRef.current = 0;
    }, 1000);

    return () => {
      socket.disconnect();
      clearInterval(statsInterval);
    };
  }, [isLive]);

  // --- Bot Logic ---
  useEffect(() => {
    if (isAutoTrading && opportunities.length > 0 && streamStatus === 'connected') {
      const best = opportunities.find(o => 
        o.profitPotential >= autoTradeThreshold && 
        !tradeStatuses[o.id] &&
        (deepScanMode ? o.liquidityDepth === 'High' : true)
      );
      if (best) handleTrade(best);
    }
  }, [isAutoTrading, opportunities, autoTradeThreshold, streamStatus, deepScanMode]);

  const handleTrade = async (opp: ArbitrageOpportunity) => {
    if (tradeStatuses[opp.id] === 'transmitting' || tradeStatuses[opp.id] === 'filled') return;
    setTradeStatuses(prev => ({ ...prev, [opp.id]: 'transmitting' }));

    try {
      const response = await cexApi.executeArbitrageOrder(opp.pair, opp.buyExchange, opp.sellExchange, opp.buyPrice, opp.sellPrice, 1);
      if (response.success) {
        setTradeStatuses(prev => ({ ...prev, [opp.id]: 'filled' }));
        setHistory(prev => [...prev, {
          id: response.txId,
          pair: opp.pair,
          buyExchange: opp.buyExchange,
          sellExchange: opp.sellExchange,
          profit: response.netProfit,
          spread: opp.spread,
          tradeVolume: opp.buyPrice,
          timestamp: Date.now(),
          status: 'filled'
        }]);
        setBotXp(prev => Math.min(100, prev + 5));
      } else {
        setTradeStatuses(prev => ({ ...prev, [opp.id]: 'failed' }));
      }
      setTimeout(() => setTradeStatuses(prev => {
        const next = { ...prev };
        delete next[opp.id];
        return next;
      }), 5000);
    } catch (e) {
      setTradeStatuses(prev => ({ ...prev, [opp.id]: 'failed' }));
    }
  };

  const handleUpgrade = async () => {
    if (botXp < 100 || isUpgrading) return;
    setIsUpgrading(true);
    try {
      await new Promise(resolve => setTimeout(resolve, 3000));
      setBotLevel(prev => prev + 1);
