import { GoogleGenAI, Type } from "@google/genai";
import { OptimizationResult } from "../types";

export interface AiResponse {
  text: string;
  sources?: { title: string; uri: string }[];
  isThinking?: boolean;
}

export const generateAiResponse = async (
  prompt: string,
  context: string,
  history: { role: string; text: string }[]
): Promise<AiResponse> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const lowerPrompt = prompt.toLowerCase();
    const isAudit = /audit|verify|check|calculate|risk|slippage|mev|reason|strategy|plan|liquidity/i.test(lowerPrompt);

    // Use Gemini 3 Flash for quick queries, Gemini 3 Pro for complex logic
    const modelName = isAudit ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview'; 
    const config: any = { 
      tools: [{ googleSearch: {} }],
      systemInstruction: `You are Nexus Core, a world-class AI market overseer and high-frequency trading architect. 
      Your purpose is to provide "Alpha" insights while strictly enforcing capital protection protocols. 
      Context: ${context}. 
      Market status: Real-time Order Book analysis active. 
      Guidelines:
      1. Be concise and technical.
      2. If asked to audit, use deep reasoning to find MEV risks.
      3. Focus on CEX arbitrage spreads and DEX flash loan routes.
      4. Always assume high volatility environment.`
    };

    if (isAudit) {
      config.thinkingConfig = { thinkingBudget: 2048 };
    }

    const recentHistory = history.slice(-6).map(h => `${h.role === 'user' ? 'OPERATOR' : 'NEXUS'}: ${h.text}`).join('\n');
    const fullPrompt = `${recentHistory}\n\nOPERATOR QUERY: ${prompt}`;

    const response = await ai.models.generateContent({
      model: modelName,
      contents: fullPrompt,
      config: config
    });

    let sources: { title: string; uri: string }[] = [];
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (groundingChunks) {
      groundingChunks.forEach((chunk: any) => {
        if (chunk.web?.uri) {
          sources.push({ title: chunk.web.title || "Nexus Intelligence Source", uri: chunk.web.uri });
        }
      });
    }

    return {
      text: response.text || "Nexus Core: Request processed successfully.",
      sources: sources.length > 0 ? sources : undefined,
      isThinking: isAudit
    };
  } catch (error) {
    console.error("Gemini API Error:", error);
    return { text: "Nexus Core Alert: Encryption handshake failed. Retrying neural link..." };
  }
};

/**
 * Uses Gemini to analyze performance data and suggest parameter optimizations.
 */
export const getNeuralOptimization = async (
  marketData: string,
  performanceHistory: string
): Promise<OptimizationResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Perform a neural optimization for a high-frequency CEX arbitrage bot.

      CURRENT MARKET STATE:
      ${marketData}

      PERFORMANCE LOGS:
      ${performanceHistory}

      Analyze the win/loss ratio and current spreads. Recommend:
      1. suggestedThreshold: The dollar profit minimum per trade to maximize net gains.
      2. deepScanRecommended: Whether to enable deep order book filtering (reduce noise) or fast scan (catch small ticks).
      3. reasoning: A concise 1-sentence logic for the change.
      4. confidenceScore: 0.0 to 1.0.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            suggestedThreshold: { type: Type.NUMBER },
            deepScanRecommended: { type: Type.BOOLEAN },
            reasoning: { type: Type.STRING },
            confidenceScore: { type: Type.NUMBER }
          },
          required: ["suggestedThreshold", "deepScanRecommended", "reasoning", "confidenceScore"]
        }
      }
    });

    const result = JSON.parse(response.text || "{}");
    return result as OptimizationResult;
  } catch (error) {
    console.error("Optimization failed:", error);
    throw error;
  }
};

