/**
 * MockWebSocket Class
 * Simulates a real WebSocket connection with life-cycle events and data streams.
 */
class NexusWebSocket {
  private onMessageCallback: (data: any) => void = () => {};
  private onStatusCallback: (status: 'connected' | 'connecting' | 'stalled') => void = () => {};
  private interval: any = null;
  private status: 'connected' | 'connecting' | 'stalled' = 'connecting';

  constructor(
    onMessage: (data: any) => void,
    onStatusChange: (status: 'connected' | 'connecting' | 'stalled') => void
  ) {
    this.onMessageCallback = onMessage;
    this.onStatusCallback = onStatusChange;
    this.connect();
  }

  connect() {
    this.status = 'connecting';
    this.onStatusCallback(this.status);

    // Simulate connection handshake
    setTimeout(() => {
      this.status = 'connected';
      this.onStatusCallback(this.status);
      this.startStreaming();
    }, 1500);
  }

  private startStreaming() {
    this.interval = setInterval(() => {
      // Simulate occasional network stalls
      if (Math.random() < 0.01 && this.status === 'connected') {
        this.status = 'stalled';
        this.onStatusCallback(this.status);
        setTimeout(() => {
          this.status = 'connected';
          this.onStatusCallback(this.status);
        }, 2000);
        return;
      }

      if (this.status === 'connected') {
        // Stream Ticker Data
        this.onMessageCallback({
          type: 'TICKER_UPDATE',
          data: {
            index: Math.floor(Math.random() * INITIAL_TICKER.length),
            delta: (Math.random() * 0.001) - 0.0005
          }
        });

        // Stream Arbitrage Order Book Depth
        if (Math.random() > 0.4) {
          this.onMessageCallback({
            type: 'ARB_DEPTH_UPDATE',
            data: {
              index: Math.floor(Math.random() * INITIAL_ARB_OPPS.length),
              noise: (Math.random() * 0.0006) - 0.0003,
              bidWall: Math.floor(Math.random() * 100),
              askWall: Math.floor(Math.random() * 100)
            }
          });
        }
      }
    }, 150); // High frequency updates
  }

  disconnect() {
    if (this.interval) clearInterval(this.interval);
    this.status = 'stalled';
    this.onStatusCallback(this.status);
  }
}

const CexDashboard: React.FC = () => {
  // --- States ---
  const [opportunities, setOpportunities] = useState<ExtendedOpportunity[]>(
    INITIAL_ARB_OPPS.map(o => ({ 
      ...o, 
      lastUpdated: 0, 
      liquidityDepth: 'Medium',
      bidWall: 50,
      askWall: 50 
    }))
  );
  const [tickerData, setTickerData] = useState<TickerItem[]>(INITIAL_TICKER);
  const [tradeStatuses, setTradeStatuses] = useState<Record<string, 'transmitting' | 'filled' | 'failed'>>({});
  const [streamStatus, setStreamStatus] = useState<'connected' | 'connecting' | 'stalled'>('connecting');
  const [pps, setPps] = useState(0);
  const [isLive, setIsLive] = useState(true);

  // Trading Params
  const [autoTradeThreshold, setAutoTradeThreshold] = useState(150);
  const [deepScanMode, setDeepScanMode] = useState(false);
  const [isAutoTrading, setIsAutoTrading] = useState(false);

  // Optimization
  const [isOptimizing, setIsOptimizing] = useState(false);
  const [lastOptResult, setLastOptResult] = useState<OptimizationResult | null>(null);

  const [history, setHistory] = useState<{
    id: string;
    pair: string;
    profit: number;
    timestamp: number;
    status: 'filled' | 'failed';
  }[]>([]);

  const packetCounterRef = useRef(0);
  const socketRef = useRef<NexusWebSocket | null>(null);

  // --- WebSocket Lifecycle ---
  useEffect(() => {
    if (!isLive) {
      socketRef.current?.disconnect();
      setStreamStatus('stalled');
      return;
    }

    const socket = new NexusWebSocket(
      (msg) => {
        packetCounterRef.current++;

        if (msg.type === 'TICKER_UPDATE') {
          setTickerData(prev => prev.map((item, idx) => 
            idx === msg.data.index 
              ? { ...item, price: item.price * (1 + msg.data.delta), lastUpdate: Date.now() } 
              : item
          ));
        }

        if (msg.type === 'ARB_DEPTH_UPDATE') {
          setOpportunities(prev => prev.map((opp, idx) => {
            if (idx === msg.data.index) {
              const oldBuy = opp.buyPrice;
              const newBuy = opp.buyPrice * (1 + msg.data.noise);
              const newSell = opp.sellPrice * (1 + msg.data.noise + 0.0001);
              const totalWall = msg.data.bidWall + msg.data.askWall;

              return {
                ...opp,
                buyPrice: newBuy,
                sellPrice: newSell,
                spread: ((newSell - newBuy) / newBuy) * 100,
                profitPotential: (newSell - newBuy) * 10,
                bidWall: msg.data.bidWall,
                askWall: msg.data.askWall,
                trend: newBuy > oldBuy ? 'up' : 'down',
                lastUpdated: Date.now(),
                liquidityDepth: totalWall > 140 ? 'High' : totalWall > 80 ? 'Medium' : 'Low'
              };
            }
            return opp;
          }));
        }
      },
      (status) => setStreamStatus(status)
    );

    socketRef.current = socket;

    const statsInterval = setInterval(() => {
      setPps(packetCounterRef.current);
      packetCounterRef.current = 0;
    }, 1000);

    return () => {
      socket.disconnect();
      clearInterval(statsInterval);
    };
  }, [isLive]);

  const handleTrade = async (opp: ArbitrageOpportunity) => {
    if (tradeStatuses[opp.id]) return;
    setTradeStatuses(prev => ({ ...prev, [opp.id]: 'transmitting' }));

    try {
      const res = await cexApi.executeArbitrageOrder(opp.pair, opp.buyExchange, opp.sellExchange, opp.buyPrice, opp.sellPrice, 1);
      if (res.success) {
        setHistory(prev => [...prev, {
          id: res.txId,
          pair: opp.pair,
          profit: res.netProfit,
          timestamp: Date.now(),
          status: 'filled'
        }]);
      }
      setTradeStatuses(prev => ({ ...prev, [opp.id]: res.success ? 'filled' : 'failed' }));
    } catch (e) {
      setTradeStatuses(prev => ({ ...prev, [opp.id]: 'failed' }));
    } finally {
      setTimeout(() => setTradeStatuses(prev => {
        const n = { ...prev };
        delete n[opp.id];
        return n;
      }), 3000);
    }
  };

  const runNeuralOptimization = async () => {
    setIsOptimizing(true);
    try {
      const marketData = opportunities.map(o => `${o.pair}: ${o.spread.toFixed(2)}%`).join(', ');
      const perfHistory = history.slice(-5).map(h => `${h.pair}: $${h.profit.toFixed(2)}`).join(', ');
      const result = await getNeuralOptimization(marketData, perfHistory);
      setLastOptResult(result);
    } catch (error) {
      console.error("Optimization error:", error);
    } finally {
      setIsOptimizing(false);
    }
  };

  const applyOptimization = () => {
    if (lastOptResult) {
      setAutoTradeThreshold(lastOptResult.suggestedThreshold);
      setDeepScanMode(lastOptResult.deepScanRecommended);
      setLastOptResult(null);
      if ((window as any).triggerNexusAi) {
        (window as any).triggerNexusAi(`[STRATEGY SYNC] AI Core adjusted threshold to $${lastOptResult.suggestedThreshold} and set scan mode to ${lastOptResult.deepScanRecommended ? 'DEEP' : 'FAST'}.`);
      }
    }
  };

  const chartData = useMemo(() => history.map((item, index) => ({
    time: new Date(item.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
    cumulative: parseFloat(history.slice(0, index + 1).reduce((acc, curr) => acc + (curr.status === 'filled' ? curr.profit : 0), 0).toFixed(2))
  })), [history]);

  const totalProfit = history.reduce((acc, curr) => acc + (curr.status === 'filled' ? curr.profit : 0), 0);

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* WebSocket Powered Ticker Feed */}
      <div className="bg-slate-900/60 border-y border-slate-800 py-3 overflow-hidden shadow-inner backdrop-blur-sm">
