              <span className="text-slate-500 font-bold tracking-tighter uppercase">{t.symbol}/USDT</span>
              <span className={`font-black transition-all duration-300 ${Date.now() - (t.lastUpdate || 0) < 400 ? 'text-primary' : 'text-white'}`}>
                ${t.price.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
              </span>
