import { GoogleGenAI, Type } from "@google/genai";
import { OptimizationResult } from "../types";

export interface AiResponse {
  text: string;
  sources?: { title: string; uri: string }[];
  isThinking?: boolean;
}

export const generateAiResponse = async (
  prompt: string,
  context: string,
  history: { role: string; text: string }[]
): Promise<AiResponse> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const lowerPrompt = prompt.toLowerCase();
    // Detect complex queries that need deeper reasoning
    const isDeepAudit = /audit|verify|check|calculate|risk|mev|liquidity|math|complex|strategy/i.test(lowerPrompt);

    const modelName = isDeepAudit ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview'; 
    const config: any = { 
      tools: [{ googleSearch: {} }],
      systemInstruction: `You are the Nexus Neural Core, the advanced AI overseer of a hybrid CEX/DEX trading terminal. 
      Your purpose is to identify Alpha opportunities, calculate arbitrage efficiency, and audit DeFi flash loan routes for MEV risks.

      CURRENT TERMINAL CONTEXT: ${context}

      Operational Guidelines:
      1. Provide technical, high-precision responses using financial terminology.
      2. If asked for a "Smart Audit", calculate slippage, gas costs (Gwei), and potential profit/loss scenarios.
      3. For CEX arbitrage, focus on order book depth and exchange latency.
      4. For DEX flash loans, analyze AMM curve mechanics and routing efficiency.
      5. Always maintain a persona of a top-tier algorithmic trading architect.`
    };

    if (isDeepAudit) {
      config.thinkingConfig = { thinkingBudget: 4096 };
    }

    const recentHistory = history.slice(-8).map(h => `${h.role === 'user' ? 'OPERATOR' : 'NEXUS'}: ${h.text}`).join('\n');
    const fullPrompt = `${recentHistory}\n\n[SYSTEM STATE: ${context}]\nOPERATOR COMMAND: ${prompt}`;

    const response = await ai.models.generateContent({
      model: modelName,
      contents: fullPrompt,
      config: config
    });

    let sources: { title: string; uri: string }[] = [];
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (groundingChunks) {
      groundingChunks.forEach((chunk: any) => {
        if (chunk.web?.uri) {
          sources.push({ title: chunk.web.title || "Nexus Data Stream", uri: chunk.web.uri });
        }
      });
    }

    return {
      text: response.text || "Neural handshake failed. Please re-issue command.",
      sources: sources.length > 0 ? sources : undefined,
      isThinking: isDeepAudit
    };
  } catch (error) {
    console.error("AI Core Error:", error);
    return { text: "CRITICAL ERROR: Nexus Core neural link severed. Check API_KEY connectivity." };
  }
};

export const getNeuralOptimization = async (
  marketData: string,
  performanceHistory: string
): Promise<OptimizationResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Execute parameter optimization for the Nexus Arbitrage Engine.

      MARKET FEED: ${marketData}
      HISTORY: ${performanceHistory}

      Return a JSON configuration for:
      1. suggestedThreshold (USD profit min)
      2. deepScanRecommended (Boolean for order book filtering)
      3. reasoning (Technical justification)
      4. confidenceScore (0.0-1.0)`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            suggestedThreshold: { type: Type.NUMBER },
            deepScanRecommended: { type: Type.BOOLEAN },
            reasoning: { type: Type.STRING },
            confidenceScore: { type: Type.NUMBER }
          },
          required: ["suggestedThreshold", "deepScanRecommended", "reasoning", "confidenceScore"]
        }
      }
    });

    return JSON.parse(response.text || "{}") as OptimizationResult;
  } catch (error) {
    console.error("Neural Opt Failed:", error);
    throw error;
  }
};

