const App: React.FC = () => {
  const [activeView, setActiveView] = useState<'CEX' | 'DEX'>('CEX');
  const [isWalletModalOpen, setIsWalletModalOpen] = useState(false);
  const [activeWallet, setActiveWallet] = useState<(Wallet & { isValidated?: boolean }) | null>(null);
  const [connectionError, setConnectionError] = useState<string | null>(null);
  const [isValidating, setIsValidating] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Auto-Save & Hydration
  useEffect(() => {
    const savedView = localStorage.getItem('nexus_active_view') as 'CEX' | 'DEX';
    if (savedView) setActiveView(savedView);

    const savedWalletId = localStorage.getItem('nexus_connected_wallet_id');
    const savedAddress = localStorage.getItem('nexus_wallet_address');
    if (savedWalletId && savedAddress) {
      const wallet = WALLETS.find(w => w.id === savedWalletId);
      if (wallet) {
        setActiveWallet({
          ...wallet,
          address: savedAddress,
          balance: localStorage.getItem('nexus_wallet_balance') || '0.00 ETH',
          connected: true,
          isValidated: true,
          tier: 'Neural'
        });
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('nexus_active_view', activeView);
  }, [activeView]);

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const handleConnectWallet = async (wallet: Wallet) => {
    setConnectionError(null);
    setIsValidating(true);

    try {
      let connectionData: Partial<Wallet> = {};

      if (wallet.id === 'metamask' && (window as any).ethereum) {
        const ethereum = (window as any).ethereum;
        const provider = new BrowserProvider(ethereum);
        await provider.send("eth_requestAccounts", []);
        const signer = await provider.getSigner();
        const address = await signer.getAddress();
        const balanceBigInt = await provider.getBalance(address);
        const formattedAddress = `${address.slice(0, 6)}...${address.slice(-4)}`;
        const formattedBalance = `${parseFloat(formatEther(balanceBigInt)).toFixed(4)} ETH`;

        connectionData = {
          address: formattedAddress,
          balance: formattedBalance,
          tier: 'Elite',
          trustScore: 99.4,
          lastAudit: Date.now()
        };

        // Auto-save connection
        localStorage.setItem('nexus_connected_wallet_id', wallet.id);
        localStorage.setItem('nexus_wallet_address', formattedAddress);
        localStorage.setItem('nexus_wallet_balance', formattedBalance);
      } else {
        await new Promise(resolve => setTimeout(resolve, 1800));
        const mockAddress = '0x71C...9A21';
        const mockBalance = wallet.id === 'phantom' ? '124.5 SOL' : '14.5 ETH';
        connectionData = {
          address: mockAddress,
          balance: mockBalance,
          tier: 'Neural',
          trustScore: 98.7,
          lastAudit: Date.now()
        };
        localStorage.setItem('nexus_connected_wallet_id', wallet.id);
        localStorage.setItem('nexus_wallet_address', mockAddress);
        localStorage.setItem('nexus_wallet_balance', mockBalance);
      }

      setActiveWallet({
        ...wallet,
        ...connectionData,
        connected: true,
        isValidated: true
      });
      setIsValidating(false);

    } catch (error: any) {
      setIsValidating(false);
      setConnectionError(error?.message || "Validation failed: Nexus secure handshake timed out.");
      throw error;
    }
  };

  const handleDisconnect = () => {
    setActiveWallet(null);
    localStorage.removeItem('nexus_connected_wallet_id');
    localStorage.removeItem('nexus_wallet_address');
    localStorage.removeItem('nexus_wallet_balance');
  };

  return (
    <div className="min-h-screen bg-background text-slate-200 font-sans selection:bg-primary/30 overflow-x-hidden">
      <Navbar 
        activeView={activeView} 
        setActiveView={setActiveView} 
        activeWallet={activeWallet}
        onConnectClick={() => setIsWalletModalOpen(true)}
        isOnline={isOnline}
      />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10 pb-32">
        <div className="mb-12 animate-in fade-in slide-in-from-top-6 duration-700">
          <div className="flex items-center gap-4 mb-3">
             <div className="w-2.5 h-10 bg-gradient-to-b from-primary to-purple-600 rounded-full" />
             <h2 className="text-5xl font-black text-white tracking-tighter uppercase italic">
               {activeView === 'CEX' ? 'Neural Scanner' : 'DeFi Terminal'}
             </h2>
          </div>
          <p className="text-slate-500 font-black uppercase tracking-widest text-[10px] border-l border-slate-800 pl-6 ml-1.5 opacity-60">
            {activeView === 'CEX' 
              ? 'Institutional-grade Arbitrage Cluster • Real-time Order Book Parity' 
              : 'Permissionless Execution Protocol • Flash Loan Routing v4.2'}
          </p>
        </div>

        {activeView === 'CEX' ? <CexDashboard /> : <DexDashboard />}
      </main>

      <WalletModal 
        isOpen={isWalletModalOpen} 
        onClose={() => { setIsWalletModalOpen(false); setConnectionError(null); }}
        activeWallet={activeWallet}
        onConnect={handleConnectWallet}
        onDisconnect={handleDisconnect}
        error={connectionError}
        isValidating={isValidating}
      />
    </div>
  );
};

