/**
 * Advanced NexusStreamEngine
 * Handles multi-feed simulation with latency and heartbeat.
 */
class NexusStreamEngine {
  private onMessageCallback: (data: any) => void;
  private onStatusCallback: (status: 'connected' | 'connecting' | 'stalled') => void;
  private interval: any = null;
  private heartbeat: any = null;
  private status: 'connected' | 'connecting' | 'stalled' = 'connecting';
  private latency: number = 2;

  constructor(
    onMessage: (data: any) => void,
    onStatusChange: (status: 'connected' | 'connecting' | 'stalled') => void
  ) {
    this.onMessageCallback = onMessage;
    this.onStatusCallback = onStatusChange;
    this.connect();
  }

  connect() {
    this.status = 'connecting';
    this.onStatusCallback(this.status);

    setTimeout(() => {
      this.status = 'connected';
      this.onStatusCallback(this.status);
      this.startStreams();
    }, 1200);
  }

  private startStreams() {
    this.interval = setInterval(() => {
      if (this.status !== 'connected') return;

      // Occasional network turbulence
      if (Math.random() < 0.005) {
        this.status = 'stalled';
        this.onStatusCallback(this.status);
        setTimeout(() => this.reconnect(), 1500);
        return;
      }

      // Latency jitter
      this.latency = Math.floor(Math.random() * 12) + 2;

      // Stream Feed 1: Market Ticker
      this.onMessageCallback({
        type: 'TICKER',
        data: {
          index: Math.floor(Math.random() * INITIAL_TICKER.length),
          delta: (Math.random() * 0.0008) - 0.0004
        }
      });

      // Stream Feed 2: Arb Scanner
      if (Math.random() > 0.4) {
        this.onMessageCallback({
          type: 'SCANNER',
          data: {
            index: Math.floor(Math.random() * INITIAL_ARB_OPPS.length),
            noise: (Math.random() * 0.0004) - 0.0002,
            walls: [Math.floor(Math.random() * 100), Math.floor(Math.random() * 100)],
            latency: this.latency
          }
        });
      }
    }, 120);

    this.heartbeat = setInterval(() => {
      this.onMessageCallback({ type: 'HEARTBEAT', timestamp: Date.now() });
    }, 2000);
  }

  private reconnect() {
    this.status = 'connecting';
    this.onStatusCallback(this.status);
    setTimeout(() => {
      this.status = 'connected';
      this.onStatusCallback(this.status);
    }, 800);
  }

  disconnect() {
    clearInterval(this.interval);
    clearInterval(this.heartbeat);
    this.status = 'stalled';
    this.onStatusCallback(this.status);
  }
}

const CexDashboard: React.FC = () => {
  const [opportunities, setOpportunities] = useState<ExtendedOpportunity[]>(
    INITIAL_ARB_OPPS.map(o => ({ 
      ...o, lastUpdated: 0, liquidityDepth: 'Medium', bidWall: 50, askWall: 50, latency: 4 
    }))
  );
  const [tickerData, setTickerData] = useState<TickerItem[]>(INITIAL_TICKER);
  const [streamStatus, setStreamStatus] = useState<'connected' | 'connecting' | 'stalled'>('connecting');
  const [lastHeartbeat, setLastHeartbeat] = useState<number>(Date.now());
  const [tradeStatuses, setTradeStatuses] = useState<Record<string, 'executing' | 'filled' | 'failed'>>({});
  const [isLive, setIsLive] = useState(true);
  const [autoPilot, setAutoPilot] = useState(false);

  const [history, setHistory] = useState<any[]>([]);
  const packetRef = useRef(0);

  useEffect(() => {
    if (!isLive) return;

    const engine = new NexusStreamEngine(
      (msg) => {
        packetRef.current++;
        if (msg.type === 'HEARTBEAT') setLastHeartbeat(msg.timestamp);
        if (msg.type === 'TICKER') {
          setTickerData(prev => {
            const next = [...prev];
            if (next[msg.data.index]) {
              next[msg.data.index] = { 
                ...next[msg.data.index], 
                price: next[msg.data.index].price * (1 + msg.data.delta),
                lastUpdate: Date.now() 
              };
            }
            return next;
          });
        }
        if (msg.type === 'SCANNER') {
          setOpportunities(prev => {
            const next = [...prev];
            const opp = next[msg.data.index];
            if (opp) {
              const oldPrice = opp.buyPrice;
              opp.buyPrice *= (1 + msg.data.noise);
              opp.sellPrice *= (1 + msg.data.noise + 0.0001);
              opp.spread = ((opp.sellPrice - opp.buyPrice) / opp.buyPrice) * 100;
              opp.bidWall = msg.data.walls[0];
              opp.askWall = msg.data.walls[1];
              opp.latency = msg.data.latency;
              opp.lastUpdated = Date.now();
              opp.trend = opp.buyPrice > oldPrice ? 'up' : 'down';
            }
            return next;
          });
        }
      },
      setStreamStatus
    );

    return () => engine.disconnect();
