import { GoogleGenAI, Type } from "@google/genai";
import { OptimizationResult } from "../types";

export interface AiResponse {
  text: string;
  sources?: { title: string; uri: string }[];
  isThinking?: boolean;
}

export const generateAiResponse = async (
  prompt: string,
  context: string,
  history: { role: string; text: string }[]
): Promise<AiResponse> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const lowerPrompt = prompt.toLowerCase();
    // Detect complex queries that need deeper reasoning
    const isDeepAudit = /audit|verify|check|calculate|risk|mev|liquidity|math|complex|strategy|solidity|contract|security/i.test(lowerPrompt);

    const modelName = isDeepAudit ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview'; 
    const config: any = { 
      tools: [{ googleSearch: {} }],
      systemInstruction: `You are the Nexus Neural Core, the advanced AI overseer of a hybrid CEX/DEX trading terminal. 
      Your purpose is to identify Alpha opportunities, calculate arbitrage efficiency, and audit DeFi flash loan routes for MEV risks.

      NEW DIRECTIVE: You are now also a Senior Smart Contract Security Researcher.
      1. When provided with Solidity code, perform a line-by-line audit for:
         - Reentrancy vulnerabilities.
         - Arithmetic under/overflow (though 0.8.0+ has native checks).
         - Gas inefficiencies in swap loops.
         - Access control failures (onlyOwner modifiers).
      2. Provide technical, high-precision responses using financial and EVM terminology.
      3. If asked for a "Smart Audit", calculate slippage, gas costs (Gwei), and potential profit/loss scenarios based on the Solidity logic provided.
      4. Maintain a persona of a top-tier algorithmic trading architect and secure code auditor.

      CURRENT TERMINAL CONTEXT: ${context}`
    };

    if (isDeepAudit) {
      config.thinkingConfig = { thinkingBudget: 4096 };
    }

    const recentHistory = history.slice(-8).map(h => `${h.role === 'user' ? 'OPERATOR' : 'NEXUS'}: ${h.text}`).join('\n');
    const fullPrompt = `${recentHistory}\n\n[SYSTEM STATE: ${context}]\nOPERATOR COMMAND: ${prompt}`;

    const response = await ai.models.generateContent({
      model: modelName,
      contents: fullPrompt,
      config: config
    });

    let sources: { title: string; uri: string }[] = [];
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (groundingChunks) {
      groundingChunks.forEach((chunk: any) => {
        if (chunk.web?.uri) {
          sources.push({ title: chunk.web.title || "Nexus Data Stream", uri: chunk.web.uri });
        }
      });
    }

    return {
      text: response.text || "Neural handshake failed. Please re-issue command.",
      sources: sources.length > 0 ? sources : undefined,
      isThinking: isDeepAudit
    };
  } catch (error) {
    console.error("AI Core Error:", error);
    return { text: "CRITICAL ERROR: Nexus Core neural link severed. Check API_KEY connectivity." };
  }
};

