class NexusStreamEngine {
  private onMessageCallback: (data: any) => void;
  private onStatusCallback: (status: 'connected' | 'connecting' | 'stalled') => void;
  private interval: any = null;
  private heartbeat: any = null;
  private status: 'connected' | 'connecting' | 'stalled' = 'connecting';
  private latency: number = 2;

  constructor(
    onMessage: (data: any) => void,
    onStatusChange: (status: 'connected' | 'connecting' | 'stalled') => void
  ) {
    this.onMessageCallback = onMessage;
    this.onStatusCallback = onStatusChange;
    this.connect();
  }

  connect() {
    this.status = 'connecting';
    this.onStatusCallback(this.status);

    setTimeout(() => {
      this.status = 'connected';
      this.onStatusCallback(this.status);
      this.startStreams();
    }, 1200);
  }

  private startStreams() {
    this.interval = setInterval(() => {
      if (this.status !== 'connected') return;

      if (Math.random() < 0.005) {
        this.status = 'stalled';
        this.onStatusCallback(this.status);
        setTimeout(() => this.reconnect(), 1500);
        return;
      }

      this.latency = Math.floor(Math.random() * 12) + 2;

      this.onMessageCallback({
        type: 'TICKER',
        data: {
          index: Math.floor(Math.random() * INITIAL_TICKER.length),
          delta: (Math.random() * 0.0008) - 0.0004
        }
      });

      if (Math.random() > 0.4) {
        this.onMessageCallback({
          type: 'SCANNER',
          data: {
            index: Math.floor(Math.random() * INITIAL_ARB_OPPS.length),
            noise: (Math.random() * 0.0004) - 0.0002,
            walls: [Math.floor(Math.random() * 100), Math.floor(Math.random() * 100)],
            volumes: [Math.random() * 500, Math.random() * 500],
            liquidity: ['High', 'Medium', 'Low'][Math.floor(Math.random() * 3)],
            latency: this.latency
          }
        });
      }
    }, 120);

    this.heartbeat = setInterval(() => {
      this.onMessageCallback({ type: 'HEARTBEAT', timestamp: Date.now() });
    }, 2000);
  }

  private reconnect() {
    this.status = 'connecting';
    this.onStatusCallback(this.status);
    setTimeout(() => {
      this.status = 'connected';
      this.onStatusCallback(this.status);
    }, 800);
  }

  disconnect() {
    clearInterval(this.interval);
    clearInterval(this.heartbeat);
    this.status = 'stalled';
    this.onStatusCallback(this.status);
  }
}

