                 <tab.icon className="w-4 h-4" />
                 {tab.label}
                 {tab.badge && tab.badge > 0 && (
                   <span className="absolute -top-1 -right-1 flex h-4 w-4 items-center justify-center rounded-full bg-rose-500 text-[8px] text-white font-black animate-bounce">
                     {tab.badge}
