                           <span className={`text-3xl font-mono font-black drop-shadow-[0_0_10px_rgba(16,185,129,0.5)] ${threats.length > 0 ? 'text-amber-400' : 'text-emerald-400'}`}>
                             {threats.length === 0 ? '100%' : `${(99.8 - (threats.length * 5)).toFixed(1)}%`}
                           </span>
                        </div>
                     </div>

