/**
 * NexusStreamEngine
 * Simulates a robust WebSocket connection for real-time market data streaming.
 * Handles connection states, heartbeats, and data packet parsing.
 */
class NexusStreamEngine {
  private onMessage: (data: any) => void;
  private onStatus: (status: 'connected' | 'connecting' | 'stalled') => void;
  private intervals: NodeJS.Timeout[] = [];
  private isConnected = false;

  constructor(
    onMessage: (data: any) => void,
    onStatus: (status: 'connected' | 'connecting' | 'stalled') => void
  ) {
    this.onMessage = onMessage;
    this.onStatus = onStatus;
    this.connect();
  }

  public connect() {
    this.clearStreams();
    this.onStatus('connecting');

    // Simulate handshake latency
    setTimeout(() => {
      this.isConnected = true;
      this.onStatus('connected');
      this.startStreams();
    }, 1200);
  }

  private startStreams() {
    if (!this.isConnected) return;

    // 1. High-frequency Ticker Feed (100ms)
    this.intervals.push(setInterval(() => {
      const idx = Math.floor(Math.random() * INITIAL_TICKER.length);
      const volatility = 0.0005; // 0.05% swing
      const delta = (Math.random() * volatility * 2) - volatility;

      this.onMessage({
        type: 'TICKER',
        data: { index: idx, delta }
      });
    }, 100));

    // 2. Arbitrage Opportunity Scanner (Simulating Order Book changes) (2s)
    this.intervals.push(setInterval(() => {
      if (Math.random() > 0.3) { // 70% chance to update
        const idx = Math.floor(Math.random() * INITIAL_ARB_OPPS.length);
        const noise = (Math.random() * 0.0004) - 0.0002;

        this.onMessage({
          type: 'SCANNER',
          data: {
            index: idx,
            noise,
            walls: [Math.floor(Math.random() * 90) + 10, Math.floor(Math.random() * 90) + 10],
            volumes: [Math.random() * 800 + 50, Math.random() * 800 + 50],
            liquidity: Math.random() > 0.6 ? 'High' : (Math.random() > 0.3 ? 'Medium' : 'Low'),
            latency: Math.floor(Math.random() * 15) + 2 // 2-17ms latency
          }
        });
      }
    }, 2000));

    // 3. Heartbeat & Connection Health (5s)
    this.intervals.push(setInterval(() => {
      // 5% chance of packet loss/stall simulation
      if (Math.random() < 0.05) {
        this.simulateStall();
      } else {
        this.onMessage({ type: 'HEARTBEAT', timestamp: Date.now() });
      }
    }, 5000));
  }

  private simulateStall() {
    this.onStatus('stalled');
    // Auto-recover after 2 seconds
    setTimeout(() => {
      if (this.isConnected) {
        this.onStatus('connected');
      }
    }, 2000);
  }

  private clearStreams() {
    this.intervals.forEach(clearInterval);
    this.intervals = [];
  }

  public disconnect() {
    this.isConnected = false;
    this.clearStreams();
    this.onStatus('stalled');
  }
}

const CexDashboard: React.FC = () => {
  const [opportunities, setOpportunities] = useState<ExtendedOpportunity[]>(
    INITIAL_ARB_OPPS.map(o => ({ 
      ...o, 
      lastUpdated: 0, 
      liquidityDepth: 'Medium', 
      bidWall: 50, 
      askWall: 50, 
      bidVolume: 12.4, 
      askVolume: 10.8, 
      latency: 4, 
      securityScore: 92 
    }))
  );

  const [tickerData, setTickerData] = useState<TickerItem[]>(INITIAL_TICKER);
  const [streamStatus, setStreamStatus] = useState<'connected' | 'connecting' | 'stalled'>('connecting');
  const [lastHeartbeat, setLastHeartbeat] = useState<number>(Date.now());
  const [tradeStatuses, setTradeStatuses] = useState<Record<string, 'executing' | 'filled' | 'failed'>>({});
  const [isLive, setIsLive] = useState(true);
  const [autoPilot, setAutoPilot] = useState(false);
  const [neuralSentiment, setNeuralSentiment] = useState(72);

  const [history, setHistory] = useState<any[]>([]);

  // Websocket Integration
  useEffect(() => {
    if (!isLive) return;

    const engine = new NexusStreamEngine(
      (msg) => {
        if (msg.type === 'HEARTBEAT') {
          setLastHeartbeat(msg.timestamp);
          setNeuralSentiment(prev => {
            const drift = (Math.random() * 4) - 2;
            return Math.min(100, Math.max(0, prev + drift));
          });
        }

        if (msg.type === 'TICKER') {
          setTickerData(prev => {
            const next = [...prev];
            const item = next[msg.data.index];
            if (item) {
              next[msg.data.index] = { 
                ...item, 
                price: item.price * (1 + msg.data.delta),
                change: item.change + (msg.data.delta * 100), // Approximate daily change drift
                lastUpdate: Date.now() 
              };
            }
            return next;
          });
        }

        if (msg.type === 'SCANNER') {
          setOpportunities(prev => {
            const next = [...prev];
            const opp = next[msg.data.index];
            if (opp) {
              const oldPrice = opp.buyPrice;
              // Simulate price drift on exchanges
              opp.buyPrice *= (1 + msg.data.noise);
              opp.sellPrice *= (1 + msg.data.noise + 0.0001); // Slight arb drift

              // Recalculate metrics
              opp.spread = ((opp.sellPrice - opp.buyPrice) / opp.buyPrice) * 100;
              opp.bidWall = msg.data.walls[0];
              opp.askWall = msg.data.walls[1];
              opp.bidVolume = msg.data.volumes[0];
              opp.askVolume = msg.data.volumes[1];
              opp.liquidityDepth = msg.data.liquidity;
              opp.latency = msg.data.latency;
              opp.lastUpdated = Date.now();
              opp.trend = opp.buyPrice > oldPrice ? 'up' : 'down';

              // Dynamic Security Score Calculation
              // If spread is too high (suspicious) or walls are thin, lower score
              const spreadPenalty = opp.spread > 5 ? 20 : 0;
              const wallSkew = Math.abs(opp.bidWall - opp.askWall);
              const depthPenalty = opp.liquidityDepth === 'Low' ? 30 : (opp.liquidityDepth === 'Medium' ? 10 : 0);
              opp.securityScore = Math.max(0, Math.min(100, 100 - (wallSkew * 0.4) - depthPenalty - spreadPenalty));
            }
            return next;
          });
        }
      },
      setStreamStatus
    );

    return () => engine.disconnect();
  }, [isLive]);

  const triggerNeuralAudit = (opp: ExtendedOpportunity) => {
    if ((window as any).triggerNexusAi) {
