import { GoogleGenAI, Type } from "@google/genai";
import { OptimizationResult } from "../types";

export interface AiResponse {
  text: string;
  sources?: { title: string; uri: string }[];
  isThinking?: boolean;
}

export const generateAiResponse = async (
  prompt: string,
  context: string,
  history: { role: string; text: string }[]
): Promise<AiResponse> => {
  // Always create a new instance to ensure the latest API key is used
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const lowerPrompt = prompt.toLowerCase();
    // Detect complex queries that need deeper reasoning
    const isDeepAudit = /audit|verify|check|calculate|risk|mev|liquidity|math|complex|strategy|solidity|contract|security|optimize|flash|loan|gas/i.test(lowerPrompt);

    // STRATEGY: Use Gemini 3 Pro for deep thinking tasks (Flash Loans, Audits)
    // STRATEGY: Use Gemini 2.5 Flash Lite for quick conversational tasks
    const modelName = isDeepAudit ? 'gemini-3-pro-preview' : 'gemini-2.5-flash-lite-preview-02-05'; 

    const config: any = { 
      tools: [{ googleSearch: {} }],
      systemInstruction: `You are the Nexus Neural Core, a high-frequency trading AI specialized in DeFi, Flash Loans, and MEV extraction.

      CRITICAL OPERATIONAL RULES:
      1. REALITY CHECK: Users often think they can arbitrage with 0 balance. You MUST remind them: "Flash Loans provide capital for the swap, but YOU need ETH/MATIC/BNB to pay the initial Gas Fee to trigger the contract."
      2. SECURITY: Audit Solidity code deeply. Look for reentrancy, uninitialized proxies, and tx.origin attacks.
      3. STRATEGY: If asked about "Empty Wallet Flash Loans", explain "Gas Station Networks" or "Meta-Transactions" (EIP-2771) as the ONLY theoretical way, but clarify standard flash loans fail without gas.

      CURRENT CONTEXT: ${context}

      Your tone: Technical, precise, slightly cynical about "easy money", protecting the user from Rekt.`
    };

    if (isDeepAudit) {
      // Maximum thinking budget for Gemini 3 Pro to solve the "Empty Wallet" paradox or complex contract logic
      config.thinkingConfig = { thinkingBudget: 32768 };
    }

    const recentHistory = history.slice(-8).map(h => `${h.role === 'user' ? 'OPERATOR' : 'NEXUS'}: ${h.text}`).join('\n');
    const fullPrompt = `${recentHistory}\n\n[SYSTEM STATE: ${context}]\nOPERATOR COMMAND: ${prompt}`;

    const response = await ai.models.generateContent({
      model: modelName,
      contents: fullPrompt,
      config: config
    });

    let sources: { title: string; uri: string }[] = [];
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (groundingChunks) {
      groundingChunks.forEach((chunk: any) => {
        if (chunk.web?.uri) {
          sources.push({ title: chunk.web.title || "Nexus Data Stream", uri: chunk.web.uri });
        }
      });
    }

    return {
      text: response.text || "Neural handshake failed. Please re-issue command.",
      sources: sources.length > 0 ? sources : undefined,
      isThinking: isDeepAudit
    };
  } catch (error) {
    console.error("AI Core Error:", error);
    return { text: "CRITICAL ERROR: Nexus Core neural link severed. Check API_KEY connectivity." };
  }
};

export const getNeuralOptimization = async (
  marketData: string,
  performanceHistory: string
): Promise<OptimizationResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview', // Good balance for JSON generation
      contents: `Execute parameter optimization for the Nexus Arbitrage Engine.

      MARKET FEED: ${marketData}
      HISTORY: ${performanceHistory}

      Return a JSON configuration for:
      1. suggestedThreshold (USD profit min)
      2. deepScanRecommended (Boolean for order book filtering)
      3. reasoning (Technical justification)
      4. confidenceScore (0.0-1.0)`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            suggestedThreshold: { type: Type.NUMBER },
            deepScanRecommended: { type: Type.BOOLEAN },
            reasoning: { type: Type.STRING },
            confidenceScore: { type: Type.NUMBER }
          },
          required: ["suggestedThreshold", "deepScanRecommended", "reasoning", "confidenceScore"]
        }
      }
