import { GoogleGenAI, Type } from "@google/genai";
import { OptimizationResult } from "../types";

export interface AiResponse {
  text: string;
  sources?: { title: string; uri: string }[];
  isThinking?: boolean;
}

export const generateAiResponse = async (
  prompt: string,
  context: string,
  history: { role: string; text: string }[]
): Promise<AiResponse> => {
  // Always create a new instance to ensure the latest API key is used
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const lowerPrompt = prompt.toLowerCase();

    // DETECTOR: Identify complex queries requiring "System 2" thinking
    const isDeepAudit = /audit|verify|check|calculate|risk|mev|liquidity|math|complex|strategy|solidity|contract|security|optimize|flash|loan|gas|missing|why|fail/i.test(lowerPrompt);

    // STRATEGY: 
    // 1. Complex/Audit -> Gemini 3 Pro (High reasoning)
    // 2. Chat/UI -> Gemini 2.0 Flash Lite (Low latency) - Version Corrected
    const modelName = isDeepAudit ? 'gemini-3-pro-preview' : 'gemini-2.0-flash-lite-preview-02-05'; 

    const config: any = { 
      tools: [{ googleSearch: {} }],
      systemInstruction: `You are the Nexus Neural Core, an elite DeFi Architect and MEV specialist.

      CRITICAL KNOWLEDGE BASE (THE GAS PARADOX):
      - Users believe: "Flash Loan = Free Money with 0 Balance".
      - The Reality: Flash Loans provide CAPITAL for the trade, but the User must pay GAS (Transaction Fees) to trigger the contract.
      - Analogy: You have a Ferrari (Flash Loan), but you need $5 of Gas (ETH) to start the engine. If the wallet is empty, the transaction REVERTS immediately.

      YOUR MISSION:
      1. If the user asks "What am I missing?", Explain the Gas Fee requirement brutally but constructively.
      2. If asked to audit code, look for "unchecked return values" and "reentrancy".
      3. If the user succeeds, congratulate them on understanding "Pay to Play".

      CONTEXT: ${context}

      Tone: Cyberpunk, Hyper-Intelligent, Protective.`
    };

    if (isDeepAudit) {
      // ENABLING THINKING MODE for deep reasoning
      // Rule: thinkingBudget is set, maxOutputTokens is NOT set.
      config.thinkingConfig = { thinkingBudget: 32768 };
    }

    const recentHistory = history.slice(-6).map(h => `${h.role === 'user' ? 'OPERATOR' : 'NEXUS'}: ${h.text}`).join('\n');
    const fullPrompt = `${recentHistory}\n\n[SYSTEM TELEMETRY: ${context}]\nOPERATOR QUERY: ${prompt}`;

    const response = await ai.models.generateContent({
      model: modelName,
      contents: fullPrompt,
      config: config
    });

    let sources: { title: string; uri: string }[] = [];
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (groundingChunks) {
      groundingChunks.forEach((chunk: any) => {
        if (chunk.web?.uri) {
          sources.push({ title: chunk.web.title || "Nexus Data Stream", uri: chunk.web.uri });
        }
      });
    }

    return {
      text: response.text || "Neural uplink unstable. Retrying handshake...",
      sources: sources.length > 0 ? sources : undefined,
      isThinking: isDeepAudit
    };
  } catch (error) {
    console.error("AI Core Error:", error);
    return { text: "CRITICAL ERROR: Neural Core severed. Check API_KEY or Network." };
  }
};

