// STABILITY: Utility to retry operations with exponential backoff
async function retryWithBackoff<T>(
  operation: () => Promise<T>,
  retries: number = 3,
  delay: number = 1000
): Promise<T> {
  try {
    return await operation();
  } catch (error: any) {
    if (retries > 0 && (error.status === 503 || error.status === 429 || error.message?.includes('fetch failed'))) {
      console.warn(`[Nexus Neural Uplink] Connection unstable. Retrying in ${delay}ms...`);
      await new Promise(resolve => setTimeout(resolve, delay));
      return retryWithBackoff(operation, retries - 1, delay * 2);
    }
    throw error;
  }
}

export const generateAiResponse = async (
  prompt: string,
  context: string,
  history: { role: string; text: string }[]
): Promise<AiResponse> => {
  // Always create a new instance to ensure the latest API key is used
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const lowerPrompt = prompt.toLowerCase();

    // DETECTOR: Identify complex queries requiring "System 2" thinking
    const isDeepAudit = /audit|verify|check|calculate|risk|mev|liquidity|math|complex|strategy|solidity|contract|security|optimize|flash|loan|gas|missing|why|fail/i.test(lowerPrompt);

    // STRATEGY: 
    // 1. Complex/Audit -> Gemini 3 Pro (High reasoning)
